export const ABILITIES = [{"id":"FIR-01-F","familyId":"emberfox","mode":"football","name":"Blazing Resolve","category":"Self enhancement","activation":"Conditional charge","mechanic":"Rushing-earned charge; timed tackle-break immunity","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Completed official rushing attempts only. Three qualifying charges ignite for a future rushing carry. No receiving, returns or two-point charge/activation. A rushing attempt qualifies when its net gain exceeds the form threshold: Flaroo over 7 yards, Blazynx over 4 yards, Infernox any positive gain (whole yards: at least 8 / 5 / 1).","ruling":"N7b P2; spec §9 (encounter rule)","supersededRule":"Completed official rushing attempts only. Three qualifying charges ignite for a future rushing carry. No receiving, returns or two-point charge/activation. Positive whole-yard thresholds are in Progression."},{"section":"Targets / placement","rule":"Self as ball carrier on a rushing attempt"},{"section":"Core resolution","rule":"First eligible tackle begins one tackle encounter. Snapshot all defenders already within tackling reach, break their attempts, spend ignition; later arrivals can tackle normally. No one-second window. Consuming carry earns no new charge. Normal strip/fumble rules remain. Do not copy old Eruption's defender stun.","ruling":"N7b P2; spec §9 (encounter rule)","supersededRule":"First eligible tackle starts one live second of automatic tackle breaks, including multiple defenders reaching runner within that window. Charge consumed; consuming carry earns no new charge. Normal strip/fumble rules remain."},{"section":"Recharge / frequency","rule":"No separate cooldown. No second bar or charging while ignited; resume following carry. Two-point attempts neither charge nor trigger ignition. Existing fields still apply during conversions."},{"section":"Lifetime / persistence","rule":"Unused ignition and partial charge persist across possessions, halftime and overtime; reset per game; save/reload preserves."},{"section":"Exceptions / counterplay","rule":"No receiving/return charge or activation. Stuns, fields, forced movement, out of bounds, strips and fumbles still apply."},{"section":"Visuals","rule":"Visible three-part charge bar above monster; full charge engulfs body in flame."},{"section":"Progression / notes","rule":"Guaranteed tackle-break window is explicitly approved. Not the legacy Eruption flatten/stun."}],"ruling":"N7b P2; spec §9 (encounter rule)","values":{"minWholeYardsByStage":[8,5,1]}},{"id":"FIR-01-C","familyId":"emberfox","mode":"clash","name":"Stoke the Flame","category":"Retaliation","activation":"Three incoming attacks survived","mechanic":"Survive three attacks; immediate single-target retaliation","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"One charge per enemy direct-damage attack survived, including HP or shield damage. Multi-hit counts once. Delayed direct attacks count; misses, fully prevented zero damage, damage over time, counters and reactions do not."},{"section":"Targets / placement","rule":"Triggering attacker; if invalid, current opposing active monster"},{"section":"Core resolution","rule":"At three charges, immediate Fire counterburst outside normal turn; reset charge."},{"section":"Recharge / frequency","rule":"Three hits, no separate cooldown approved."},{"section":"Lifetime / persistence","rule":"Retain partial charge through rotations; reset each Clash."},{"section":"Exceptions / counterplay","rule":"At third charge must survive and be able to act immediately, otherwise consume charge with no queued retaliation. If Stunned blocks counter, consume Stoke charge but NOT Stunned duration. Only normal turns advance status. Invalid attacker redirects to opposing active monster. Counterburst is reaction damage; no reaction chain. Shared status system supersedes old Shock-skip consumption exception."},{"section":"Visuals","rule":"Three-charge heat indicator and fiery counterburst; detailed choreography pending."},{"section":"Progression / notes","rule":"Counterburst deals 60 / 70 / 80% of normal attack damage by Flaroo / Blazynx / Infernox, plus 0 / 5 / 10 / 15 percentage points by mastery. Normal type, damage-reduction and shield mitigation applies. No status or splash.","ruling":"N7b P1","supersededRule":"Damage scales by form/mastery. No status or splash."}],"ruling":"N7b P1","values":{"counterburstPctByStage":[60,70,80],"masteryBonusPts":[0,5,10,15]}},{"id":"FIR-02-F","familyId":"ashkit","mode":"football","name":"Impact Pyre","category":"Zone","activation":"Three tackle-play charges -> next defensive snap","mechanic":"Tackle-earned charge creates stationary Fire at owner next snap","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Three defensive SCRIMMAGE PLAYS with personally credited tackle/assist/sack fill bar, max1charge/play. No charge while full. At next participating defensive scrimmage snap create zone and empty bar. Punts/special teams do not spend/build it; readiness waits through possession changes."},{"section":"Targets / placement","rule":"Stationary field-aligned Fire rectangle centered at linebacker STARTING position on activation snap;6wide x4long. It does not follow owner."},{"section":"Core resolution","rule":"Create a 6-yard sideline-to-sideline width by 4-yard end-zone-to-end-zone length Fire zone."},{"section":"Recharge / frequency","rule":"Charge requirement REPLACES old3-defensive-play cooldown. Three qualifying tackle/assist/sack plays needed again. Spawn play cannot earn charge; resume afterward."},{"section":"Lifetime / persistence","rule":"1/2/3/4 completed plays by mastery, counting SPAWN play as first. Partial/full bar survives possession changes and halftime; created nonlegendary zone clears halftime, all game state clears actual game end."},{"section":"Exceptions / counterplay","rule":"Fire types immune. All other types both teams slowed only inside. Uses global zone replacement/reaction rules."},{"section":"Visuals","rule":"Visible3-part charge bar cycles with status/stamina indicators. Full bar waits next defensive snap; Fire rectangle blooms at owner start position, bar empties."},{"section":"Progression / notes","rule":"Cindruff15% slowdown/Magmaul20%;6x4 footprint; mastery1/2/3/4plays including spawn. No separate cooldown. Placement no longer centered on prior tackle."}]},{"id":"FIR-02-C","familyId":"ashkit","mode":"clash","name":"Cinder Clamp","category":"Rotation control","activation":"Successful direct attack while ready","mechanic":"Finite mark; queued voluntary rotation delay","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Successful normal direct attack dealing HP or shield damage applies grip. No miss, fully prevented zero damage, counter or reaction application."},{"section":"Targets / placement","rule":"Attacked opponent"},{"section":"Core resolution","rule":"Connected normal direct attack dealing HP or shield damage applies grip when ready. Next voluntary rotation request consumes grip and waits until AFTER marked target NEXT NORMAL TURN, then executes at next legal rotation opportunity. Stunned skipped normal turn counts; reactions do not. Same request cannot be delayed twice. No seconds or exchange countdown."},{"section":"Recharge / frequency","rule":"THREE subsequent OWNER NORMAL TURNS; application turn excluded, Stunned skips count, reserve time/reactions do not. No new grip while existing grip or delayed rotation pending. Ready after all three turns complete."},{"section":"Lifetime / persistence","rule":"Unused grip duration counts marked TARGET own normal turns, not exchanges: Cindruff 3/4/5/6, Magmaul 4/5/6/7 by mastery. Exclude application turn; Stunned skips count; reserve time pauses. Requested rotation waits through target next normal turn, then executes next legal opportunity. Existing forced-swap and owner-KO cleanup retained."},{"section":"Exceptions / counterplay","rule":"Forced swap removes grip and cancels pending request. Owner knockout removes grip; pending rotation is released next legal rotation phase without remaining delay. An owner rotating out was not approved to remove it."},{"section":"Visuals","rule":"Visible smoldering grip on target; delayed rotation indicator."},{"section":"Progression / notes","rule":"Unused grip TARGET-turn duration Cindruff 3/4/5/6, Magmaul 4/5/6/7. Cooldown three subsequent OWNER turns. Rotation delay through next TARGET normal turn fixed. Supersedes old exchange units; this non-status grip does not occupy shared status slot."}]},{"id":"FIR-03-F","familyId":"firestorm","mode":"football","name":"Meteor Impact","category":"Special action","activation":"Eligible powered pass release","mechanic":"Deep completed catch; opponent-only radial push","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Forward pass targeted at least 15 yards beyond line of scrimmage while ready; commit on release."},{"section":"Targets / placement","rule":"Opponents within 3 yards of teammate completed catch"},{"section":"Core resolution","rule":"Completed teammate catch releases outward shockwave; no effect on tips, drops or interceptions."},{"section":"Recharge / frequency","rule":"Three completed offensive scrimmage plays: fires 1, unavailable 2–4, ready 5. Commit at powered release even on failure. Two-point attempts neither activate nor advance cooldown."},{"section":"Lifetime / persistence","rule":"Instant bounded displacement; no lingering zone."},{"section":"Exceptions / counterplay","rule":"No stun or knockdown. Resistance reduces displacement. No ball trajectory change or forced fumble. Teammates unaffected."},{"section":"Visuals","rule":"Flaming powered pass; visible expanding shockwave synchronized to catch."},{"section":"Progression / notes","rule":"Mastery increases max push 1/1.25/1.5/1.75 yards."}]},{"id":"FIR-03-C","familyId":"firestorm","mode":"clash","name":"Falling Star","category":"Delayed attack","activation":"Normal action replaced by launch","mechanic":"Delayed slot meteor; one hit on the marked position’s occupant","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Launch meteor in place of normal attack, once per Clash."},{"section":"Targets / placement","rule":"Mark the normal target lineup position, not combatant identity; normally the opposing front. Current occupant takes the hit. No other opponent is hit: no splash, reserves and other teammates of the target are never damaged. Empty marked slot: the meteor lands on nobody."},{"section":"Core resolution","rule":"Impact at end of following exchange after rotations. Freeze the target identity when impact begins: the marked occupant. Resolve the target’s eligible reactions immediately after the hit."},{"section":"Recharge / frequency","rule":"Once per Clash; one meteor in flight per owner."},{"section":"Lifetime / persistence","rule":"N9d: preserve the approved launch, charge and delayed-impact lifetime. Target the then-active position when impact starts. Due impacts resolve before the exchange-30 cap check. Not-yet-due impacts are discarded at the cap, without extending the battle. Preserve the named post-KO exception.","ruling":"N9d","supersededRule":"Once launched, persists through owner rotation/knockout while Clash ongoing. Recalculate offensive strength at impact; if owner is knocked out, use strength immediately before knockout. Target uses current defense/type/shield/evasion at the hit."},{"section":"Exceptions / counterplay","rule":"Delayed direct attack. The hit respects normal evasion/decoys. The damaged target may trigger eligible reactions once. No Burn/stun. No formation/grid adjacency requirement remains."},{"section":"Visuals","rule":"Meteor flies UP and out of battle view on launch. Persistent slot marker warns of impact. Meteor descends onto the marked position and strikes its occupant only."},{"section":"Progression / notes","rule":"Main damage 150/160/170/180% by mastery. No splash. Target defense/type calculated as for any hit. No adjacency-based targeting."}],"ruling":"N9d"},{"id":"FIR-04-F","familyId":"cinderclaw","mode":"football","name":"Ember Grip — Scorch Mark","category":"Targeted effect","activation":"Immediate first blocking engagement while ready","mechanic":"Pair-specific effective Strength and Blocking debuff","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Marks first blocker engaged while ready."},{"section":"Targets / placement","rule":"That blocker, against this Scorchulk only"},{"section":"Core resolution","rule":"Reduce marked blocker’s effective Strength and Blocking by mastery percentage only in engagements versus this Scorchulk. Never alter stored ratings or other matchups. No separate push-speed bonus."},{"section":"Recharge / frequency","rule":"Three defensive plays: fires 1, unavailable 2–4, ready 5; one marked blocker per activation."},{"section":"Lifetime / persistence","rule":"Rest of play, including disengage and re-engage; clear at whistle."},{"section":"Exceptions / counterplay","rule":"Does not weaken blocker against any other defender."},{"section":"Visuals","rule":"Visible glowing claw marks on affected blocker."},{"section":"Progression / notes","rule":"Strength and Blocking reductions both 10/12/14/16%. Shared engine change: displacement is Strength-based; holding uses Blocking versus defender Agility, with LB Strength-based shed exception. No guaranteed release/push."}]},{"id":"FIR-04-C","familyId":"cinderclaw","mode":"clash","name":"Molten Brand","category":"Retaliation mark","activation":"First successful direct attack while ready","mechanic":"Two-use attached damage-triggered reaction mark","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First successful normal direct attack while ready brands target alongside normal damage. HP or shield damage qualifies; multi-hit once; no counters/reactions, misses or fully prevented zero-damage application."},{"section":"Targets / placement","rule":"Branded opponent"},{"section":"Core resolution","rule":"Branded opponent dealing HP or shield direct-attack damage to Scorchulk triggers one Fire eruption, consuming one of two charges. Includes delayed direct attacks. Multi-hit counts once; no damage-over-time/counter/reaction trigger. Eruption is reaction damage and triggers no retaliation."},{"section":"Recharge / frequency","rule":"Once per Clash; cannot reapply."},{"section":"Lifetime / persistence","rule":"Molten Brand remains for FOUR subsequent marked TARGET NORMAL TURNS or until its two reaction charges consumed. Application turn excluded; Stunned skips count; reserve time pauses. Target rotation retains mark. Existing lethal-hit reaction and owner-KO cleanup remain as approved. Old four-full-exchange clock superseded."},{"section":"Exceptions / counterplay","rule":"No damage-over-time/counter/reaction trigger; eruption itself cannot trigger retaliation. Lethal hit still erupts, then remaining charge disappears; settle both knockouts before winner."},{"section":"Visuals","rule":"Visible two-charge brand and localized flame eruption."},{"section":"Progression / notes","rule":"20/25/30/35% normal attack damage per eruption."}]},{"id":"FIR-05-F","familyId":"pyrelynx","mode":"football","name":"Heat Haze","category":"Aura","activation":"Passive live play","mechanic":"Passive opponent Catching debuff; moving aura","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Active while Flarynx on field during live play."},{"section":"Targets / placement","rule":"Opponents within 3 yards; opposing Fire types immune"},{"section":"Core resolution","rule":"Reduce effective Catching attribute, not flat catch probability. Effect ends outside aura."},{"section":"Recharge / frequency","rule":"No cooldown; duplicates use strongest only."},{"section":"Lifetime / persistence","rule":"Moving aura; no field remains."},{"section":"Exceptions / counterplay","rule":"Teammates unaffected. Fire immunity is explicitly approved for this aura. No guaranteed drops."},{"section":"Visuals","rule":"Moving visible heat shimmer, readable ball and player markers."},{"section":"Progression / notes","rule":"Catching reduction 10/12/14/16%."}]},{"id":"FIR-05-C","familyId":"pyrelynx","mode":"clash","name":"Heat Mirage","category":"Entry defense","activation":"Starting active or entering active position while ready","mechanic":"Entry decoy; probabilistic whole-attack evasion","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Eligible starting-active or entry creates one decoy even if Flarynx cannot act; creation is automatic entry effect, not action. No new creation just because cooldown ends."},{"section":"Targets / placement","rule":"Self; next direct attack"},{"section":"Core resolution","rule":"Normal direct attacks and delayed offensive attacks trigger one diversion roll for entire attack including all hits. Success diverts whole attack; failure resolves normally. Both consume decoy. Other targets of area attacks resolve independently."},{"section":"Recharge / frequency","rule":"THREE subsequent OWNER NORMAL TURNS after decoy creation. Creation turn excluded; Stunned skips count; reserve time/reactions do not. Opening entry starts same counter at zero. Entry creates decoy only when ready; no automatic creation merely because cooldown expires while already active. Supersedes exchange readiness examples."},{"section":"Lifetime / persistence","rule":"Until direct attack consumes it or Flarynx leaves active position."},{"section":"Exceptions / counterplay","rule":"Counters, reaction damage and damage over time neither roll nor consume decoy. Explicitly undodgeable attacks bypass it without consuming. Unused decoy ends when owner leaves active position."},{"section":"Visuals","rule":"Recognizable shimmering decoy; successful attack visibly strikes it."},{"section":"Progression / notes","rule":"Diversion chance 30/35/40/45%."}]},{"id":"FIR-06-F","familyId":"pyroclast","mode":"football","name":"Eruption — Burning Wake","category":"Zone","activation":"Five YAC earns next-offensive-play zone","mechanic":"Total-YAC-width Fire rectangle at upcoming LB depth","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Catch-and-run reaches5YAC while ready; finalize earned width AFTER return ends. Before next offensive snap create zone at opposing linebackers INITIAL alignment depth for upcoming play. No live-run Fire strip. Once per offensive possession as previously approved."},{"section":"Targets / placement","rule":"Before play selection create fixed5-yard-long rectangle centered at LB REFERENCE DEPTH, always FIVE yards beyond upcoming LOS regardless actual linebackers. Center laterally on Pyroclast INITIAL pre-play position. Width TOTAL earned YAC, min5/cap FIELD.width; symmetric lateral expansion and inward boundary shift. Later play/formation changes do not move it."},{"section":"Core resolution","rule":"After qualifying catch-and-run, pending earned rectangle becomes Fire zone before NEXT offensive snap.5YAC ->5x5;10YAC ->10wide x5long;20YAC ->20wide x5long. Slow25/28/31/34% by mastery; Fireimmune, both teams others affected."},{"section":"Recharge / frequency","rule":"Once per offensive possession as approved; at most ONE pending activation. Pending token waits through touchdowns, possession changes and halftime. Do not bank extra tokens while one is pending. Two-point attempts cannot trigger. Stored token is spent when its zone actually spawns."},{"section":"Lifetime / persistence","rule":"TWO completed plays INCLUDING SPAWN play as play1. Pending token and already-created legendary field preserve remaining state through halftime without refresh. Hold pending token across possession changes; all clear actual game end. Earlier suggestion to exclude spawn play was explicitly withdrawn by owner."},{"section":"Exceptions / counterplay","rule":"Fire types immune; other types on both teams slowed. Use fixed5-yard LB reference, not actual LB count/depth. Show before play selection and lock placement. Only one pending activation; existing boundary/overlap rules apply."},{"section":"Visuals","rule":"Earn size during catch-and-run; before next snap create clearly bounded Fire rectangle at upcoming LB depth. Visible earned width, symmetric lateral expansion; no obsolete live trail. Specific pre-snap creation choreography not newly approved."},{"section":"Progression / notes","rule":"Slow25/28/31/34%, fixed5length; width TOTALYAC at least5 cappedfullfield. Not extra yards beyond5, not previous live-anchor footprint."}]},{"id":"FIR-06-C","familyId":"pyroclast","mode":"clash","name":"Faultline","category":"Delayed slot disruption","activation":"Normal action replaced by fissure creation","mechanic":"Delayed single-target eruption plus 100% Healing Reduced","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Marks slot of normal attack target."},{"section":"Targets / placement","rule":"Mark lineup position occupied by normal attack target, not monster identity. Current occupant at eruption receives main hit. Healing block attaches to hit MONSTER and follows rotations; no persistent slot suppression."},{"section":"Core resolution","rule":"Create fissure instead of normal attack; erupt at end of following exchange after rotations. Deal single-target direct damage; attempt Healing Reduced at 100% for TWO affected target TURNS, blocking all HP restoration while allowing shields. Apply shared status gate/strength/three-application rules. If status is blocked, eruption damage still resolves and use is spent."},{"section":"Recharge / frequency","rule":"Once per Clash."},{"section":"Lifetime / persistence","rule":"N9d: preserve the approved launch, charge and delayed-impact lifetime. Target the then-active position when impact starts. Due impacts resolve before the exchange-30 cap check. Not-yet-due impacts are discarded at the cap, without extending the battle. Preserve the named post-KO exception.","ruling":"N9d","supersededRule":"Once per Clash. Pending attack persists through source rotation/KO while Clash ongoing. Offensive strength recalculates at impact; KO source uses last pre-KO strength. Accepted Healing Reduced follows target through rotations, pauses in reserve, starts decrement on next normal turn, applies through final turn. Target KO clears it; entering football clears it because no Football effect is defined."},{"section":"Exceptions / counterplay","rule":"Faultline Healing Reduced is a harmful UNCLEANSABLE status at 100%. It CANNOT coexist with another shared status type. Shield-absorbed connected hit can attempt it; dodge/decoy prevents it. Empty marked slot: no damage/status. Same-status stronger/equal/weaker and episode cap rules apply. No splash."},{"section":"Visuals","rule":"Visible fissure marks lineup position; eruption synchronized to hit. If Healing Reduced applies, show shared green-cross/red-down-arrow badge and remaining target-turn count. No separate healing-block badge or slot-suppression indicator."},{"section":"Progression / notes","rule":"Damage 150/160/170/180% by mastery. Healing Reduced is 100% for two affected target turns; no application-turn decrement. Old two-exchange timer and condition coexistence are superseded. Formation suppression removed. Approved archetype Disruptor."}],"ruling":"N9d"},{"id":"WAT-01-F","familyId":"tidepaw","mode":"football","name":"Splashdown","category":"Zone","activation":"Personal pass breakup","mechanic":"PBU-created small Water slip patch","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Personally credited pass breakup only; interceptions do NOT trigger. Automatic when ready."},{"section":"Targets / placement","rule":"Water rectangle centered on deflection spot; 6 yards wide sideline-to-sideline by 4 yards long end-zone-to-end-zone, fixed field alignment."},{"section":"Core resolution","rule":"On distinct sharp cut or sudden stop, roll form/mastery slip chance, never per frame. Water types immune; both teams otherwise affected. Slip attempts Stumbled via shared single-status gate: lose 40% CURRENT speed, maximum speed unchanged, Speed controls reacceleration. No Knocked Down. Maximum one successful slip per monster per play."},{"section":"Recharge / frequency","rule":"Three subsequent defensive plays: trigger play 1, unavailable 2–4, ready 5. Recharge even if creator benched; no seconds timer."},{"section":"Lifetime / persistence","rule":"Creation play excluded; lasts TWO subsequent completed football plays regardless possession/creator participation. Clear halftime/actual game end. Slip Stumbled clears at current whistle, not carried into next snap: explicit application-play exception."},{"section":"Exceptions / counterplay","rule":"Environmental field is not shared status. Water immunity; explicit Stumbled attempt can be blocked by active different status. Existing overlap rules apply. No interception activation."},{"section":"Visuals","rule":"Visible shallow wet rectangle; recharge bar fills thirds and alternates via fade with status badge rather than crowding overhead UI."},{"section":"Progression / notes","rule":"Aquip slip chances 20/22/24/26%; Aquarrel 25/27/29/31%; Abyssin 30/32/34/36%. Duration, footprint and slip loss fixed."}]},{"id":"WAT-01-C","familyId":"tidepaw","mode":"clash","name":"Second Tide","category":"Support","activation":"Every second eligible normal action, in addition to the attack","mechanic":"Heal most injured percentage; surplus attempts Shielded","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Every second own normal turn on which able to act, the support effect resolves and the normal attack still follows in the same action; it never replaces the attack. First eligible action attacks only. Stunned skipped actions do not build ability counter (but do tick status duration)."},{"section":"Targets / placement","rule":"Living ally INCLUDING self with largest missing-HP percentage. If tied, active ally first, then reserve lineup order. If all healthy, active ally."},{"section":"Core resolution","rule":"Compute healing budget from recipient maximum HP and form/mastery; apply Healing Reduced to budget FIRST. Restore missing HP; 100% remaining surplus attempts Shielded. 100% Healing Reduced means no heal or surplus shield. The support effect deals no damage; the normal attack then resolves as usual."},{"section":"Recharge / frequency","rule":"Every second eligible action, not exchanges or wall-clock seconds. Action counter preserved on rotation; reset for separate Clash."},{"section":"Lifetime / persistence","rule":"Shield lasts THREE recipient own normal turns, excluding application turn; pause reserve time; clear when pool depleted. Same-game transfer preserves remaining duration 1:1 and becomes one football fumble save."},{"section":"Exceptions / counterplay","rule":"Normal shared status gate applies to shield; healing still resolves if shield blocked. Equal Shielded extends duration only without refill; stronger replaces; blocked surplus is lost. No undoing restored HP."},{"section":"Visuals","rule":"Water healing animation then visible shield if accepted. Use shared Shielded badge; no extra status identity."},{"section":"Progression / notes","rule":"Healing fractions: Aquip 15/16/17/18%; Aquarrel 18/19/20/21%; Abyssin 21/22/23/24%. Support retained."}]},{"id":"WAT-02-F","familyId":"mudcub","mode":"football","name":"Divided Guard","category":"Self enhancement","activation":"Automatic snap when ready","mechanic":"Two simultaneous block engagements with split effectiveness","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Automatically activates at snap on eligible offensive play when ready, even if ultimately zero or one defender engaged."},{"section":"Targets / placement","rule":"Self; up to TWO defenders simultaneously, within normal physical reach. May replace freed targets during play; no ranged blocking."},{"section":"Core resolution","rule":"With two engagements, each uses 50% Strength and form/mastery Blocking fraction. With only one engagement, use normal 100% attributes. No pancake while double-engaged; single engagement uses ordinary OL one-attempt-total-per-play rule."},{"section":"Recharge / frequency","rule":"Three subsequent offensive plays; activation spent at snap even if double block never occurs."},{"section":"Lifetime / persistence","rule":"Active entire activation play; ends at whistle. Cooldown carries halftime/OT; resets actual game end."},{"section":"Exceptions / counterplay","rule":"No two fixed targets for whole play. Reach, collision and ordinary contest rules remain. Does not duplicate monster, ball or statuses."},{"section":"Visuals","rule":"Body divides into two visible lobes, each bracing against its engaged defender. Shared cooldown bar/status cycling."},{"section":"Progression / notes","rule":"Muddlet Blocking per defender 70/73/76/79%; Sludgeon 80/83/86/89%. Strength split fixed at 50%."}]},{"id":"WAT-02-C","familyId":"mudcub","mode":"clash","name":"Shared Burden","category":"Tank","activation":"Spend first eligible normal turn creating link","mechanic":"Reserve owner absorbs fraction of raw incoming active-ally attack","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, first own normal turn able to act with another living ally creates link INSTEAD of attack. If last survivor, attack normally. No automatic free setup."},{"section":"Targets / placement","rule":"Protect current active ally only while Muddlet/Sludgeon is in RESERVE. Never protects self. Current active ally changes with rotation; no reset."},{"section":"Core resolution","rule":"Original target evasion first; miss damages neither. Split RAW attack, then each recipient own type/defense/shield. Owner share 30/32/34/36% Muddlet or 40/42/44/46% Sludgeon; ally remainder. IMPORTANT: Tank damage reduction applies ONLY while active, so reserve source receives NO Tank guard on transferred share. No second source evasion; no spill between shield pools. Transferred share not direct attack, status transfer or retaliation trigger; no link chain."},{"section":"Recharge / frequency","rule":"One setup per Clash; no recharge/cooldown. Only strongest available link protects a hit."},{"section":"Lifetime / persistence","rule":"Link lasts THREE protected active-ally OWN NORMAL TURNS while source in reserve; Stunned skips count. Protection and countdown pause while source active. Rotation of protected ally does not reset duration."},{"section":"Exceptions / counterplay","rule":"Owner KO ends link immediately. Current hit keeps its original split with no overflow back to ally; later hits recalculate without link. Status attempts remain on original target. Rounding/tie rules and attack-modifier attribution still require implementation specification."},{"section":"Visuals","rule":"Visible watery link between reserve owner and active ally, showing redirected hit; no extra shared status slot."},{"section":"Progression / notes","rule":"Muddlet Tank; transfer 30/32/34/36%. Sludgeon 40/42/44/46%. Owner expressly chose NO reserve Tank guard on transferred damage (21B). Other explicitly applicable defenses and own shield still resolve; original active target may use its active defenses."}]},{"id":"WAT-03-F","familyId":"reefclaw","mode":"football","name":"Pressure Drain","category":"Targeted effect","activation":"First block engagement when ready","mechanic":"Immediate current-stamina-point drain from blocker","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First block engagement while ready; immediate trigger, not prolonged contact."},{"section":"Targets / placement","rule":"One engaged opposing blocker per activation."},{"section":"Core resolution","rule":"Subtract 5/10/15/20 CURRENT STAMINA POINTS by mastery, bounded at zero. Permanent Durability determines starting/MAX stamina 1:1: 90 Durability -> 90 points. Temporary Durability modifiers do not resize pool. Drain does not reduce Durability or get resisted by higher Durability."},{"section":"Recharge / frequency","rule":"Three subsequent defensive plays; one blocker per activation."},{"section":"Lifetime / persistence","rule":"Stamina loss lasts until approved halftime recovery; depletion can trigger game-long Exhaustion. No timed debuff or shared status."},{"section":"Exceptions / counterplay","rule":"Not Afflicted, not a percentage drain and not injury damage. See Rules for stamina capacity, halftime-only recovery, low-stamina indicator and 0-stamina penalty. Normal play cost remains provisional pending testing."},{"section":"Visuals","rule":"Drain feedback plus low-stamina battery indicator at or below 25% capacity; indicator alternates with shared status/recharge displays."},{"section":"Progression / notes","rule":"Standalone Uncommon; no evolution. Drain points Developing 5, Practiced 10, Expert 15, Mastered 20."}]},{"id":"WAT-03-C","familyId":"reefclaw","mode":"clash","name":"Shell Renewal","category":"Tank","activation":"Automatic harmful status received or active entry","mechanic":"Once-per-Clash automatic harmful-status shedding attempt","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"While active: trigger after harmful status applies, or enter active already harmful, if unused. Automatic and can trigger while Stunned. No trigger for beneficial/no status."},{"section":"Targets / placement","rule":"Self only; entire active harmful shared status."},{"section":"Core resolution","rule":"Remove removable harmful status, including all stacked duration/applications. NO heal, shield or bonus attack. Uncleansable status remains but ATTEMPT SPENDS the sole use."},{"section":"Recharge / frequency","rule":"ONCE per separate Clash, all mastery levels. No action cost. No forced numerical mastery scaling."},{"section":"Lifetime / persistence","rule":"Immediate cleanse attempt; ready again in separate Clash. No reserve-time cleanse."},{"section":"Exceptions / counterplay","rule":"Uncleansable failure consumes use; independent damage/effects from incoming ability still resolve. Shared lifecycle otherwise unchanged."},{"section":"Visuals","rule":"On success, harmful-status badge cracks, breaks apart and disappears. On failure, badge remains. No protective shell barrier."},{"section":"Progression / notes","rule":"Tank retained. Simplicity exception: identical effect/use limit at all mastery levels."}]},{"id":"WAT-04-F","familyId":"tidefin","mode":"football","name":"Second Touch","category":"Special action","activation":"Eligible physically reached dropped pass","mechanic":"One ordinary extra catch attempt after eligible drop","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Physically reached pass with failed catch, including contested drop. Unreachable pass, interception or defender deflection does NOT qualify. Normal scrimmage only, not returns or two-point attempts."},{"section":"Targets / placement","rule":"Ripplet and same live bobbled ball; no teleporting unreachable throws into reach."},{"section":"Core resolution","rule":"One additional ordinary catch attempt using normal Catching, position and contest checks. NO guaranteed catch and NO extra retry bonus. Defenders may intercept or bat bobble. Second failure ends ability sequence."},{"section":"Recharge / frequency","rule":"Offensive-play cooldown 5/4/3/2 by mastery. Spend activation/cooldown even if retry fails."},{"section":"Lifetime / persistence","rule":"Extra attempt occurs in same live pass sequence; no lingering buff/status."},{"section":"Exceptions / counterplay","rule":"Fully trained permanent Catching CEILING 78 and Speed CEILING 95, NOT starting ratings. Generation, training and permanent progression respect ceilings; temporary boosts/reductions may cross them. No extra forced-drop chance."},{"section":"Visuals","rule":"Physical bobble, fin tap and second reach. Recharge bar; no extra status/field/label."},{"section":"Progression / notes","rule":"Standalone Uncommon WR. Permanent max Catching 78 and Speed 95. Offensive cooldown 5/4/3/2 plays. Reference generator starting values remain separate."}]},{"id":"WAT-04-C","familyId":"tidefin","mode":"clash","name":"Wash Away","category":"Disruptor","activation":"Normal-turn beneficial-status removal attempt","mechanic":"Sacrifice attack to strip opposing active beneficial status","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"When ready on own normal turn, wait until opposing active has a beneficial status, then attempt instead of attack. No beneficial status: attack normally, preserve use. This final A overrides earlier waste-on-no-target answer."},{"section":"Targets / placement","rule":"Opposing ACTIVE monster only, not reserve. Benefits only; no traits, charges, marks or harmful-status removal."},{"section":"Core resolution","rule":"Non-damaging utility replaces attack. On success remove ENTIRE beneficial status, stacked duration and remaining Shield HP included. No steal, heal or new status."},{"section":"Recharge / frequency","rule":"ONCE per separate Clash. Fixed effect/use limit at all mastery; no cooldown progression."},{"section":"Lifetime / persistence","rule":"Immediate attempt; reset readiness for separate Clash."},{"section":"Exceptions / counterplay","rule":"Normal evasion check applies. Evasion or explicit removal immunity wastes action AND use. Respect immunity; cannot remove permanent archetype traits. Exact normal-evasion integration for utility needs engine work."},{"section":"Visuals","rule":"Splash breaks beneficial badge apart; no water jet, field or extra status."},{"section":"Progression / notes","rule":"Disruptor retained. Once-per-Clash choice supersedes old 5/4/3/2-turn cooldown proposal."}]},{"id":"WAT-05-F","familyId":"wavehorn","mode":"football","name":"Breakwater","category":"Aura","activation":"Only blocking-assignment plays","mechanic":"Moving aura reduces opponents entire effective Strength","designStatus":"Core approved; interaction decisions open","details":[{"section":"Trigger / eligibility","rule":"Active only when SNAP ASSIGNMENT is blocking, including block-and-release. Route assignment does not qualify. Snap assignment remains the eligibility decision for that play; no physical-engagement toggling."},{"section":"Targets / placement","rule":"Opponents within THREE yards center-to-center of Tideram; reduce their entire effective Strength for ALL Strength-based actions against anyone. No type immunity was approved. Supports Tideram as well as nearby allies. Leave range removes reduction."},{"section":"Core resolution","rule":"Opponents in range lose 25/30/35/40% of ENTIRE effective Strength by mastery, affecting all Strength-based actions against anyone. No additional displacement reduction and NO Stumbled protection; supporting stumble mechanic removed by owner. Not a shared status."},{"section":"Recharge / frequency","rule":"Passive on eligible blocking play; no cooldown."},{"section":"Lifetime / persistence","rule":"No lingering shared status or field. Dynamic range during play; inactive when assigned route. Assignment changes within play require clarification rather than guessing."},{"section":"Exceptions / counterplay","rule":"Strongest overlapping Strength reduction only. Each additional eligible overlapping Breakwater adds one yard of radius, capped at FIVE yards. Determine eligibility from original THREE-yard radii to prevent chain expansion. Resolve Strength contests using reduced Strength, then apply Earth displacement resistance normally; never apply obsolete extra Breakwater displacement multiplier."},{"section":"Visuals","rule":"Water barrier appears ONLY when protection occurs; no persistent barrier. Exact visual cue for full-Strength reduction requires alignment with revised mechanic."},{"section":"Progression / notes","rule":"Group Strength reduction distinct from Scorch Mark pair-specific Strength AND Blocking; explicitly owner approved. Blocking snap assignment gates aura, including block-and-release. Stumbled mitigation removed. Strength mastery 25/30/35/40%."}]},{"id":"WAT-05-C","familyId":"wavehorn","mode":"clash","name":"Riptide Charge","category":"Balanced","activation":"Every second performed normal attack","mechanic":"Charged hit forces surviving target to reserve with opponent choice","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Every SECOND performed normal attack becomes charged. Skipped turns/reactions do not build progress."},{"section":"Targets / placement","rule":"Opposing active monster; if it survives, send into reserve and opposing team chooses living replacement."},{"section":"Core resolution","rule":"Charged damage 130/135/140/145% normal attack. Connected hit can force rotation even when shield absorbs all damage. If no living reserve, damage still applies with no rotation."},{"section":"Recharge / frequency","rule":"Attack counter retained across own rotations; normal attack cadence, no seconds timer."},{"section":"Lifetime / persistence","rule":"Immediate damage then forced rotation; preserve departing target status and remaining duration. Reset ability counter for separate Clash."},{"section":"Exceptions / counterplay","rule":"Evasion prevents damage AND rotation; charge spent. KO uses ordinary replacement. Explicit forced-rotation immunity blocks lineup change but NOT charged damage. Audit confirms existing side-wide forced-rotation pacing and just-entered protection: preserve unless owner changes. Target choice must be recorded for player and deterministic AI."},{"section":"Visuals","rule":"Stationary horn strike followed by splash and lineup change. No running charge or football pulling."},{"section":"Progression / notes","rule":"Balanced retained. Damage scaling approved; replacement choice differs from original automatic next-in-line sweep."}]},{"id":"WAT-06-F","familyId":"tsunarok","mode":"football","name":"Tsunami Line","category":"Zone","activation":"Secured interception; post-play slam","mechanic":"Interception earns full-width next-play Water at safety depth","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Personally secured interception while ready. Finish return normally; before next offensive scrimmage snap summon GIANT RAINDROP onto opposing secondary. No football slam."},{"section":"Targets / placement","rule":"FULL field width x5yards long, centered at SAFETY REFERENCE DEPTH, always TWELVE yards beyond upcoming LOS regardless actual safeties or missing safety positions. Use initial pre-play snapshot, reveal before play selection, never follow later defensive changes. Keep within playable bounds."},{"section":"Core resolution","rule":"Giant raindrop impact is cosmetic only: no damage, immediate stumble or displacement. Creates full-width Water field; later sharp cuts/stops slip30/32/34/36% mastery,40%current-speed loss, max1successful slip/monster/play, clearswhistle. Nature rules do not replace Water. Waterimmune both teams other types affected."},{"section":"Recharge / frequency","rule":"FIVE subsequent defensive plays; interception activation play excluded. No once-per-game restriction."},{"section":"Lifetime / persistence","rule":"TWO completed plays including FIRST OFFENSIVE SPAWN PLAY as play1. Preserve remaining duration over halftime, no refresh; actual game end clear. Wait for next offensive scrimmage snap, not specialteams."},{"section":"Exceptions / counterplay","rule":"Waterimmunity/both-team effects and existing overlaps. Return finishes before summon; no real-ball slam or live return impact. Spawned location no longer end-of-return spot. Source personal position unaffected."},{"section":"Visuals","rule":"GIANT RAINDROP falls from sky before next offensive snap onto opposing secondary, splashes full-width5yardlong wet strip. REPLACES jump/football-slam entirely. Both teams see."},{"section":"Progression / notes","rule":"Legendary S; full-width x5long Water at fixed12-yard safety reference; giant raindrop before next offensive play. Two plays INCLUDING spawn. Five subsequent defensive-play cooldown; slip30/32/34/36%. Actual-safety averaging and return-end slam are superseded."}]},{"id":"WAT-06-C","familyId":"tsunarok","mode":"clash","name":"Riptide Pursuit","category":"Disruptor","activation":"One ready pursuit each active entry","mechanic":"Undodgeable reaction punishes voluntary enemy departure","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Opening active entry and EVERY later active entry grants ONE ready pursuit; never accumulate unused uses. While active and able to act, react to first opposing voluntary rotation before target departs."},{"section":"Targets / placement","rule":"Departing opposing active monster. Forced rotations and knockout replacements do NOT trigger."},{"section":"Core resolution","rule":"Reaction deals 75/85/95/105% normal attack damage by mastery and CANNOT be evaded. Normal type, damage reduction and Shield HP apply. Costs no normal action. Surviving target completes rotation; no additional status."},{"section":"Recharge / frequency","rule":"One use per active entry, not once per Clash. Re-entry replaces unused opportunity rather than stacking. No seconds cooldown."},{"section":"Lifetime / persistence","rule":"Immediate pre-departure hit. If target KO, resolve knockout and replacement normally. No delayed mark/status."},{"section":"Exceptions / counterplay","rule":"Cannot trigger while Stunned; unused opportunity retained. Pursuit cannot trigger counterattacks/retaliation or further reaction chains. Must integrate voluntary/forced/KO entry reasons and existing rotation locks; no football pulling."},{"section":"Visuals","rule":"Tsunarok briefly transforms into water and surges into departing monster. Damage resolves before lineup transition."},{"section":"Progression / notes","rule":"Disruptor retained. Opening entry included; new entry max readiness 1. Undodgeable chosen explicitly over initial normal-evasion recommendation."}]},{"id":"NAT-01-F","familyId":"thornkit","mode":"football","name":"Bloom Break","category":"Zone","activation":"Designed route cut earns next-play patches","mechanic":"Two seeded random Nature patches earned by designated route cut","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First designated route cut of at least 45 degrees while ready; incidental steering does not qualify. Route-running passing plays; no returns/two-point/block assignments."},{"section":"Targets / placement","rule":"Before play selection use initial pre-play formation snapshot. Create TWO recorded random, non-overlapping 6-yard-wide x 4-yard-long rectangles between initial defensive line and FIXED safety-reference depth 12 yards beyond upcoming LOS. Use that reference even if actual safeties differ or none exist. Both teams see patches before choosing plays; later changes never move/reroll them. Near goal line extend eligible band toward end line just enough to fit, within playable bounds."},{"section":"Core resolution","rule":"Nature environmental modifier: maximum turning rate reduction Spriglet 15%, Floracat 20%, Sylvanyx 25%. Straight speed/acceleration and other Agility uses unchanged. Both teams affected except Nature types. No physical vine obstacles/shared status."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent OFFENSIVE plays by mastery, starts on spawn. Spawn play cannot earn new activation. One pending activation; wait through punts/possession changes."},{"section":"Lifetime / persistence","rule":"Pending activation: at most ONE; wait through punts, possession changes and halftime. Spawned patches last ONE completed play INCLUDING spawn play, all outcomes, then clear whistle. No bonus attempt after incompletion. No new token earned on spawn play or while cooldown/pending activation prevents eligibility."},{"section":"Exceptions / counterplay","rule":"Show recorded placement to BOTH teams before choosing plays. Fixed pre-play formation snapshot and safety reference12yards; later defensive changes cannot reroll/move patches. Two patches must not overlap each other. Nature immunity and normal field overlap rules apply."},{"section":"Visuals","rule":"Shoots emerge directly from ground into clearly outlined vegetation; no falling seeds. Both offense and defense see patches."},{"section":"Progression / notes","rule":"Common WR family, Support Clash. Form turning 15/20/25%; mastery cooldown 5/4/3/2. Does not use old immediate cut-centered patch."}]},{"id":"NAT-01-C","familyId":"thornkit","mode":"clash","name":"Second Spring","category":"Support","activation":"Next eligible normal turn revives first knocked-out ally","mechanic":"Once-per-Clash ally revival to back reserve without refreshing uses","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Unused ability, own normal turn able to act, at least one knocked-out ally. Automatically revive earliest knocked-out ally still down; otherwise ordinary attack and preserve use."},{"section":"Targets / placement","rule":"One ally, not self. Return at BACK OF RESERVE, no immediate action. Cannot activate after Clash ended."},{"section":"Core resolution","rule":"Replace attack; restore max-HP percentage by form/mastery. Distinct revival NOT ordinary healing; Healing Reduced does not block. KO cleared target status already. Restore HP only; no shield/charges/cooldown reset/ability-use refresh."},{"section":"Recharge / frequency","rule":"ONCE per separate Clash, across all entries. Stunned skip cannot activate and does not spend use."},{"section":"Lifetime / persistence","rule":"Instant revival; resumed monster may later KO normally. Retain spent once-use flags and existing progression; revive runtime KO state, not roster duplication."},{"section":"Exceptions / counterplay","rule":"No self-revival after final KO. Preserve source/target uses through revival. Exact prior KO ordering/stable tie rule and turn scheduling require deterministic engine hooks."},{"section":"Visuals","rule":"Seed beneath fallen monster; glowing flower bud closes, blossoms open, ally returns reserve. No extra status."},{"section":"Progression / notes","rule":"Spriglet HP 10/12/14/16%; Floracat 15/17/19/21%; Sylvanyx 20/22/24/26%. Keep Support."}]},{"id":"NAT-02-F","familyId":"mossclaw","mode":"football","name":"Vine Vault","category":"Special action","activation":"First single-block pass-rush engagement","mechanic":"Contested vault to legal spot beyond engaged blocker","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"DL rushing quarterback on passing play only. First single-block engagement while ready; not run defense."},{"section":"Targets / placement","rule":"Engaged blocker; nearest clear landing immediately beyond blocker toward offensive backfield. If no clear legal landing, do not attempt/spend readiness."},{"section":"Core resolution","rule":"Normal intended DL Agility versus blocker Blocking shed contest. On success vault past blocker; resume ordinary pursuit. On failure stay engaged normally. No attribute boost, bonus speed, automatic sack/stumble/knockdown."},{"section":"Recharge / frequency","rule":"5/4/3/2 subsequent defensive-play cooldown by mastery; failed attempted vault spends activation. Same mechanic both forms."},{"section":"Lifetime / persistence","rule":"One live vault and landing, no lingering field/status. During airborne traversal IGNORE OTHER BLOCKING COLLISIONS until landing; applicable disabling effects can still interrupt. After landing resume normal pursuit and ordinary blocking/status interactions. This is not general damage/status invulnerability."},{"section":"Exceptions / counterplay","rule":"Can bypass Deep Roots; does NOT consume its first-ordinary-shed protection. Ignore blocking collisions while airborne, not disabling effects. No bonus Speed, guaranteed sack or universal invulnerability. Legal clear destination required before attempt; no destination -> preserve readiness."},{"section":"Visuals","rule":"Crouch, two short supporting vines, visible arc over blocker, leafy landing; vines retract. Larger Fungorilla visual, same rules."},{"section":"Progression / notes","rule":"Common DL -> Fungorilla level 14; Balanced Clash. Speed-boost option explicitly withdrawn by owner."}]},{"id":"NAT-02-C","familyId":"mossclaw","mode":"clash","name":"Spore Detonation","category":"Balanced","activation":"Ready normal attack against removable harmful status","mechanic":"Consume enemy harmful status duration for immediate bonus damage","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Own normal attack when ready and opposing active has removable harmful status. Otherwise ordinary attack, preserve readiness; uncleansable status not consumed."},{"section":"Targets / placement","rule":"Opposing active monster and its entire harmful shared status, all stacked remaining duration."},{"section":"Core resolution","rule":"Snapshot existing harmful status and remaining turns before attack. Calculate connected attack damage WITH existing status: +10% per remaining turn Mossmaw or15% Fungorilla, max3 counted turns. After connected damage, remove entire harmful status BEFORE retaliation. Evasion prevents removal/damage and spends readiness. No new status or attribute change."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent OWN NORMAL turns; exclude application turn; Stunned skips count, reserve pauses."},{"section":"Lifetime / persistence","rule":"Immediate single attack. At 3 counted turns total damage 130% Mossmaw, 145% Fungorilla. No lingering mark."},{"section":"Exceptions / counterplay","rule":"Only removable harmful status eligible. Uncleansable/no status -> ordinary attack, preserve readiness. Connected shield-absorbed hit eligible if such state legally exists; shared slot ordinarily prevents Shielded+harmful coexistence. Snapshot duration for bonus; calculate damage with old status, then remove before eligible retaliation."},{"section":"Visuals","rule":"Claw scatters mushrooms over target; spores swell/burst; harmful badge breaks apart. No field."},{"section":"Progression / notes","rule":"Balanced retained. Fixed per-form conversion; mastery cooldown only. Prior Spore Swipe retaliation-heal replaced."}]},{"id":"NAT-03-F","familyId":"rootram","mode":"football","name":"Deep Roots","category":"Self enhancement","activation":"First block engagement when ready","mechanic":"Fixed rooted blocking position plus one ordinary-shed prevention","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First block engagement while ready, run OR pass blocking; not one-yard-push trigger."},{"section":"Targets / placement","rule":"Self at engagement point; ordinary reach for defenders. Remain stationary until whistle."},{"section":"Core resolution","rule":"Root in place, no translation; may turn and engage within reach. Prevent all forced displacement including ability pushes. Prevent FIRST successful ORDINARY block shed during activation play; after consumed sheds normal. No attribute changes."},{"section":"Recharge / frequency","rule":"5/4/3/2 subsequent offensive-play cooldown, starts on root activation."},{"section":"Lifetime / persistence","rule":"Roots remain through play even if defender gets past. Ends whistle. No field/shared status."},{"section":"Exceptions / counterplay","rule":"Special bypass such as Vine Vault can succeed and does NOT consume ordinary-shed prevention. Does not grant Stunned/Knocked Down immunity. Branching Guard alternative discarded."},{"section":"Visuals","rule":"Thick roots from feet into turf; lean against defender, roots taut; retract whistle."},{"section":"Progression / notes","rule":"Uncommon standalone OL; Self enhancement. Both blocking assignments eligible; old half-speed pass-push behavior replaced."}]},{"id":"NAT-03-C","familyId":"rootram","mode":"clash","name":"Last Root","category":"Tank","activation":"Automatic otherwise lethal damage","mechanic":"One lethal damage event prevented leaving one HP","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once-use available and any incoming damage event would KO. Automatic even Stunned, active OR reserve."},{"section":"Targets / placement","rule":"Self only. One damage event, not whole multi-hit attack."},{"section":"Core resolution","rule":"Set surviving HP to ONE instead of KO; prevent event lethal remainder. Includes direct, reaction and Afflicted damage. Can activate from already 1 HP. No heal/shield/cleanse/retaliation. Next hit may KO."},{"section":"Recharge / frequency","rule":"ONCE per Clash across entries; revival does not refresh spent use."},{"section":"Lifetime / persistence","rule":"Immediate survival only. Other statuses/independent effects resolve normally. No temporary invulnerability."},{"section":"Exceptions / counterplay","rule":"If not spent before KO by an uncovered mechanism, remains unused on revival. Preserve flags; all damage paths need pre-KO hook. Replace old entry shield, normal Tank stats/active guard retained."},{"section":"Visuals","rule":"Impact bends body, roots brace, bark cracks, one green leaf glows as HP stops at 1; roots retract. No lingering badge."},{"section":"Progression / notes","rule":"Tank retained; identical survival effect all mastery levels. No added scaling."}]},{"id":"NAT-04-F","familyId":"leafhorn","mode":"football","name":"Surefoot Canopy","category":"Targeted effect","activation":"Random teammate protection before each defensive snap","mechanic":"One randomly chosen teammate immune to Stumbled for whole play","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Each defensive SCRIMMAGE play before snap; no cooldown."},{"section":"Targets / placement","rule":"One OTHER participating defensive teammate, every type eligible, equal chance; exclude Florant. Repeats allowed. Record choice; reload cannot reroll."},{"section":"Core resolution","rule":"Selected teammate cannot receive ANY Stumbled application that play, any source, regardless distance. No other status immunity/cleanse/attribute modification. Protect every attempt, not only first."},{"section":"Recharge / frequency","rule":"Every defensive scrimmage play, no charges/cooldown; no forced mastery scaling approved."},{"section":"Lifetime / persistence","rule":"Protection ends whistle. Ability protection NOT shared status, occupies no status slot."},{"section":"Exceptions / counterplay","rule":"Both teams see target before snap. No range requirement or moving aura. Old proximity Surefoot proposal replaced. Interaction with already-active Stumbled needs clarification if can persist into this snap."},{"section":"Visuals","rule":"Leaf effect identifies target, fades whistle. No environmental patch."},{"section":"Progression / notes","rule":"Uncommon standalone S; Support Clash. Targeted effect category explicitly approved; not Aura."}]},{"id":"NAT-04-C","familyId":"leafhorn","mode":"clash","name":"Canopy Assist","category":"Support","activation":"Once normal turn calls reserve basic attack","mechanic":"Reserve ally attacks without active entry or extra normal turn","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash on Florant normal turn able to act. Eligible non-Stunned living reserve required; none -> Florant attacks normally and keeps use."},{"section":"Targets / placement","rule":"Reserve with highest CURRENT attack damage, ties lineup order, attacks opposing active. Florant remains active. Target comparison metric must be deterministic."},{"section":"Core resolution","rule":"Replace Florant attack; assist basic damage 75/80/85/90% normal ally attack. No signature, charge consumption or offensive archetype perks. Normal type/target defenses/evasion. Miss spends use."},{"section":"Recharge / frequency","rule":"ONCE per Clash, no reset on entry/revival."},{"section":"Lifetime / persistence","rule":"Immediate assist then return original reserve slot; not active entry/rotation/normal turn. No status/cooldown/attack-counter ticking for helper."},{"section":"Exceptions / counterplay","rule":"Eligible retaliation targets ASSISTING ally and resolves normally; no automatic immunity. Entry and rotation effects do not trigger. Need attack-source identity and reaction tag distinct from no-retaliation reaction abilities."},{"section":"Visuals","rule":"Florant antlers form leafy arch; helper rushes through, attacks, retreats; arch dissolves."},{"section":"Progression / notes","rule":"Support retained. Mastery damage 75/80/85/90%; no extra resources/attribute boosts."}]},{"id":"NAT-05-F","familyId":"thornback","mode":"football","name":"Bramble Trap","category":"Zone","activation":"Break receiving tackle earns next-play target-centered patch","mechanic":"Random non-Nature defender-centered next-play Nature zone","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First successfully broken tackle AFTER RECEPTION while ready. No rushing carries/returns/two-point attempts."},{"section":"Targets / placement","rule":"Before play selection choose uniformly from participating NON-NATURE defenders in initial pre-play formation. Center stationary8wide x6long patch on chosen defender INITIAL position. Shift inward at boundaries to preserve size. No eligible defender -> hold pending readiness. Later formation/play changes do not reroll target or move zone. Fixed5/12-yard reference bands do NOT replace this explicitly defender-centered placement."},{"section":"Core resolution","rule":"Nature turning-rate reduction 25/30/35/40% mastery. Straight speed/acceleration unchanged. Both teams non-Nature affected; no immobilization, physical vines, damage or shared status."},{"section":"Recharge / frequency","rule":"THREE subsequent offensive plays cooldown starts spawn; no re-earn on spawn play. One pending activation, no accumulation."},{"section":"Lifetime / persistence","rule":"ONE completed play including spawn play, all outcomes. Pending activation survives possession changes/HALFTIME. Spawned nonlegendary zone clears whistle/halftime."},{"section":"Exceptions / counterplay","rule":"Recorded target and initial position are locked before both teams choose plays; no reload/audible reroll. Three subsequent offensive-play cooldown starts spawn; no re-earn on spawn play or while unavailable. One pending activation persists possession/halftime. Bramble Lane rejected."},{"section":"Visuals","rule":"Both teams see target/patch before snap; seed drops beneath chosen defender and blooms."},{"section":"Progression / notes","rule":"Rare standalone TE; Zone. Size8x6 fixed; mastery turning25/30/35/40%."}]},{"id":"NAT-05-C","familyId":"thornback","mode":"clash","name":"Shell Harvest","category":"Tank","activation":"First active entry shield; voluntary departure cashes remainder","mechanic":"Voluntary exit converts remaining own shield HP to self healing","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"ONCE first ACTIVE entry attempts Shielded; if status gate blocks attempt spent. No refresh on re-entry/revival."},{"section":"Targets / placement","rule":"Self; shield pool 20/22/24/26% max HP by mastery, shared Shielded status."},{"section":"Core resolution","rule":"Successful voluntary departure consumes entire remaining ORIGINAL Shell Harvest shield and heals100% of eligible remaining Shield HP capped missing HP. Excess lost. Other-source replacement Shielded cannot be converted. Resolve pre-departure damage before computing remaining pool. Refused/failed swap does not convert; no break retaliation."},{"section":"Recharge / frequency","rule":"One entry grant, no reset; conversion requires live shield when voluntary exit succeeds."},{"section":"Lifetime / persistence","rule":"Shield THREE subsequent own normal turns, application excluded, reserve pauses, Stunned skips count. Forced exit preserves shield/duration, no heal. Depleted/stripped/expired no heal."},{"section":"Exceptions / counterplay","rule":"Cash out ONLY original Shell Harvest-created shield. If another source REPLACES it, replacement is ineligible. Normal equal Shielded duration extensions do not refill/change pool origin. Resolve any pre-departure Pursuit first; only surviving successful voluntary exit converts remaining eligible pool. No healing if KO before leaving. Normal Healing Reduced applies if legally present; shared slot ordinarily prevents coexistence."},{"section":"Visuals","rule":"Woven thorn shell; on voluntary exit remaining branches bloom into leaves and dissolve into body."},{"section":"Progression / notes","rule":"Tank retained; old thorns retaliation replaced. Shield 20/22/24/26%, no added attributes."}]},{"id":"NAT-06-F","familyId":"elderoot","mode":"football","name":"Grove Guardian","category":"Special action","activation":"Ready defensive scrimmage snap","mechanic":"One independent temporary extra defender with copied assignment","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"At ready defensive scrimmage SNAP, including first. No tackle-charge requirement."},{"section":"Targets / placement","rule":"One clone nearest legal unoccupied spot beside Elderoot on defensive side. Independent roaming; copies Elderoot chosen assignment: blitz/zone/man target. No tether radius."},{"section":"Core resolution","rule":"Clone effective ratings 60/65/70/75% source by mastery, normal rounding. Source unchanged. Can cover, contest passes, intercept, tackle, be blocked; real collision. No abilities/new clones/roster slot/XP/mastery/independent stamina pool."},{"section":"Recharge / frequency","rule":"FIVE subsequent defensive-play cooldown fixed all mastery. Temporary extra player must not be dropped by normal personnel count."},{"section":"Lifetime / persistence","rule":"ONE completed play; clear clone/statuses/injuries at whistle. Applicable statuses affect clone normally; later source Stunned does not disable it. Clone has no lasting injury, XP, mastery, roster or independent stamina state. Normal goal/end-zone possession rulings occur before cleanup."},{"section":"Exceptions / counterplay","rule":"Credit football statistics to ELDEROOT, no extra clone XP or owner ability triggers. Clone injuries vanish with clone and never injure Elderoot; no independent stamina pool. Clone possession ends play immediately without return, but NORMAL touchdown/touchback rulings apply before cleanup. Preserve football and legal next spot; no-space handling uses deterministic nearest legal unoccupied spawn search."},{"section":"Visuals","rule":"Root at snap grows into leafy Elderoot copy with distinct outline, both teams see; disappears whistle. Not fake echo or decoy."},{"section":"Progression / notes","rule":"Legendary LB, Special action. Clone effective-rating fraction60/65/70/75%; fixed5 subsequent defensive-play cooldown. Owner credits football stats only, not extra XP/ability triggers; transient clone injuries do not transfer. Category exception approved."}]},{"id":"NAT-06-C","familyId":"elderoot","mode":"clash","name":"Root Communion","category":"Support","activation":"Eligible normal turn redistributes living team current HP","mechanic":"Once-per-Clash simultaneous HP-percentage equalization","designStatus":"Approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Own normal turn while unused, living ally at 25% max HP or less and redistribution would increase that ally HP. Otherwise ordinary attack preserve use; Stunned skips cannot activate."},{"section":"Targets / placement","rule":"ALL living allies including Elderoot/reserves. KO allies excluded; cannot revive. Shield HP not pooled or changed."},{"section":"Core resolution","rule":"Common target percentage=sum CURRENT HP/sum MAX HP. Redistribute current HP toward target simultaneously. Contributions not attacks; shields do not absorb. No HP created via rounding; keep >=1 HP each living member. Apply Healing Reduced to allocated GAINS; blocked healing LOST, can reduce total HP."},{"section":"Recharge / frequency","rule":"ONCE per Clash replaces normal attack, same effect all mastery levels."},{"section":"Lifetime / persistence","rule":"Instant redistribution; no lasting link, status, charge or attribute modifier. Existing status remains."},{"section":"Exceptions / counterplay","rule":"No retaliation/damage-triggered charges/status cleanse. Recipient gains constrained by healing rules; donor reductions not damage. Need deterministic apportionment with 1 HP lower bounds and finite accounting; implementation should not invent extra healing."},{"section":"Visuals","rule":"Glowing roots link living team; light flows healthy -> injured; HP bars settle then roots retract."},{"section":"Progression / notes","rule":"Support retained; fixed trigger 25%, no mechanical mastery scaling. Replace old periodic team heal."}]},{"id":"ELE-01-F","familyId":"flicker","mode":"football","name":"Crossed Wires","category":"Special action","activation":"Ready route snap","mechanic":"Snap-time exchange of two receivers remaining routes plus local Confused attempt","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"At a ready offensive scrimmage snap, Zippit must be running a receiving route. Blocking assignments, special teams and two-point attempts are excluded."},{"section":"Targets / placement","rule":"Select a random eligible allied WR or TE running a route within five yards. No eligible teammate: preserve readiness and original route. At activation, collect unique opposing defenders within three yards of either receiver."},{"section":"Core resolution","rule":"Exchange remaining routes: each receiver heads toward the other route’s next waypoint and follows its remaining path; no teleportation. QB targets remain attached to the monster and use its actual new route. Each collected defender gets one Confused roll: Zippit 35%, Zaptera 45%."},{"section":"Recharge / frequency","rule":"One exchange per activation. Cooldown 5 / 4 / 3 / 2 subsequent offensive plays; spend only on actual exchange."},{"section":"Lifetime / persistence","rule":"Confused reduces effective Awareness by 20%, immediately for the current play plus one subsequent participating play. Ordinary shared-status gate applies; not a separate environmental penalty."},{"section":"Exceptions / counterplay","rule":"No Speed or Coverage change, forced wrong target or input delay. Preserve normal catch, coverage and route movement rules. Deterministic random choices must be saved for replay."},{"section":"Visuals","rule":"Brief electrical connection and updated offensive route art. Both teams see the actual route change / effects; do not expose defensive play art."},{"section":"Progression / notes","rule":"Evolutions retain WR, rarity and ability identity. Charge / cooldown and status displays alternate rather than crowding the head area."}]},{"id":"ELE-01-C","familyId":"flicker","mode":"clash","name":"Lightning Rod","category":"Status transfer","activation":"Before own attack while empty status slot","mechanic":"Transfer reserve ally harmful status to self with immediate one-turn duration reduction","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, automatically before its own attack, provided its shared status slot is empty."},{"section":"Targets / placement","rule":"Choose a living reserve ally with a removable harmful status; lowest current HP percentage wins, then stable reserve order. No eligible ally or occupied own slot: preserve use and perform ordinary action."},{"section":"Core resolution","rule":"Transfer the entire status, retaining strength, accepted application count and remaining duration, then immediately subtract one turn. If duration becomes zero it expires before the attack; otherwise Confused or Stunned may affect that action normally."},{"section":"Recharge / frequency","rule":"Once per Clash, no action replacement or extra turn. No mastery scaling."},{"section":"Lifetime / persistence","rule":"Transfer immediately subtracts one remaining turn. Do NOT decrement again at end of that same turn. Ordinary countdown begins on the next owner normal turn; reserve pauses normally. Preserve transferred strength and episode application count."},{"section":"Exceptions / counterplay","rule":"Exclude uncleansable statuses. No heal, damage or retaliation. Do not reset the transferred episode’s stack cap."},{"section":"Visuals","rule":"Show harmful-status energy moving from the reserve ally to Zippit and update the ordinary shared status badge."},{"section":"Progression / notes","rule":"Support archetype retained. Transfer is distinct from Crustank self-cleanse and Ripplet enemy benefit removal."}]},{"id":"ELE-02-F","familyId":"voltfin","mode":"football","name":"Charge Strip","category":"Zone","activation":"Rushing first down earns next-snap field","mechanic":"Rushing-first-down token creates LOS-to-LB Electric rectangle on next offensive snap","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Personally earn a rushing first down while ready; touchdowns, receptions, returns and two-point attempts do not qualify. Earn one pending token."},{"section":"Targets / placement","rule":"Next participating offensive scrimmage pre-play: eight yards sideline-to-sideline by five yards longitudinal, from LOS to the fixed five-yard LB reference. Lateral center uses Volcoil’s initial alignment; shift inward to preserve width and apply normal field boundaries."},{"section":"Core resolution","rule":"Electric zone: Volcoil 20%, Eelectra 30% chance to apply Stunned on each non-Electric monster’s first entry that play. Starting inside counts; one roll per monster, no re-entry reroll. Both teams affected, Electric immune, no total stun cap."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent offensive plays, starts at spawn. Cannot earn another token during the spawn play."},{"section":"Lifetime / persistence","rule":"One completed play INCLUDING spawn. Accepted Stunned lasts the remainder of that play and clears at whistle. Pending max one carries possession and halftime; actual game end clears it. Nonlegendary field follows normal halftime clearing."},{"section":"Exceptions / counterplay","rule":"Normal shared status application gate. Field exposure is environmental; an accepted Stunned application is a shared status. No damage or additional attribute penalty."},{"section":"Visuals","rule":"Two electrical nodes at rectangle edges, readable ground arcs and boundary. Reveal before both teams select plays, then lock placement."},{"section":"Progression / notes","rule":"Rectangles and squares are legal zone shapes. Duration and stun chance do not scale with mastery; cooldown does."}]},{"id":"ELE-02-C","familyId":"voltfin","mode":"clash","name":"Arc Rebound","category":"Miss redirection","activation":"Ordinary normal attack evaded while ready","mechanic":"Evaded normal attack redirects once to first living reserve enemy","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"While ready, an ordinary normal attack is evaded by normal dodge, decoy or applicable miss effect. A shield absorbing a connected attack is not a miss."},{"section":"Targets / placement","rule":"Redirect once at the first living enemy reserve in stable lineup order. No eligible reserve: preserve readiness; do not store damage."},{"section":"Core resolution","rule":"Rebound deals 60% of normal attack damage for Volcoil, 75% for Eelectra. New target resolves its own normal type, damage reduction, shield and evasion checks. A second miss ends the sequence."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent owner normal turns, starts at launch even if rebound misses. Stunned skipped normal turns count; reserve and reaction events pause."},{"section":"Lifetime / persistence","rule":"No stored rebound or recursive redirection. Ordinary original attack retains its normal resource accounting."},{"section":"Exceptions / counterplay","rule":"Rebound is reaction damage: no retaliation chain, extra normal turn, charge consumption, normal attack-counter progress or ordinary-only offensive archetype perks. Do not consume original attack resources twice."},{"section":"Visuals","rule":"Missed bolt curves sharply toward the reserve target."},{"section":"Progression / notes","rule":"Balanced archetype retained. Different trigger and target from knockout-earned Victory Surge and voluntary-exit Riptide Pursuit."}]},{"id":"ELE-03-F","familyId":"voltfang","mode":"football","name":"Phase Release","category":"Self enhancement","activation":"Ready receiving-route snap","mechanic":"Temporary collision-and-jam bypass until first cut or pass release","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Automatically activate at a ready receiving-route snap; activation spends readiness even with no contact."},{"section":"Targets / placement","rule":"Zappard only. No teammate protection or persistent field."},{"section":"Core resolution","rule":"Ignore opposing body collisions and jams while phased; cannot block opponents during that state. No teleportation or Speed increase."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent offensive plays."},{"section":"Lifetime / persistence","rule":"Ends at the first designated route cut, QB pass release or whistle, whichever occurs first. Solidify before ball flight and resolve catches, interceptions and tackles normally."},{"section":"Exceptions / counterplay","rule":"Defenders track normally; no automatic separation or confusion. Fields and statuses still apply. Stunned or Knocked Down prevents activation or ends phasing."},{"section":"Visuals","rule":"Readable electrical silhouette while phased, returning to solid form at the endpoint."},{"section":"Progression / notes","rule":"Ability state, not an additional shared status. Mastery changes cooldown only."}]},{"id":"ELE-03-C","familyId":"voltfang","mode":"clash","name":"Phase Strike","category":"Shield bypass","activation":"Active enemy Shielded on eligible own action","mechanic":"Once-only attack bypasses shield absorption without removing shield pool","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, replace a normal attack when the active enemy is Shielded. No eligible target: ordinary attack and preserve use."},{"section":"Targets / placement","rule":"Active enemy only; its existing shield remains in place."},{"section":"Core resolution","rule":"Deal 100% / 110% / 120% / 130% normal attack damage directly to HP, bypassing shield absorption ONLY. Do not damage or strip the shield pool."},{"section":"Recharge / frequency","rule":"Once per Clash; normal evasion / decoys apply and a miss spends the use."},{"section":"Lifetime / persistence","rule":"Single special attack; no persistent mode or buff."},{"section":"Exceptions / counterplay","rule":"Type matchups, damage reduction, Tank guard, Guarded, hit caps and Last Root still work. Damage-triggered retaliation applies; shield-break triggers do not. No ordinary-only Striker shield-break perk on this special."},{"section":"Visuals","rule":"Electrical body passes through the visible shield, strikes the target and returns; shield remains visibly intact."},{"section":"Progression / notes","rule":"Striker retained. Unlike Wash Away, this does not remove a beneficial status."}]},{"id":"ELE-04-F","familyId":"stormlynx","mode":"football","name":"Static Field","category":"Zone","activation":"Ready defensive pre-play including first","mechanic":"Ready safety field spans fixed LB-to-safety depth band with entry stun","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Automatically create before a ready participating defensive scrimmage play, including the first. No tackle-earning requirement."},{"section":"Targets / placement","rule":"Twelve yards wide by seven yards long. Depth runs from five to twelve yards beyond upcoming LOS. Lateral center is Statyx initial alignment. Normal inward shift / boundary rules apply."},{"section":"Core resolution","rule":"Each non-Electric monster of either team independently rolls 15% Stunned on first entry; starting inside counts. No re-entry reroll and no total stun cap. Electric monsters are unaffected."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent defensive plays, starts on creation."},{"section":"Lifetime / persistence","rule":"One completed play INCLUDING spawn. Accepted Stunned lasts remainder of play and clears at whistle; normal status gate applies. Nonlegendary zone clears halftime / actual game end under normal rules."},{"section":"Exceptions / counterplay","rule":"REMOVE legacy catching penalty; do not combine the approved field with the old 10% catching restriction. This is not an Awareness or Coverage debuff."},{"section":"Visuals","rule":"Ground electrical lines, clear rectangle boundary and small sparks. Reveal before both teams select plays and lock initial placement. Screenshot preview was illustrative, not implementation."},{"section":"Progression / notes","rule":"Chance and geometry fixed across mastery; cooldown scales. Ask before creating future visual mockups."}]},{"id":"ELE-04-C","familyId":"stormlynx","mode":"clash","name":"Circuit Breaker","category":"Cooldown disruption","activation":"Active enemy ability currently recharging","mechanic":"Once-only attack extends running enemy ability cooldown by two owner turns","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, automatically replace normal attack when active opponent has an ability currently recharging. Otherwise attack normally and preserve use."},{"section":"Targets / placement","rule":"Among the active enemy’s currently running ability cooldowns, extend the one with the LEAST time remaining. Not limited to its signature. No running cooldown: ordinary attack, preserve use."},{"section":"Core resolution","rule":"Deal 100% / 110% / 120% / 130% normal attack damage by mastery. Connected hit adds TWO of target’s own normal turns to its remaining cooldown."},{"section":"Recharge / frequency","rule":"Once per Clash. Normal evasion; miss spends use without delay. Shield absorption still counts as connected for delay."},{"section":"Lifetime / persistence","rule":"Add two to the selected remaining cooldown counter and continue its ordinary schedule, including an upcoming target turn in the current round. No added grace round. Rotation preserves remaining cooldown and ordinary reserve pause rules."},{"section":"Exceptions / counterplay","rule":"Do not restore spent once-per-battle abilities, remove charges or disable passives. No shared status slot. No new instant action or global timing clock."},{"section":"Visuals","rule":"Jagged bolt followed by a brief broken-circuit symbol over the enemy ability indicator; no additional status badge."},{"section":"Progression / notes","rule":"Disruptor retained. Fixed two-turn extension; mastery scales attack damage only. Owner approved least-remaining running cooldown selection (2B). Stable tie handling must use the implementation’s deterministic ability ordering."}]},{"id":"ELE-05-F","familyId":"joltrex","mode":"football","name":"Chain Break","category":"Targeted effect","activation":"Successful ordinary block shed while ready","mechanic":"Successful shed arcs Stumbled to a different nearby engaged offensive blocker","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First successful ordinary block shed while ready, on either run or pass play."},{"section":"Targets / placement","rule":"Nearest DIFFERENT offensive monster currently engaged in blocking within three yards of Joltrex at shed time. Exclude the escaped blocker. Equal distance: stable lineup order. No eligible target: preserve readiness for later successful shed."},{"section":"Core resolution","rule":"Arc attempts Stumbled, removing 40% of current movement speed. Normal reacceleration applies; no maximum-Speed or other attribute reduction."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent defensive plays, starts when arc fires. Blocked status application still spends it."},{"section":"Lifetime / persistence","rule":"Accepted Stumbled clears at whistle, following shared status gate. One target per activation."},{"section":"Exceptions / counterplay","rule":"Target’s existing block continues normally; no automatic second shed. A stationary blocker loses no movement speed immediately. No hidden Strength or Blocking penalty."},{"section":"Visuals","rule":"Spark as Joltrex tears free, visible arc to second blocker, feet skid if Stumbled applies."},{"section":"Progression / notes","rule":"Rare standalone DL. Owner selected stable lineup tie-break. Normal shared status gate: a different existing status blocks Stumbled but the fired arc still spends readiness. No hidden stationary-block penalty."}]},{"id":"ELE-05-C","familyId":"joltrex","mode":"clash","name":"Victory Surge","category":"Knockout follow-up","activation":"Ordinary normal attack knocks out active enemy","mechanic":"Normal-attack knockout earns one immediate strike at chosen replacement","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, Joltrex personally knocks out active enemy with an ordinary normal attack. Reaction, special and damage-over-time knockouts do not qualify."},{"section":"Targets / placement","rule":"Opponent chooses replacement normally. Resolve its entry effects first. No living replacement / battle ended: no follow-up attack or animation."},{"section":"Core resolution","rule":"Follow-up deals 60% / 70% / 80% / 90% normal attack damage. Normal type, evasion, shields, Guarded and active Tank defense apply; miss spends follow-up."},{"section":"Recharge / frequency","rule":"Once per Clash; rotation and revival do not restore spent use."},{"section":"Lifetime / persistence","rule":"Immediate one-strike sequence. If replacement entry effects leave Joltrex knocked out or Stunned, surge is lost."},{"section":"Exceptions / counterplay","rule":"No further Victory Surge chain even on knockout. Follow-up grants no normal turn, attack-counter progress or ordinary-only archetype perks. Normal damage-triggered retaliation applies."},{"section":"Visuals","rule":"Knockout releases electricity into horns; after replacement arrives, Joltrex lunges as a lightning streak, strikes and returns."},{"section":"Progression / notes","rule":"Striker retained. Damage scales by mastery; no permanent attack boost from legacy Overcharge."}]},{"id":"ELE-06-F","familyId":"stormcrown","mode":"football","name":"Stormguard","category":"Special action","activation":"After eligible offensive passing play selected","mechanic":"Two real temporary electrical pass blockers outside both offensive line ends","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"After an eligible passing play is selected, including play-action and RPO passing options, summon if ready. Available on the first eligible play."},{"section":"Targets / placement","rule":"One guard just outside EACH end of offensive line, on offensive side of LOS. Find nearest legal empty spot on its respective side, remaining behind LOS. Summon only if BOTH can be legally placed; otherwise no guards, preserve readiness."},{"section":"Core resolution","rule":"Both guards provide pass protection using ordinary reach, movement, collision and block contests. Attributes are 60% / 65% / 70% / 75% of Voltarch PERMANENT Strength, Blocking, Speed, Agility and Awareness, rounded to whole ratings. No inherited temporary modifiers or separate stamina pool."},{"section":"Recharge / frequency","rule":"Fixed FIVE subsequent offensive plays cooldown; mastery improves guard ratings instead. Successful summon spends readiness even if neither guard engages."},{"section":"Lifetime / persistence","rule":"Remain through entire creation play and disappear at whistle. On an RPO run branch, remain but retain pass-protection assignments; never become lead blockers. No roster slot, independent progression or lasting injury."},{"section":"Exceptions / counterplay","rule":"Owner override: guards are immune to ALL statuses and environmental modifiers. Ordinary collision, block sheds and pushback still work. No ball handling, routes, tackles, pancakes, abilities or further summons. Track NO guard statistics and credit none to Voltarch; no extra participation XP or source ability triggers. Guard injuries disappear with them and never injure Voltarch."},{"section":"Visuals","rule":"Two lightning strikes, left and right of offensive line, spawn recognizable electrical blocker silhouettes with subtle sparks. Strikes cosmetic, no damage or obscuring cloud. User declined additional placement visual."},{"section":"Progression / notes","rule":"Legendary standalone QB. Earlier route-link and block-retry aura versions withdrawn. Owner closed placement, RPO branch, permanent-rating, immunity and no-stat boundaries. Physical knockdown must not bypass the explicit shared-status immunity. Implementation and balance checks remain."}]},{"id":"ELE-06-C","familyId":"stormcrown","mode":"clash","name":"Twin Thunder","category":"Setup constructs","activation":"First eligible own action summons instead of attacking","mechanic":"Two setup constructs bolt after future HP-damaging normal attacks against surviving active target","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, replace first eligible own normal action with summoning two guards. Stunned postpones setup until Voltarch can act."},{"section":"Targets / placement","rule":"After a qualifying normal attack that deals actual HP damage, one guard targets the SAME surviving ACTIVE enemy. Knockout, target removal or replacement before launch preserves guard; do not redirect or follow into reserve."},{"section":"Core resolution","rule":"Guard bolt deals 40% / 50% / 60% / 70% normal attack damage. Launch ONLY if Voltarch’s normal attack deals actual HP damage. Miss or full shield absorption preserves guard. Bolt uses separate evasion, type, shield and damage-reduction checks; launching spends it even if the bolt misses."},{"section":"Recharge / frequency","rule":"Once per Clash setup. No repeat summon after rotation or revival."},{"section":"Lifetime / persistence","rule":"Unused guards persist in reserve with no turn countdown. Voltarch KO removes them; revival does not restore use. Constructs have no HP, collision, shared status slots or independent turns."},{"section":"Exceptions / counterplay","rule":"Resolve retaliation from original attack FIRST. If Voltarch is then KO or Stunned, do not launch; surviving Stunned Voltarch retains unused guard. Bolts grant no extra turn, attack-counter progress or ordinary-only archetype perks and cannot trigger retaliation chains."},{"section":"Visuals","rule":"Two lightning strikes form guards beside Voltarch. Guards STAY STATIONARY and fire lightning bolts (owner 10B), disappearing after their individual launch."},{"section":"Progression / notes","rule":"Striker retained. Owner final closeout 9B requires actual HP damage, superseding earlier connected-hit wording; 10A preserves guard if original target is removed/replaced before launch. Setup and two finite constructs, not permanent attack growth."}]},{"id":"EAR-01-F","familyId":"pebble","mode":"football","name":"Clean Sweep","category":"Special action","activation":"Ordinary pancake earns later guarantee","mechanic":"Ordinary successful pancake banks one guaranteed pancake on a later participating play","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"An ordinary successful pancake earns one stored guarantee for a LATER participating offensive scrimmage play. Entire family specializes at OL."},{"section":"Targets / placement","rule":"First legal pancake opportunity on a later participating play; normal reach and engagement required. If no opportunity, preserve guarantee."},{"section":"Core resolution","rule":"Guaranteed success without pancake failure or stumble roll. Normal pancake Knocked Down recovery rules remain; explicit Knocked Down immunity still applies."},{"section":"Recharge / frequency","rule":"No additional cooldown. Maximum one stored guarantee. A guaranteed pancake NEVER earns another guarantee."},{"section":"Lifetime / persistence","rule":"Preserve through possession changes and halftime; clear at actual game end. Same mechanic across all evolutions and mastery."},{"section":"Exceptions / counterplay","rule":"No teleportation or extra reach. Use normal once-per-play pancake attempt budget. If current status/immunity blocks Knocked Down, skip that target and preserve guarantee until a legal opportunity; no shared-status override."},{"section":"Visuals","rule":"Stone-fist readiness indicator, forceful shoulder slam with stone fragments on use, ordinary pancake badge. Alternate readiness with shared badge when necessary."},{"section":"Progression / notes","rule":"Foundation zone and same-play bonus-attempt variants WITHDRAWN. This is not guaranteed pancakes every play."}]},{"id":"EAR-01-C","familyId":"pebble","mode":"clash","name":"Emergency Cover","category":"Lethal-hit interception","activation":"Reserve ally would lose active teammate to eligible direct hit","mechanic":"Reserve source intercepts one lethal direct hit damage without rotating or taking attached effects","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, living reserve Pebblit intervenes when a connected eligible direct hit would KO its active teammate after defenses. Stunned source cannot intervene. Cannot protect self."},{"section":"Targets / placement","rule":"Original active target resolves evasion first. Predict lethality before applying damage or spending survival abilities. Direct normal/special/follow-up hits eligible; DOT, transferred damage and retaliation excluded."},{"section":"Core resolution","rule":"Redirect DAMAGE ONLY to reserve source; recalculate against its own type, shield and applicable defenses. NO active-only Tank guard in reserve. No second evasion or consumption of attacker resources. Source can KO."},{"section":"Recharge / frequency","rule":"Once per Clash, no normal action cost. Remain in reserve; no positions change (owner 6B). Rotation / revival do not restore spent use."},{"section":"Lifetime / persistence","rule":"Only triggering hit is intercepted. Remaining multi-hit strikes stay aimed at original active monster; original attached effects also remain aimed there under normal rules (owner 8B)."},{"section":"Exceptions / counterplay","rule":"No heal, invulnerability or guaranteed survival. Multiple eligible reserve rescuers and same-hit survival ordering require deterministic audit resolution."},{"section":"Visuals","rule":"Reserve source visibly intercepts impact, then returns to its reserve position; do not animate a permanent active-position swap."},{"section":"Progression / notes","rule":"Tank retained. No progression scaling approved. Distinct from setup-based Shared Burden damage splitting and self-only Last Root."}]},{"id":"EAR-02-F","familyId":"rockram","mode":"football","name":"Stonewall Swat","category":"Targeted effect","activation":"Three low-yardage participating defensive plays","mechanic":"Banked low-yardage charge guarantees next legally launched forward pass becomes incomplete","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Three qualifying participating defensive scrimmage plays fill bar, maximum one charge per play. No personal tackle/assist/PBU required."},{"section":"Targets / placement","rule":"Qualifying opponent gain <=3 / <=4 / <=5 / <=6 yards by mastery, including losses and incompletions. Opponent touchdowns, special teams and two-point attempts excluded."},{"section":"Core resolution","rule":"Armed source targets first opposing forward pass RELEASED on a later participating defensive play, including play-action and RPO passing branches. Guaranteed breakup regardless distance; no interception, fumble, player damage or status."},{"section":"Recharge / frequency","rule":"Launch empties bar. No extra cooldown. Activation play cannot earn charge. Runs preserve readiness."},{"section":"Lifetime / persistence","rule":"Partial and full bars carry through possessions and halftime; actual game end clears. Craggo and Ramparte share progression thresholds."},{"section":"Exceptions / counterplay","rule":"Stunned / Knocked Down at release prevents launch and preserves bar. Ordinary block engagement does not prevent it. If multiple able users are armed, stable lineup order selects ONE; only its bar empties, others remain full."},{"section":"Visuals","rule":"Full charge becomes ready stone icon. At QB release, rock launches, visibly strikes football and causes incomplete pass; rock crumbles, no field obstacle."},{"section":"Progression / notes","rule":"Rock Roller proposal withdrawn. Incomplete-pass result must flow through ordinary down/clock/stat handling; do not create a catch then reverse it."}]},{"id":"EAR-02-C","familyId":"rockram","mode":"clash","name":"Rubble Reprisal","category":"Healing-triggered reaction","activation":"Active enemy receives actual HP healing while source ready","mechanic":"Active source reacts after enemy healing with one rock attack","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"While ready, source active and able to act; Stunned prevents reaction and preserves readiness. Active enemy must receive actual HP restoration, from self, ally or healing effect."},{"section":"Targets / placement","rule":"Same active enemy that was healed. Healing resolves first. A single healing event can trigger at most one rock."},{"section":"Core resolution","rule":"Craggo damage 60 / 65 / 70 / 75%; Ramparte 70 / 75 / 80 / 85% normal attack by mastery. Normal evasion, type, shields and applicable damage reduction."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent owner normal turns; application turn excluded, reserve pauses. Launch spends even on miss."},{"section":"Lifetime / persistence","rule":"Immediate reaction, not a stored normal attack or extra owner turn."},{"section":"Exceptions / counterplay","rule":"Shield grants, zero-HP overheal, fully blocked healing, revival and HP redistribution do not trigger. No attack-counter progress, stored-charge consumption, ordinary-only perks or retaliation chain."},{"section":"Visuals","rule":"Healing finishes; source stamps, raises loose stone and headbutts it toward opponent."},{"section":"Progression / notes","rule":"Balanced retained. Finish the entire originating healing ability, including shield or rotation effects, BEFORE reaction. Launch only if the same healed opponent remains active and source can act; otherwise preserve readiness."}]},{"id":"EAR-03-F","familyId":"boulderox","mode":"football","name":"Stone Charge","category":"Special action","activation":"Ready designed rushing carry with defender three yards ahead","mechanic":"Committed three-yard straight rush attempts one sideways contact displacement","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Designed rushing carry after secured handoff or direct snap. No receptions or returns. Activate while ready when defender within three yards ahead of current rushing direction."},{"section":"Targets / placement","rule":"First defender contacted during up-to-three-yard committed travel. No contact: still spends readiness."},{"section":"Core resolution","rule":"Hold current heading until three yards traveled, first contact or whistle. Normal Speed/acceleration. On contact, normal Strength-vs-Strength pushback contest; success moves defender one yard sideways toward nearest legal open side."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent offensive plays, spent on activation."},{"section":"Lifetime / persistence","rule":"Commitment ends on contact or whistle / travel limit. No persistent field or shared status."},{"section":"Exceptions / counterplay","rule":"Failure: ordinary tackle resolution. Success: normal tackle still applies if defender in reach. No automatic tackle break, fumble protection, immunity or credited bonus yards. One contact attempt."},{"section":"Visuals","rule":"Owner 10B: translucent BOULDER SHELL surrounds source during charge. Do not retain only the original stone-plate/dust version."},{"section":"Progression / notes","rule":"Uncommon standalone RB. Source legacy +10 carry Strength removed; new ability uses ordinary attributes without adding any."}]},{"id":"EAR-03-C","familyId":"boulderox","mode":"clash","name":"Unbroken Charge","category":"Stun-response special","activation":"Actually skip normal action due to Stunned","mechanic":"Stunned skipped action arms next performed normal-action undodgeable charge","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Actually losing a normal action to Stunned arms once-per-Clash charge. Merely receiving Stunned is not sufficient."},{"section":"Targets / placement","rule":"Next performed normal attack targets enemy then active, not necessarily original stun source. Further Stunned skips preserve armed charge."},{"section":"Core resolution","rule":"150 / 160 / 170 / 180% normal attack by mastery, undodgeable including decoys. Normal type, shield, Guarded, active Tank protection and survival abilities apply."},{"section":"Recharge / frequency","rule":"Once per Clash, committed when charge FIRST ARMS. Costs next performed normal action; counts as performed attack for normal attack counters. No ordinary-only archetype perks; normal retaliation applies."},{"section":"Lifetime / persistence","rule":"Armed charge survives rotation; KO clears it. Revival cannot restore a spent use."},{"section":"Exceptions / counterplay","rule":"No stun immunity, cleanse, bonus action or permanent attribute boost. Arming commits use. KO destroys unused armed charge and revival cannot rearm or restore it."},{"section":"Visuals","rule":"Glowing cracks when skipped turn arms ability; translucent boulder shell forms as source charges, hits and returns."},{"section":"Progression / notes","rule":"Tank retained. Do not silently convert charge into immediate reaction when Stunned expires."}]},{"id":"EAR-04-F","familyId":"stoneguard","mode":"football","name":"Stone Cradle","category":"Special action","activation":"First eligible caught punt in field of play","mechanic":"Once-game caught-punt return ends immediately at catch spot","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per game, automatically on first eligible Granigor punt caught inside field of play. Granigor approved primary K."},{"section":"Targets / placement","rule":"Receiving opponent at secured catch spot. Punts ONLY, not kickoffs. Normal punt distance and placement still use Kicking."},{"section":"Core resolution","rule":"Stone cuffs trap legs, immediate whistle at catch spot, ZERO return yards. No live immobilized-player tackle sequence."},{"section":"Recharge / frequency","rule":"Once per game, no mastery scaling. Touchback, out-of-bounds punt and fair catch preserve use."},{"section":"Lifetime / persistence","rule":"Stone disappears after whistle. Actual game includes overtime; no refresh at halftime or possession change."},{"section":"Exceptions / counterplay","rule":"Special kick-ending rule, not shared status; Earth typing / existing statuses do not block. End-zone catches follow ordinary touchback rules, never force safety. Blocked / downed punts require ordinary result mapping, not invented roll simulation."},{"section":"Visuals","rule":"Stone cuffs form around both legs, then crumble after whistle; no lingering obstacle or field."},{"section":"Progression / notes","rule":"All bounce/roll Stone Cradle and Heavy Return proposals withdrawn. Current engine resolves punts abstractly; no new bounce system requested."}]},{"id":"EAR-04-C","familyId":"stoneguard","mode":"clash","name":"Bank Shot","category":"Shield ricochet","activation":"Shielded active enemy plus living reserve","mechanic":"Once special attacks shield then ricochets to last reserve if shield HP removed","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash replace normal attack when enemy active is Shielded and has living reserve. Otherwise ordinary attack, preserve use."},{"section":"Targets / placement","rule":"Primary active target. Secondary LAST living enemy in reserve order."},{"section":"Core resolution","rule":"Primary 100% normal attack with normal defenses/evasion. If removes at least one shield HP, launch ricochet for 50 / 60 / 70 / 80% normal attack by mastery. Shield need not break."},{"section":"Recharge / frequency","rule":"Launching primary spends use even if misses or no ricochet. No additional normal action for bounce."},{"section":"Lifetime / persistence","rule":"Primary retaliation resolves before bounce. If source KO or Stunned, cancel ricochet. Maximum one bounce."},{"section":"Exceptions / counterplay","rule":"Secondary normal type/evasion/shield/DR; no active-only Tank guard in reserve. No secondary retaliation chains or extra charge consumption. Neither hit receives ordinary-only Striker perks."},{"section":"Visuals","rule":"Short kicking approach, boot stone into shield, visible direction change to reserve, shatter on impact."},{"section":"Progression / notes","rule":"Striker retained. Distinct from miss-triggered Arc Rebound and shield-bypassing Phase Strike."}]},{"id":"EAR-05-F","familyId":"terrabull","mode":"football","name":"Stone Screen","category":"Special action","activation":"Reception at least five yards beyond LOS","mechanic":"Catch creates moving one-sided physical stone wall for five further forward yards","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Secure reception at least FIVE yards beyond LOS while ready. No handoffs, returns or blocking-only activation."},{"section":"Targets / placement","rule":"Nearest defender determines side at catch; equal distance uses stable lineup order. THREE-yard width, HALF-yard thickness, ONE-yard clear gap between owner body and near wall face. Lock field orientation, never rotate toward new threats."},{"section":"Core resolution","rule":"Wall follows Terrabull UNTIL first obstructing defender contact, then stops moving and remains a STATIONARY physical barrier until existing distance/whistle expiration. Defenders must go around. No push, damage, status, automatic tackle break or fumble protection; other approaches remain open."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent offensive plays, spent on successful creation. Illegal overlapping/trapping placement: preserve readiness."},{"section":"Lifetime / persistence","rule":"Ends after FIVE additional forward yards after activation or whistle. No seconds-based duration; no next-play obstacle."},{"section":"Exceptions / counterplay","rule":"Not a zone, status or extra monster. Never spawn through/trap a monster; illegal overlap or boundary placement preserves readiness. Moving wall STOPS on obstructing defender contact; never displaces the defender."},{"section":"Visuals","rule":"Jagged slab rises, travels with visible ground seam, then cracks into fading rubble. Ask before generating visual preview."},{"section":"Progression / notes","rule":"Rare standalone TE. Prior Quake Step proposals WITHDRAWN. Similarity to Stormguard is acknowledged but wall has no AI, attributes or block contests."}]},{"id":"EAR-05-C","familyId":"terrabull","mode":"clash","name":"Stone Divide","category":"Extra-attack denial","activation":"Active non-Stunned source observes enemy extra strike","mechanic":"Once automatic wall cancels enemy follow-up or attack retaliation before evasion and damage","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, source ACTIVE and not Stunned, automatically intercept first eligible enemy extra strike."},{"section":"Targets / placement","rule":"Any living teammate, self or reserve. Includes Twin Thunder bolt, Victory Surge, Arc Rebound, Riptide Pursuit and attack-based retaliation."},{"section":"Core resolution","rule":"Cancel ONE strike and its attached effects BEFORE evasion or damage. Do not consume target dodge / shield. Intercepted attack counts as launched and attacker resources remain spent."},{"section":"Recharge / frequency","rule":"No normal action cost; once per Clash, no mastery scaling. Rotation/revival do not restore spent use."},{"section":"Lifetime / persistence","rule":"Instant interception; subsequent remaining strikes resolve normally. No persistent shield or field."},{"section":"Exceptions / counterplay","rule":"N9d: ordinary attacks, normal-action specials and their secondary/commanded/assist hits, delayed impacts, DOT and transferred damage remain unaffected. Intercept eligible attack-triggered retaliation, including Molten Brand eruption. Healing-triggered Rubble Reprisal is unaffected. Preserve explicit Twin Thunder, Victory Surge, Arc Rebound and Riptide Pursuit inclusions and the active/able/once-use restrictions.","ruling":"N9d","supersededRule":"Ordinary attacks, normal-action specials, delayed meteors/fissures, DOT and transferred damage unaffected. No reflection, bonus attack, HP pool or attributes."},{"section":"Visuals","rule":"Tall slab erupts between attacker and target, takes impact, collapses. No persistent obstacle or status."},{"section":"Progression / notes","rule":"Disruptor retained. Requires explicit attack-kind tags shared with earlier mode signatures; never guess from animation alone."}],"ruling":"N9d"},{"id":"EAR-06-F","familyId":"titanolith","mode":"football","name":"Landslide","category":"Special action","activation":"First eligible offensive snap each possession","mechanic":"Snap slam creates advancing full-front rock wall with guaranteed bounded displacement","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per offensive possession at first eligible offensive scrimmage snap, run or pass. Stunned / Knocked Down prevents activation, preserving use for later snap that possession."},{"section":"Targets / placement","rule":"At snap, target defenders aligned within TWO yards on defensive side of LOS, including front-aligned edge rushers/blitzers. Wall spans the full qualified front, outermost to outermost; rear off-ball defenders are not included."},{"section":"Core resolution","rule":"Guaranteed push 2 / 2.5 / 3 / 3.5 yards toward defenders own end zone by mastery. NO Strength contest. Explicit displacement immunity and physical obstructions still apply."},{"section":"Recharge / frequency","rule":"Firing spends possession use even if immunity prevents movement. Special teams and two-point attempts excluded."},{"section":"Lifetime / persistence","rule":"Wall advances through approved push distance and immediately crumbles. No lingering blocker or extra status; normal defender actions resume after push."},{"section":"Exceptions / counterplay","rule":"Instant action / physical wall, not Earth zone; no same-type field immunity. Cannot push through obstruction or award automatic rushing yards. Remove legacy guaranteed pass-block wins and +2 rush yards."},{"section":"Visuals","rule":"Both fists strike turf; continuous stone wall erupts across front, surges forward carrying targets back, fractures into fading rubble."},{"section":"Progression / notes","rule":"Legendary standalone OL. Owner approved two-yard snap-alignment frontline definition. Keep guaranteed bounded push at 2 / 2.5 / 3 / 3.5 yards and explicit obstruction/immunity handling."}]},{"id":"EAR-06-C","familyId":"titanolith","mode":"clash","name":"Mountain Shelter","category":"Team Guarded replacement","activation":"Own action when any living teammate at <=50 percent HP","mechanic":"Once normal action guarantees team Guarded overriding all prior shared statuses","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash replace normal action when any living teammate INCLUDING self is <=50% HP. Otherwise ordinary attack, preserve use. Stunned prevents activation and preserves readiness."},{"section":"Targets / placement","rule":"EVERY living teammate, including source and reserves, GUARANTEED. No eligible-other-recipient prerequisite. Never revive KO monsters."},{"section":"Core resolution","rule":"Guarded reduces incoming attacks/reactions/DOT by 30 / 35 / 40 / 45% by mastery. Explicit owner exception: REPLACE existing harmful or beneficial status, even uncleansable; remove replaced Shielded pool. One active status/badge remains."},{"section":"Recharge / frequency","rule":"Once per Clash; no refresh on rotation or revival. Uses normal action instead of attack. No damage reflection, HP healing or shield pool."},{"section":"Lifetime / persistence","rule":"Two RECIPIENT normal turns, application turn excluded. Reserve pauses; Stunned-skipped turns count. Protection independent after source leaves or KO. Clear on entering football under existing unsupported-mode rule."},{"section":"Exceptions / counterplay","rule":"Guaranteed replacement also applies to already Guarded allies: replace with a FRESH episode at Titanolith mastery strength and TWO recipient normal turns, even if old Guarded was stronger/longer. No additive old duration; bypass old episode application cap. Other later applications follow normal shared status rules."},{"section":"Visuals","rule":"Stone arches briefly rise over each protected monster then dissolve into standard Guarded badge. No persistent canopy clutter."},{"section":"Progression / notes","rule":"Tank retained. No blanket change to other cleanse/stack rules. Original largest entry shield / immovable legacy signature replaced."}]},{"id":"ICE-01-F","familyId":"snowmoth","mode":"football","name":"Frostmark","category":"Zone","activation":"Made field goal earns next opposing-offense field","mechanic":"Made field goal banks fixed-size random Ice braking patch for later defensive series","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Successful field goal ONLY, regardless distance. Extra points excluded. Each made field goal may earn max ONE pending field; no extra cooldown."},{"section":"Targets / placement","rule":"Eight yards WIDE by six yards LONG. Randomize lateral and depth placement, keeping ENTIRE rectangle between opponent upcoming LOS and fixed 12-yard safety-depth reference. Normal playable boundaries. This replaces fixed-center and 5-to-11-depth proposals."},{"section":"Core resolution","rule":"Ice reduces braking deceleration 20% Flurrit / 25% Blizzmoth. Both teams non-Ice affected; Ice receives neither benefit nor penalty. No max Speed / acceleration / catching penalty or automatic Stumbled/Stunned."},{"section":"Recharge / frequency","rule":"No additional cooldown. Fixed geometry and strength by form; mastery changes lifetime. Maximum one pending token."},{"section":"Lifetime / persistence","rule":"Next opposing offensive scrimmage pre-play, even while kicker benched. Reveal BEFORE both play choices and lock; formation changes do not reroll. 1/2/3/4 completed opposing offensive scrimmage plays INCLUDING spawn; stationary world location after spawn."},{"section":"Exceptions / counterplay","rule":"Kickoffs do not consume pending activation. Pending survives possession changes/halftime; created field clears halftime under nonlegendary rule; actual game end clears all. Missed FG cannot earn it."},{"section":"Visuals","rule":"Frost sweeps across flat translucent rectangle, clear boundary and readable yard lines. Owner-requested example preview generated; random placement is not locked to pictured location. Ask before future visuals."},{"section":"Progression / notes","rule":"Common K family, rarity fixed across evolution. Owner explicitly likes FG-vs-touchdown trade-off and team-neutral risk. Braking change is environmental, not shared status."}]},{"id":"ICE-01-C","familyId":"snowmoth","mode":"clash","name":"Fresh Start","category":"Ally cooldown support","activation":"Eligible other living ally cooldown while source ready","mechanic":"Replace attack to reduce longest-running other ally ability cooldown","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"While ready, replace normal attack if another living teammate has eligible cooldown running. Otherwise ordinary attack and preserve readiness. Stunned prevents use, preserves readiness."},{"section":"Targets / placement","rule":"Other living teammates including reserves, never self. Select individual eligible ability with MOST cooldown turns remaining; tie uses stable lineup order."},{"section":"Core resolution","rule":"Flurrit removes ONE remaining turn; Blizzmoth TWO, minimum zero. No extra normal action or attack."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent OWNER normal turns, setup/application turn excluded. Reserve pauses; Stunned skipped normal turns count."},{"section":"Lifetime / persistence","rule":"Reaching zero restores readiness only. Requires next ordinary legal trigger; never replay missed entry trigger or immediately activate ability."},{"section":"Exceptions / counterplay","rule":"Running ability cooldowns ONLY. No stored-charge refill, once-per-Clash reset, status-duration change, cleanse or status-slot occupation. Multiple timers on one tied ally require stable secondary ordering."},{"section":"Visuals","rule":"Snowflakes travel to ally; existing ability indicator flashes as TURN count decreases. No new head/status badge or seconds clock."},{"section":"Progression / notes","rule":"Support retained. Old periodic entry-shield support replaced. Distinct resource help from Second Tide healing and Lightning Rod transfer."}]},{"id":"ICE-02-F","familyId":"hailfang","mode":"football","name":"Frost Nip","category":"Targeted effect","activation":"Tracked route receiver reaches two-yard separation before pass release","mechanic":"Pre-pass separation triggers targeted current-play Slowed snowball","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Keep CB for both forms. While ready before pass release, tracked route-running receiver reaches at least TWO yards separation, no cut requirement (owner 2B)."},{"section":"Targets / placement","rule":"Assigned receiver in man coverage; currently tracked receiver in zone. Must remain within FOUR yards at activation."},{"section":"Core resolution","rule":"Attempt Slowed: Frostpup 15%, Hoarhound 20% max movement-speed reduction. No direct damage, automatic PBU or separate evasion roll; normal shared-status gate."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent defensive plays. Firing spends readiness even if existing status blocks application."},{"section":"Lifetime / persistence","rule":"B: Receiver must remain eligible until snowball impact. Pass release before impact cancels the snowball and Slowed application; play ending also cancels it. Firing still spends readiness. No added random miss chance. If applied, Slowed lasts current play only and clears at whistle."},{"section":"Exceptions / counterplay","rule":"Stunned or Knocked Down prevents source activation and preserves readiness. At impact recheck tracked route receiver, two-yard separation, four-yard range and pre-release eligibility. If no longer eligible, cancel without applying status; launched use remains spent."},{"section":"Visuals","rule":"Owner override: FIRE A SNOWBALL at receiver. Standard Slowed badge only if applied. No frozen legs, ground field or jaw-breath alternative."},{"section":"Progression / notes","rule":"Cold Trail route-reveal proposal withdrawn. Evolution keeps common rarity and CB. Different from Water-zone Stumbled and maximum-speed-neutral current-speed loss."}]},{"id":"ICE-02-C","familyId":"hailfang","mode":"clash","name":"Cold Welcome","category":"Voluntary-entry disruption","activation":"Successful enemy voluntary rotation while source active and ready","mechanic":"Incoming enemy after entry effects receives attempted Slowed","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Source ACTIVE and not Stunned. Successful enemy voluntary rotation only; exclude forced rotation and KO replacement."},{"section":"Targets / placement","rule":"Incoming replacement AFTER all its entry effects resolve. Source must still be able to act; otherwise preserve readiness."},{"section":"Core resolution","rule":"Attempt Slowed 15% Frostpup / 20% Hoarhound initiative reduction. No damage, separate evasion roll or extra normal action."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent source normal turns; reserve pauses, Stunned skips count. Throwing spends readiness even if status blocked."},{"section":"Lifetime / persistence","rule":"TWO recipient normal turns, application turn excluded. Recipient reserve pauses countdown."},{"section":"Exceptions / counterplay","rule":"Ordinary shared-status rules. Incoming Shielded or any different status blocks Slowed; do not strip protection. No rotation prevention or pursuit damage."},{"section":"Visuals","rule":"Snowball at incoming enemy then standard Slowed badge if applied."},{"section":"Progression / notes","rule":"Disruptor retained. Riptide Pursuit targets departing enemy with damage; this affects arrival initiative after entry protection."}]},{"id":"ICE-03-F","familyId":"frostclaw","mode":"football","name":"Snowfall Slam","category":"Special action","activation":"Three participating low-yardage defensive plays charge next snap","mechanic":"Stationary summoning of two random snowballs that stun offense or remain as bilateral obstacles","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Three participating defensive scrimmage plays allowing <=THREE yards fill bar, max one per play. Include losses/incompletions; no personal credit needed. Touchdowns, special teams and two-point attempts excluded."},{"section":"Targets / placement","rule":"Next participating defensive scrimmage snap after full bar. Two independently random NONOVERLAPPING legal footprints between LOS and FIVE yards into offensive backfield, across full legal width. TWO-yard-diameter snowballs."},{"section":"Core resolution","rule":"At impact, check actual occupancy, not launch occupants. Offensive hit: attempt Stunned at 20/25/30/35% by mastery; ball disappears regardless blocked status. Miss: physical obstacle blocks BOTH teams, no damage/status on later contact."},{"section":"Recharge / frequency","rule":"Summon starts -> empty bar. Activation play earns no charge; no extra cooldown. Maximum one banked summon."},{"section":"Lifetime / persistence","rule":"Landing markers at snap. Source cannot move/cover/block/tackle until BOTH land, then resumes assignment subject to other statuses. Fixed landing-animation duration is a balance-testing parameter, not a play/turn duration or pause of live game. Obstacles and accepted impact Stunned clear whistle."},{"section":"Exceptions / counterplay","rule":"A: If no offensive target is hit but a defender occupies landing footprint, snowball crumbles without Stunned or obstacle. Never trap or displace that defender. A: Each offensive player within landing footprint receives an independent mastery-based Stunned roll through normal shared-status gate. Snowball disappears after offensive impact, regardless of roll or blocked status. Obstacles affect both teams physically, including Ice. No football displacement or extra damage."},{"section":"Visuals","rule":"Ground slam, two visible shadow markers, two snowballs fall. On offensive impact burst away; otherwise remain solid route/lane obstacles. Source visibly occupied through landing."},{"section":"Progression / notes","rule":"False Blitz decoy withdrawn. Uncommon standalone LB. Explicit trade-offs: abandoned coverage during cast and obstacles can hinder own defense."}]},{"id":"ICE-03-C","familyId":"frostclaw","mode":"clash","name":"Snowbank Shot","category":"Attack with defensive miss fallback","activation":"Ready own normal action","mechanic":"Oversized snowball attack with extra accuracy check and Shielded fallback on miss","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Replace normal attack while ready. Stunned prevents activation and preserves readiness."},{"section":"Targets / placement","rule":"Enemy active; normal attack targeting and current applicable redirection rules. No reserve splash."},{"section":"Core resolution","rule":"80% LAUNCH accuracy check first, then ordinary target evasion. Failed launch does NOT consume target dodge/decoy. Connected damage 130% normal, type/shield/DR normal."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent owner normal turns, spent on launch. Costs normal action. No extra attack, ordinary-only archetype perks or second attack-charge consumption."},{"section":"Lifetime / persistence","rule":"Launch miss or enemy evasion attempts Shielded worth 20% source max HP, TWO owner normal turns, application turn excluded, reserve pauses."},{"section":"Exceptions / counterplay","rule":"Normal status gate: other status can block fallback; equal shield strength extends duration without pool refill. Full absorption by enemy shield is CONNECTED, no fallback. Normal connected-damage retaliation."},{"section":"Visuals","rule":"Pack oversized snowball, launch. Miss bursts into snow that whips back to form personal barrier, then standard Shielded badge/pool."},{"section":"Progression / notes","rule":"Balanced retained. Accuracy/damage/shield fixed, mastery cooldown only. No independent cloak/icebody status. Distinct from offensive reserve-target Arc Rebound after miss."}]},{"id":"ICE-04-F","familyId":"icehorn","mode":"football","name":"Permafrost","category":"Zone","activation":"Personal TFL or sack earns later backfield Ice zone","mechanic":"Personal negative-yardage stop banks fixed quarterback-aligned backfield braking patch","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Personal tackle-for-loss or sack while ready; assisted credit qualifies, zero-yard stop does not. Primary position DL, no evolution."},{"section":"Targets / placement","rule":"Next participating defensive scrimmage pre-play: TEN yards wide by SIX yards long, from upcoming LOS SIX yards into OFFENSIVE BACKFIELD. Lateral center QB initial alignment. Reveal before both play choices, then lock; ordinary boundary rules."},{"section":"Core resolution","rule":"30% reduced braking deceleration for both teams non-Ice. Ice unaffected. Normal maximum Speed/acceleration. No auto Stumbled/Stunned or automatic yardage subtraction."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent defensive plays starts CREATION. Cannot earn again during creation play; max ONE pending zone."},{"section":"Lifetime / persistence","rule":"TWO completed defensive scrimmage plays INCLUDING creation. Stationary world location after spawn, not moved with later LOS."},{"section":"Exceptions / counterplay","rule":"Pending survives possession changes / halftime. Created field clears halftime; actual end clears all. Shared field overlap rules. Live QB can move out; defenders chasing into field also suffer braking penalty."},{"section":"Visuals","rule":"Both front hooves stamp, frost wave spreads across readable flat rectangle. No physical wall."},{"section":"Progression / notes","rule":"Zone exception permits same Ice effect as Frostmark; distinct stop trigger and fixed backfield placement. Remove old subtract-one-yard Permafrost."}]},{"id":"ICE-04-C","familyId":"icehorn","mode":"clash","name":"Snowdrift Shelter","category":"Self Guarded preparation","activation":"Ready source at <=50 percent HP and empty shared status slot","mechanic":"Sacrifice attack for one-next-owner-turn self Guarded shelter","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"At <=50% HP while ready and own status slot EMPTY, replace normal attack with preparation. Otherwise ordinary attack and preserve readiness. Stunned prevents setup."},{"section":"Targets / placement","rule":"Self only. Apply Guarded 50% incoming damage reduction; normal active Tank protection still follows existing scope."},{"section":"Core resolution","rule":"No heal, cleanse, shield pool, immunity, guaranteed survival or attack bonus. Defense only, no offensive armor cash-out."},{"section":"Recharge / frequency","rule":"Cooldown 5/4/3/2 subsequent owner normal turns begins setup. Mastery cooldown only; protection fixed."},{"section":"Lifetime / persistence","rule":"Guarded lasts through NEXT owner normal turn and expires at that turn END. Setup turn excluded. On next turn emerge and perform ordinary legal action. Reserve pauses status and cooldown."},{"section":"Exceptions / counterplay","rule":"Normal shared-status rules; later replacement/removal follows those rules. No rotation refresh or source maxHP change."},{"section":"Visuals","rule":"Snow mound surrounds source with horns visible. Burst out on next action, standard Guarded badge, no second custom status."},{"section":"Progression / notes","rule":"Tank retained by owner choice. Packed Avalanche and Glacial Claim proposals withdrawn; no protection theft or guard-to-damage conversion."}]},{"id":"ICE-05-F","familyId":"glaciron","mode":"football","name":"Cold Snap","category":"Aura","activation":"First enemy new activation while source block-engaged","mechanic":"Blocking-dependent three-yard aura suppresses one enemy new ability for rest of current play","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Source OL, blocking assignment AND actually block-engaged, while ready. Stunned / Knocked Down prevents activation."},{"section":"Targets / placement","rule":"THREE-yard aura follows source. First opposing monster attempting NEW ability inside range; simultaneous attempts use stable lineup order."},{"section":"Core resolution","rule":"B: Suppressed enemy cannot activate its ability OR gain new ability charge for remainder of current play, even after leaving aura. Existing charge / readiness remains intact and no enemy ability cooldown is spent. Suppression begins at blocked activation; earlier charge gain is not undone. Only first eligible enemy per source activation; simultaneous attempts use stable lineup order."},{"section":"Recharge / frequency","rule":"One enemy per activation, cooldown 5/4/3/2 subsequent OFFENSIVE plays. Enemy retains charge/readiness and spends no activation cooldown."},{"section":"Lifetime / persistence","rule":"Suppression ends whistle. Later play requires ordinary legal trigger; do not auto-fire or replay earlier event."},{"section":"Exceptions / counterplay","rule":"No canceling already active effects, passives, fields or launched objects. Suppression is ability state, not shared status; existing status cannot block it. Source Stunned / Knocked Down prevents activation. Enemy must meet a fresh legal trigger on a later play; no automatic replay."},{"section":"Visuals","rule":"Low frost ring while aura active; pulse briefly crystallizes affected enemy ABILITY indicator, separate from shared status badge."},{"section":"Progression / notes","rule":"Rare OL. Owner chose Aura over missing Self enhancement category. Ice Lock / Icebound Recovery withdrawn. Shares broad activation-denial theme with Eclipse; finite one-target blocking-dependent cooldown identity explicitly reviewed."}]},{"id":"ICE-05-C","familyId":"glaciron","mode":"clash","name":"Glacier Wall","category":"Original shield rebuild","activation":"First active entry plus first eligible depletion of own original shield","mechanic":"Entry shield with once-only smaller rebuild after full hit/effects resolution","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"First ACTIVE entry including opening active attempts Shielded worth 20% maximum HP. Blocked application spends initial entry opportunity."},{"section":"Targets / placement","rule":"Only original Glacier Wall-created shield may trigger rebuild. Stronger other-source replacement removes eligibility; original equal duration extension retains ownership under existing rule."},{"section":"Core resolution","rule":"A: After each complete individual enemy direct hit and its attached effects, surviving Shardok may attempt once-only smaller rebuild if its original own pool was depleted. Rebuild can protect against later strikes in same action, never triggering-hit overflow. Rebuilt pool 10 / 12 / 14 / 16% maximum HP for two recipient normal turns by mastery. Blocked rebuild attempt is spent."},{"section":"Recharge / frequency","rule":"ONE rebuild per Clash, no normal action cost. Blocked rebuild spends opportunity. Rebuilt shield NEVER rebuilds again. Rotation/revival restores neither opportunity."},{"section":"Lifetime / persistence","rule":"Initial THREE owner normal turns; rebuilt TWO owner normal turns; application turn excluded, reserve pauses."},{"section":"Exceptions / counterplay","rule":"No rebuild for expiry/status removal. Cannot undo overflow HP damage or prevent an already-caused KO. Both applications use normal shared-status gate; attached harmful status may block replacement."},{"section":"Visuals","rule":"Ice plates on entry. Original breaks to fragments, reassembles visibly smaller and cracked. Standard Shielded badge and pool."},{"section":"Progression / notes","rule":"Tank retained. Only rebuilt pool scales mastery. Legacy immediate same-size regrow occurs too early and must be replaced, not reused unchanged."}]},{"id":"ICE-06-F","familyId":"glacivern","mode":"football","name":"Second Chance","category":"Special action","activation":"First eligible missed field goal in game","mechanic":"Once-game failed FG reroll at original distance before result finalization","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Legendary primary K per approved roster amendment. Automatic on first eligible missed FIELD GOAL; extra points and blocked kicks excluded. Wide/short qualify."},{"section":"Targets / placement","rule":"Same football, original kick distance and currently applicable kicking conditions. Fresh ordinary FG success check; not guaranteed success."},{"section":"Core resolution","rule":"B: Record TWO field-goal attempts: initial miss plus retry. Retry success records one make; double miss records zero makes. One football play, one clock runoff and one final score / possession resolution. Log both checks and ability use. Fresh normal success check from original distance and applicable conditions, no guaranteed score."},{"section":"Recharge / frequency","rule":"ONCE per GAME including overtime. Rescue attempt spends use whether succeeds/fails; original success preserves use."},{"section":"Lifetime / persistence","rule":"One original kicking play with two checks, not a bonus play. No halftime refresh or separate mastery scaling."},{"section":"Exceptions / counterplay","rule":"Only first eligible missed field goal, not extra point or blocked kick; current resolver has no blocked-kick mechanic, do not invent one. Successful original kick preserves use. Final good result alone awards three points and triggers made-field-goal abilities once."},{"section":"Visuals","rule":"Before final miss declaration, Glacivern launches ice shard into football to visibly redirect toward uprights. Resolve final good/miss once."},{"section":"Progression / notes","rule":"Old safety Whiteout Football signature superseded by approved K identity. Distinct from Ripplet dropped-catch retry in trigger/scoring/frequency."}]},{"id":"ICE-06-C","familyId":"glacivern","mode":"clash","name":"Deep Winter","category":"Harmful-status countdown freeze","activation":"Own action when living enemy has existing harmful status","mechanic":"Once action pauses existing enemy harmful status expiration for two recipient normal turns","designStatus":"Core approved; engine work required","details":[{"section":"Trigger / eligibility","rule":"Once per Clash replace own normal action when at least one living enemy has harmful status. Otherwise ordinary attack, preserve use. Stunned prevents activation, preserves readiness."},{"section":"Targets / placement","rule":"ALL living enemies including reserves with harmful status ALREADY present at activation. No new status is created; later new statuses count normally."},{"section":"Core resolution","rule":"Freeze EXPIRATION countdown for next TWO recipient normal turns. Existing count stays unchanged through those turns. Harmful strength/effects continue: Afflicted ticks normally, Stunned skips subject to consecutive-action safeguards."},{"section":"Recharge / frequency","rule":"Once per Clash, no damage or mastery scaling. Freezing neither consumes nor resets episode three-application cap."},{"section":"Lifetime / persistence","rule":"Recipient reserve pauses freeze duration. After two affected normal turns, thaw; ordinary status countdown resumes following normal turn. A: Carry remaining frozen turns into football as same number of frozen participating plays, and remaining frozen plays into Clash as recipient normal turns. Underlying status also carries normally. Bench / reserve pauses both. Continue existing mode-specific harmful effects and safeguards. No extra DOT tick at application."},{"section":"Exceptions / counterplay","rule":"B: Successful new application of same harmful status ends that status episode's Deep Winter freeze, including accepted equal-strength duration extension or stronger replacement. Ignored weaker / rejected application does not end freeze. Normal strength, duration and three-application cap remain. Cleanse removes underlying status and ends its freeze; uncleansable restrictions remain. Existing consecutive-action Stunned safeguard still applies."},{"section":"Visuals","rule":"Blizzard across enemy lineup; ICE ENCASES EXISTING STATUS BADGE, count readable. No additional status badge or full-body freeze. Thaw visual when expiration resumes."},{"section":"Progression / notes","rule":"Disruptor retained. Direct add-two-turn extension proposal withdrawn. Must separate harmful effect execution from expiration decrement, not freeze whole status tick."}]},{"id":"WIN-01-F","familyId":"gustling","mode":"football","name":"Runway","category":"Zone","activation":"Gustling; common; WR; Before BOTH play choices on next participating offensive scrimmage snap while ready. Activate regardless of later route-running or blocking assignment; never read future selected play.","mechanic":"Pre-choice receiver-aligned Wind speed corridor with evolution-scaled bonus","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Gustling; common; WR; Before BOTH play choices on next participating offensive scrimmage snap while ready. Activate regardless of later route-running or blocking assignment; never read future selected play."},{"section":"Targets / placement","rule":"Stationary Wind rectangle at upcoming LOS: 6 yards wide, 10 long into defense, centered on initial receiver lateral alignment. Clip to legal field; do not follow routes."},{"section":"Core resolution","rule":"Non-Wind monsters of BOTH teams gain +15 / +20 / +25% maximum movement speed by Gustling / Squallow / Stratosoar. Acceleration unchanged; entering/leaving adds/removes modifier."},{"section":"Recharge / frequency","rule":"Cooldown 6 / 5 / 4 / 3 subsequent participating offensive plays, starts creation; creating play excluded."},{"section":"Lifetime / persistence","rule":"Spawn play counts for field life. Pending readiness carries possessions/halftime; created common field clears halftime. No special-team activation."},{"section":"Exceptions / counterplay","rule":"Defenders can use runway too. Same-type immunity includes no speed bonus. No catch guarantee or altered route."},{"section":"Visuals","rule":"A pale teal gust paints parallel runway lines; readable boundary and yard marks, no head icon."},{"section":"Progression / notes","rule":"Lifetime 1 / 1 / 2 / 2 participating offensive scrimmage plays by mastery. Form changes strength only. Needs pre-choice field creation and seeded geometry snapshot; existing actor movement must aggregate max-speed modifiers."}]},{"id":"WIN-01-C","familyId":"gustling","mode":"clash","name":"Feather Relay","category":"Reserve rotation support","activation":"Gustling family; Support. Once per Clash, while living/able in RESERVE, at own team normal action opportunity if current active ally below50% HP and legal rotation available. This SUPPORT ACTION replaces team attack; not another simultaneous active fighter.","mechanic":"Once reserve support sacrifices team attack to rotate and heal departing active ally","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Gustling family; Support. Once per Clash, while living/able in RESERVE, at own team normal action opportunity if current active ally below50% HP and legal rotation available. This SUPPORT ACTION replaces team attack; not another simultaneous active fighter."},{"section":"Targets / placement","rule":"Current injured active ally rotates with FIRST living reserve in stable lineup order. Gustling may become incoming if it is that reserve. Respect rotation locks and legal availability."},{"section":"Core resolution","rule":"Rotate, then heal DEPARTING ally8 /10 /12% of that ally maximum HP by Gustling /Squallow /Stratosoar form. Incoming receives NO normal attack that team turn. Healing Reduced/maxHP cap normal; no shield, cleanse or revive."},{"section":"Recharge / frequency","rule":"One successful legal rotation commits use even if heal prevented. Failed/blocked rotation preserves. Source Stunned prevents and preserves. No resetting on rotation/revival."},{"section":"Lifetime / persistence","rule":"Immediate rotation/heal only, no status or schedule. Team action consumed once, not a bonus reserve normal turn; normal supported status carry remains."},{"section":"Exceptions / counterplay","rule":"Cannot bypass active ally Stunned skipped turn: only replace a normal action it could legally perform. No arbitrary reserve recharge clock. KO cannot be revived and cannot be chosen as recipient."},{"section":"Visuals","rule":"Soft feather ring escorts departing fighter into reserve; green heal number, normal entry visuals on incoming. No new badge."},{"section":"Progression / notes","rule":"Heal8 /10 /12% by form, same at all mastery tiers. Once-per-Clash replaces old6/5/4/3 owner-turn cooldown. Owner selected11A. Requires reserve-origin support action, one team-action cost, rotation-first heal and incoming-action suppression. No transition to multi-active combat. Runtime ordering and balance still require tests."}]},{"id":"WIN-02-F","familyId":"breezefang","mode":"football","name":"Slipstream Step","category":"Special action","activation":"Zephyroo / Mistralope; common Wind RB. Each personal broken tackle earns1 charge; threshold3 /2 by form. When full, next participating rushing play activates on first crossing beyond LOS while carrying ball and able. No activation on qualifying charge-filling play.","mechanic":"Broken-tackle charge displaces everyone but runner opposite run vector on later rush","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Zephyroo / Mistralope; common Wind RB. Each personal broken tackle earns1 charge; threshold3 /2 by form. When full, next participating rushing play activates on first crossing beyond LOS while carrying ball and able. No activation on qualifying charge-filling play."},{"section":"Targets / placement","rule":"ALL other on-field monsters on BOTH teams, including other Wind monsters; source RB alone excluded. One simultaneous snapshot of positions and current RB movement vector at activation. No radius limitation selected."},{"section":"Core resolution","rule":"One wind gust displaces targets1 /1.5 /2 /2.5 yards by mastery OPPOSITE RB movement direction, including diagonal. Stop safely at bodies, obstacles and field bounds, without domino pushing. No extra stun, stumble, tackle break or football duplication."},{"section":"Recharge / frequency","rule":"Bar empties on activation, no additional cooldown; activation play cannot recharge. Each broken tackle counts once, bar caps at full with no overflow. Unable source preserves readiness; failed LOS crossing preserves full bar."},{"section":"Lifetime / persistence","rule":"Partial/full charge carries possessions, halftime and overtime until actual game end. One impulse only, no persistent zone or seconds duration; save/reload preserves charge/use."},{"section":"Exceptions / counterplay","rule":"Other Wind monsters are intentionally eligible: this is an ability, not Wind terrain. Source must be able and ball carrier. Do not apply generic shared-status gate to physical displacement. Ordinary explicit movement-immunity/collision rules need implementation tests."},{"section":"Visuals","rule":"Charge bar alternates with status badge. At LOS crossing, visible gust drives affected monsters opposite runner heading; runner/ball remain readable. No new status badge."},{"section":"Progression / notes","rule":"Push1 /1.5 /2 /2.5 yards by mastery; broken-tackle threshold3 Zephyroo /2 Mistralope fixed by form. No old evasion-chance bonus. Requires broken-tackle event provenance, later-play armed flag, simultaneous collision-safe displacement and correct football stats. Snapshot heading; if velocity zero use last nonzero route/runner heading then offensive forward direction as deterministic technical fallback. Design closed by all13 A choices; runtime/balance pending."}]},{"id":"WIN-02-C","familyId":"breezefang","mode":"clash","name":"Gust Hop","category":"Signature action","activation":"Zephyroo; common; RB; Clash archetype Balanced → Balanced. Every third performed normal attack, replacing that attack with a two-hit leap.","mechanic":"Every third performed attack becomes two independently evadable same-target hits","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Zephyroo; common; RB; Clash archetype Balanced → Balanced. Every third performed normal attack, replacing that attack with a two-hit leap."},{"section":"Targets / placement","rule":"Current intended enemy active target; lock target at launch."},{"section":"Core resolution","rule":"Two separately evadable hits, EACH60 /65 /70 /75% normal damage by mastery. Same target locked at launch; no retarget if first KO. Each hit normal shield/DR; one performed attack, no ordinary-only archetype perks on special hits."},{"section":"Recharge / frequency","rule":"Three performed attacks to recharge; Stunned skips and support actions do not build count; no time cooldown."},{"section":"Lifetime / persistence","rule":"Partial count carries reserve rotation within same Clash, clears actual Clash end; same-game status carry unchanged."},{"section":"Exceptions / counterplay","rule":"Confused rolls once at launch for whole move; no second target or free attack after KO. Standard retaliation after each connected hit subject to no-recursion rule."},{"section":"Visuals","rule":"Two low wind hops with separate readable impact flashes."},{"section":"Progression / notes","rule":"Per-hit power 60 / 65 / 70 / 75% by mastery; both forms same power. Needs multi-hit pipeline with per-hit shield/rebuild and single normal-action accounting."}]},{"id":"WIN-03-F","familyId":"skywarden","mode":"football","name":"Air Brake","category":"Targeted effect","activation":"Aeralis; uncommon Wind CB.3 personal pass breakups fill bar; interceptions excluded. On later successful forward-pass catch by assigned/tracked receiver, activate if Aeralis within8 yards and able. No activation on charge-filling play.","mechanic":"PBU charge displaces guarded catcher opposite heading with actual yardage loss","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Aeralis; uncommon Wind CB.3 personal pass breakups fill bar; interceptions excluded. On later successful forward-pass catch by assigned/tracked receiver, activate if Aeralis within8 yards and able. No activation on charge-filling play."},{"section":"Targets / placement","rule":"One actual guarded receiver: man assignment or currently tracked zone receiver at catch. Range measured source-to-receiver at completed catch. Wind receivers eligible; no environmental immunity."},{"section":"Core resolution","rule":"Frontal wind displaces receiver5 /6.5 /8 /10 yards by mastery OPPOSITE receiver movement vector, including lateral crossing route. Ball moves with carrier. Stop safely at bodies, obstacles and field bounds; no pull, automatic tackle, status or stripped ball."},{"section":"Recharge / frequency","rule":"Consume full bar when legal activation occurs; no extra cooldown; activation play cannot recharge. If source disabled, range invalid or target not assigned, preserve bar for later legal catch."},{"section":"Lifetime / persistence","rule":"Partial/full charge survives possessions/halftime/OT and saves; actual game end clears. One catch-triggered impulse; no continuing field or unselected seconds timer."},{"section":"Exceptions / counterplay","rule":"Can genuinely lose football yardage; later normal stop at new location sets spot. Never undo completed touchdown or dead-ball finalized event. No automatic PBU or second catch roll. Carrier can keep running afterward."},{"section":"Visuals","rule":"Deflection charge bar; visible gust from ahead of receiver drives it backward relative to heading. No Stumbled badge, because this is physical movement rather than status."},{"section":"Progression / notes","rule":"Push5 /6.5 /8 /10 yards by mastery. Charge threshold3 PBUs, range8 yards fixed. Replaces rejected40% current-speed-loss proposal. Audit catch-before-score eligibility, vector fallback, collision and forward-progress ledger; do not award negative catch distance twice. Design values approved all-A; implementation must reconcile normal stop/scoring rules explicitly."}]},{"id":"WIN-03-C","familyId":"skywarden","mode":"clash","name":"Downdraft","category":"Enemy lineup disruption","activation":"Aeralis; Disruptor. Ready own normal action replaces attack when enemy has active fighter plus living first reserve and legal forced exchange.","mechanic":"Normal action swaps enemy active with first reserve then attempts incoming Weakened","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Aeralis; Disruptor. Ready own normal action replaces attack when enemy has active fighter plus living first reserve and legal forced exchange."},{"section":"Targets / placement","rule":"Swap enemy ACTIVE fighter with FIRST living reserve in stable lineup order. There are NOT two simultaneously active enemies."},{"section":"Core resolution","rule":"After legal swap and normal entry effects, attempt Weakened15% on incoming active fighter for2 recipient normal turns. No damage; ordinary one-status gate."},{"section":"Recharge / frequency","rule":"Illegal swap preserves use; legal swap spends even if status blocked. Source Stunned prevents. No extra reserve action or invented fallback stun."},{"section":"Lifetime / persistence","rule":"App turn excluded; reserve pauses cooldown/status. Football status carry converts to15% Strength reduction for remaining plays, normal episode count."},{"section":"Exceptions / counterplay","rule":"Respect existing rotation locks/immunity. Incoming Shielded entry can block Weakened. Normal rotation/action-order rules apply; no second same-team attack."},{"section":"Visuals","rule":"Downward wind spiral exchanges active/reserve pedestals; normal entry effects then cracked-fist badge if accepted."},{"section":"Progression / notes","rule":"Cooldown6 /5 /4 /3 source owner normal turns by mastery; status15% and2-turn duration fixed. Owner selected12A. Active/reserve action order and entry-status timing need target-branch tests; design does not change Clash format."}]},{"id":"WIN-04-F","familyId":"windlynx","mode":"football","name":"Crosswind Rescue","category":"Zone","activation":"Galyx; uncommon Wind Safety.2 personal pass breakups charge bar; one credit per breakup event. Next eligible defensive scrimmage pre-play creates lanes while source able, before BOTH play selections.","mechanic":"PBU charge creates paired stationary sideline Wind lanes at next eligible defensive snap","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Galyx; uncommon Wind Safety.2 personal pass breakups charge bar; one credit per breakup event. Next eligible defensive scrimmage pre-play creates lanes while source able, before BOTH play selections."},{"section":"Targets / placement","rule":"TWO stationary sideline rectangles: EACH4 yards WIDE sideline direction ×7 yards LONG endzone direction. Left/right outer edges meet playable sidelines; longitudinal band upcoming LOS+5 throughLOS+12. Normal field-boundary clipping; locked after reveal."},{"section":"Core resolution","rule":"Non-Wind monsters on BOTH teams gain20% maximum movement speed inside either lane. Acceleration unchanged. Wind monsters neither benefit nor suffer. Environmental modifier, not status."},{"section":"Recharge / frequency","rule":"Bar empties when pair creates; no extra cooldown; creation play cannot recharge. If own previous lanes remain, hold full bar until they expire. At most1 own created pair,1 full bar, no overflow."},{"section":"Lifetime / persistence","rule":"Partial/full charge survives possession/half/OT; created nonlegendary lanes clear halftime. Incompletions still count field lifetime. Stationary after creation; no pre-choice reroll/audible reposition."},{"section":"Exceptions / counterplay","rule":"Source Stunned / Knocked Down prevents creation and preserves bar. Offensive receivers can exploit lanes too. No automatic pursuit win or speed to source Wind family."},{"section":"Visuals","rule":"Two pale teal bordered gust lanes along sidelines; readable ball, yard marks and routes. Charge/status display alternates."},{"section":"Progression / notes","rule":"Lifetime1 /2 /2 /3 completed defensive scrimmage plays by mastery INCLUDING creation play. Charge2 PBUs, geometry and20% strength fixed. Requires PBU charge, source availability, field-pair lifetime, snap geometry/reveal and halftime cleanup. Design closed; bounds, replay and balance testing remain."}]},{"id":"WIN-04-C","familyId":"windlynx","mode":"clash","name":"Second Wind","category":"Reserve priority support","activation":"Galyx; Support. Once per Clash FROM RESERVE before normal round initiative resolves, if living active ally would act second and has an action it can legally perform.","mechanic":"Once reserve support moves active ally existing second action before enemy","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Galyx; Support. Once per Clash FROM RESERVE before normal round initiative resolves, if living active ally would act second and has an action it can legally perform."},{"section":"Targets / placement","rule":"Current living ACTIVE ally only. Source must remain living/able in reserve at trigger; do not look for another active teammate."},{"section":"Core resolution","rule":"Advance ally EXISTING normal action before opponent in this round. NO extra action, heal, damage boost or Stunned bypass; source itself does not take a normal attack."},{"section":"Recharge / frequency","rule":"Spend only when order actually changes. If ally already acts first, is Stunned, or source unable, preserve. No rotation/revival refresh."},{"section":"Lifetime / persistence","rule":"Priority change applies current round only. If target becomes KO/unable before action, normal cancellation applies without bonus replacement attack."},{"section":"Exceptions / counterplay","rule":"Does not interrupt already-resolving actions or remove Stunned. Resolve simultaneous priority with ordinary stable initiative/ties. No additional shared status."},{"section":"Visuals","rule":"Gust lifts active ally EXISTING action marker forward in visible turn order. No duplicated attack marker or extra head badge."},{"section":"Progression / notes","rule":"Once-per-Clash, no mastery numerical scaling selected. Replaces old6/5/4/3 cooldown and impossible multiple-active target condition. Owner selected13A. Reserve support priority hook must preserve one normal action/side and source once-use ledger; test Stunned and forced-replacement order."}]},{"id":"WIN-05-F","familyId":"zephyr","mode":"football","name":"Tailwind Huddle","category":"Aura","activation":"Zephiro; rare Wind QB. At offensive snap while ready/able choose one eligible allied NON-Wind blocker with legal blocking assignment and running cooldown, inside mastery radius4 /5 /6 /7 yards of initial QB alignment.","mechanic":"Snap-local QB aura grants one extra ally blocker cooldown unit at whistle","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Zephiro; rare Wind QB. At offensive snap while ready/able choose one eligible allied NON-Wind blocker with legal blocking assignment and running cooldown, inside mastery radius4 /5 /6 /7 yards of initial QB alignment."},{"section":"Targets / placement","rule":"Nearest eligible blocker in mastery radius4 /5 /6 /7 yards, stable lineup ties. Snapshot candidate at snap, never switch later."},{"section":"Core resolution","rule":"At whistle, after ordinary participating-play cooldown decrement, remove1 extra play from chosen blocker's still-running eligible cooldown. Radius eligibility is the SNAP snapshot at mastery4 /5 /6 /7 yards, not fixed4 and not continuous following. Never charge/once-use refill or replay missed trigger."},{"section":"Recharge / frequency","rule":"Zephiro own cooldown 4 subsequent offensive plays, application play excluded; only spent if bonus actually removes a unit."},{"section":"Lifetime / persistence","rule":"Per-play candidate lock, no later target switching. No effect on once-game/possession uses or status clocks."},{"section":"Exceptions / counterplay","rule":"Stunned / Knocked Down at snap prevents. Cannot accelerate self, constructs or an already-ready ability."},{"section":"Visuals","rule":"Low pale wind ring around QB; chosen blocker recharge bar pulses once at whistle."},{"section":"Progression / notes","rule":"Aura radius 4 / 5 / 6 / 7 yards by mastery. One bonus cooldown unit fixed. Need separate ordinary cooldown decrement and extra decrement to avoid same-play activation or negative counts."}]},{"id":"WIN-05-C","familyId":"zephyr","mode":"clash","name":"Tailwind Pact","category":"Signature action","activation":"Zephiro; rare; QB; Clash archetype Support → Support. Once per Clash on own normal action when at least two living allies have empty slots; replaces attack.","mechanic":"Once normal action attempts gated team Empowered without healing or override","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Zephiro; rare; QB; Clash archetype Support → Support. Once per Clash on own normal action when at least two living allies have empty slots; replaces attack."},{"section":"Targets / placement","rule":"All living allies including reserves and self with empty slots; no replacement or cleanse."},{"section":"Core resolution","rule":"Attempt Empowered +15 /18 /21 /24% by mastery for2 recipient normal turns on all living allies/self/reserves with empty slots. No heal/extra attack/overwrite. Football converts same percentage to Strength for remaining plays."},{"section":"Recharge / frequency","rule":"Once per Clash, committed on cast even if some allies blocked."},{"section":"Lifetime / persistence","rule":"App turn excluded; reserve pauses. Football conversion is same-percent Strength for remaining plays; no immediate field trigger."},{"section":"Exceptions / counterplay","rule":"Existing other statuses block. Equal same-status extension follows normal cap; targeting requires two empty slots, not two extendable slots."},{"section":"Visuals","rule":"Team wind stream links eligible allies; one ordinary fist badge per accepted ally."},{"section":"Progression / notes","rule":"Empowered strength 15 / 18 / 21 / 24% by mastery. Requires multi-target shared-status application and defined cross-mode payload."}]},{"id":"WIN-06-F","familyId":"tempestra","mode":"football","name":"Cyclonic Release","category":"Special action","activation":"Tempestra; legendary Wind WR.3 successful receptions fill bar. NEXT eligible reception while charged and able creates ONE stationary tornado at catch location. Activation reception cannot recharge.","mechanic":"Reception charge creates stationary three-distinct-defender Stumbled wind-blast emitter","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Tempestra; legendary Wind WR.3 successful receptions fill bar. NEXT eligible reception while charged and able creates ONE stationary tornado at catch location. Activation reception cannot recharge."},{"section":"Targets / placement","rule":"First3 DIFFERENT non-Wind defenders within5 yards: initial occupants qualify, then new entrants. Nearest first at selection; stable lineup ties. Offense and all Wind defenders unaffected. One shot per selected defender."},{"section":"Core resolution","rule":"Launch visible crescent wind blast at each selected defender. Once launched it reaches that target without extra accuracy roll, even after leaving radius; whistle cancels unfinished projectile. Each hit attempts Stumbled with40% current-speed loss ONCE; max speed unchanged, ordinary reacceleration and status gate."},{"section":"Recharge / frequency","rule":"Full bar consumed on tornado creation, no additional cooldown. No activation-play recharge. Blocked status still spends shot/target eligibility; no every-frame retry or repeated defender target."},{"section":"Lifetime / persistence","rule":"Emitter ends at3 blasts or whistle, whichever first. Stationary catch point, no movement obstruction, lingering zone or pull. Partial/full bar survives possessions/halftime/OT until actual game end; live objects clean at whistle."},{"section":"Exceptions / counterplay","rule":"Wind defenders/offense unaffected. No automatic Stunned, damage, tackle break or ball loss. Launched projectiles follow normal independent-effect resolution; source disable cannot retroactively undo launched shots. Technical event ordering and boundary tests remain."},{"section":"Visuals","rule":"Visible rotating tornado at catch point fires crescent wind blasts. Standard Stumbled badge on accepted status only; charge bar alternates with badge. No pulling animation."},{"section":"Progression / notes","rule":"Fixed3 catches,5-yard radius,3 distinct shots,40% current-speed loss at all4 mastery tiers; no new power progression selected. Owner approved original5 recommended choices and closeout9A targeting plus8A charge handling. Need stable target ledger, collision-free emitter/projectile presentation, whistle cancellation and saved charge. Design closed; game implementation/balance pending."}]},{"id":"WIN-06-C","familyId":"tempestra","mode":"clash","name":"Eye of the Storm","category":"Signature action","activation":"Tempestra; legendary; WR; Clash archetype Disruptor → Disruptor. Once per Clash own normal action replaces attack if enemy front active has a ready, repeatable signature.","mechanic":"Once normal action temporarily restricts enemy active to ordinary attacks without cooldown extension","designStatus":"Approved design; implementation required","details":[{"section":"Trigger / eligibility","rule":"Tempestra; legendary; WR; Clash archetype Disruptor → Disruptor. Once per Clash own normal action replaces attack if enemy front active has a ready, repeatable signature."},{"section":"Targets / placement","rule":"Current enemy front active, lock monster identity."},{"section":"Core resolution","rule":"For next 2 recipient normal turns it must use ordinary attack instead of a ready signature. Existing charges/cooldowns continue normally; no forced rotation prevention."},{"section":"Recharge / frequency","rule":"Once per Clash; normal shared status is not applied."},{"section":"Lifetime / persistence","rule":"Countdown follows target; reserve pauses. Ends actual Clash end, not transferred to football."},{"section":"Exceptions / counterplay","rule":"Cannot suppress passives, entry effects, reactions, launched effects or once-Clash legendary casts. Source Stunned prevents. Ordinary attacks remain usable."},{"section":"Visuals","rule":"A clear eye within dark wind around target ability panel; show restriction in inspect, no extra status badge."},{"section":"Progression / notes","rule":"2 recipient turns fixed; no mastery power growth. Need signature eligibility metadata and choice override BEFORE action commit; target does not spend forbidden ability."}]},{"id":"DAR-01-F","familyId":"shadowkit","mode":"football","name":"Shadow Patch","category":"Zone","activation":"Umbrikit; common; CB; After own pass breakup while ready, bank field for next defensive scrimmage pre-choice. Interceptions excluded.","mechanic":"DAR-01-F: Shadow Patch; Non-Dark on both teams -15 / -20% effective Awareness by Umbrikit / Obscurat while inside. Essential ball/controls truthful.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Umbrikit; common; CB; After own pass breakup while ready, bank field for next defensive scrimmage pre-choice. Interceptions excluded."},{"section":"Targets / placement","rule":"6-wide by 6-long Dark rectangle centered at upcoming LOS plus 5-yard LB reference, lateral at breakup location projected into new snap."},{"section":"Core resolution","rule":"Non-Dark on both teams -15 / -20% effective Awareness by Umbrikit / Obscurat while inside. Essential ball/controls truthful."},{"section":"Recharge / frequency","rule":"Cooldown 5 defensive plays fixed after creation; cannot bank during cooldown."},{"section":"Lifetime / persistence","rule":"Pending carries halves/possessions; created field clears halftime; no reanchor after creation."},{"section":"Exceptions / counterplay","rule":"No Confused status or auto-route error; ordinary Awareness formulas operate. Dark monsters receive no effect."},{"section":"Visuals","rule":"Low translucent violet shadow with clear edge; ball and routes remain readable."},{"section":"Progression / notes","rule":"Lifetime 1 / 1 / 2 / 2 defensive scrimmage plays including spawn. Requires Dark modifier consumers in reads/reactions with stored stats unchanged."}]},{"id":"DAR-01-C","familyId":"shadowkit","mode":"clash","name":"Shadow Pounce","category":"Clash ability","activation":"First enemy normal-action attack, including an enhanced normal attack, whose entire attack misses the active, able source triggers a counter after the whole attack. Counters and reactions never qualify.","mechanic":"DAR-01-C: Shadow Pounce; Counter at 70 / 80% normal damage by Umbrikit / Obscurat, standard evasion/type/shields; not ordinary attack for archetype perks.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"First enemy normal-action attack, including an enhanced normal attack, whose entire attack misses the active, able source triggers a counter after the whole attack. Counters and reactions never qualify."},{"section":"Targets / placement","rule":"Same attacker if still active and alive; no target replacement."},{"section":"Core resolution","rule":"Counter at 70 / 80% normal damage by Umbrikit / Obscurat, standard evasion/type/shields; not ordinary attack for archetype perks."},{"section":"Recharge / frequency","rule":"One counter per Clash, committed at eligible miss. While the counter is unused, each enemy normal attack against the active, able Umbrikit / Obscurat has an explicit 15% / 20% chance to miss entirely (one roll for the whole attack); explicitly undodgeable attacks bypass it without a roll. The dodge ends once the counter is used. No universal evasion is implied.","ruling":"N7b P10","supersededRule":"One counter per Clash, committed at eligible miss; no passive guaranteed dodge is granted."},{"section":"Lifetime / persistence","rule":"If unable at reaction point, preserve use; no queue. No carry from actual Clash to another Clash."},{"section":"Exceptions / counterplay","rule":"Multi-hit move qualifies only if EVERY hit misses; shield absorption is not miss. No reaction to counters or own Confused self-hit."},{"section":"Visuals","rule":"Shadow crouches then lunges back along attack trail."},{"section":"Progression / notes","rule":"Counter power +0 / +5 / +10 / +15 percentage points by mastery. Needs completed-attack all-miss event, counter recursion guard and one-use state."}],"ruling":"N7b P10","values":{"dodgePctByStage":[15,20]}},{"id":"DAR-02-F","familyId":"nightowl","mode":"football","name":"Night Watch","category":"Aura","activation":"Noctlet; common; S; While active safety is able, allies within 4-yard moving radius benefit on defensive scrimmage plays.","mechanic":"DAR-02-F: Night Watch; Ignore only Awareness reductions from Dark ENVIRONMENTAL field. No bonus outside field, no status cleanse or protection from Confused.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Noctlet; common; S; While active safety is able, allies within 4-yard moving radius benefit on defensive scrimmage plays."},{"section":"Targets / placement","rule":"Moving radius 4 / 5 / 6 / 7 yards by mastery. Real allied non-Dark defenders inside ignore only the Dark base-field Awareness penalty. No redundant self bonus; Noctlet and Strixen already have same-type field neutrality."},{"section":"Core resolution","rule":"Ignore only Awareness reductions from Dark ENVIRONMENTAL field. No bonus outside field, no status cleanse or protection from Confused."},{"section":"Recharge / frequency","rule":"Passive aura; no cooldown or charges."},{"section":"Lifetime / persistence","rule":"Only while in radius and source able. Leaves no lasting status and no cross-mode payload."},{"section":"Exceptions / counterplay","rule":"Stunned / Knocked Down source disables. Does not nullify Eclipse denial or other hybrid effects. Dark allies already immune gain nothing."},{"section":"Visuals","rule":"Low owl-eye ring, allies inspect shows Dark-awareness protection; no head badge."},{"section":"Progression / notes","rule":"Aura radius 4 / 5 / 6 / 7 yards by mastery. Protection has no additional stat bonus. Need modifier provenance to filter base Dark Awareness term only."}]},{"id":"DAR-02-C","familyId":"nightowl","mode":"clash","name":"Night Swoop","category":"Clash ability","activation":"Noctlet; common; S; Clash archetype Balanced → Striker. First performed normal attack of each Clash.","mechanic":"DAR-02-C: Night Swoop; Resolve this first normal attack before opponents scheduled in same round at 110 / 120% normal damage by Noctlet / Strixen. It is still evadable and can be Stunned before action scheduling.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Noctlet; common; S; Clash archetype Balanced → Striker. First performed normal attack of each Clash."},{"section":"Targets / placement","rule":"Current enemy active target; no reserve hit."},{"section":"Core resolution","rule":"Resolve this first normal attack before opponents scheduled in same round at 110 / 120% normal damage by Noctlet / Strixen. It is still evadable and can be Stunned before action scheduling."},{"section":"Recharge / frequency","rule":"Spent on performed attack even if miss; support action or Stunned skip preserves first-attack opportunity."},{"section":"Lifetime / persistence","rule":"First eligible attack priority applies once; no reset on rotation/revival."},{"section":"Exceptions / counterplay","rule":"Does not interrupt already-resolving action or beat an explicit higher-priority interrupt. Ordinary damage mitigation and Confused apply."},{"section":"Visuals","rule":"Owl silhouette arcs overhead then strikes before turn marker settles."},{"section":"Progression / notes","rule":"Power +0 / +5 / +10 / +15 percentage points by mastery; one use. Need stable priority tier: interrupts first, then priority attacks in ordinary initiative/tie order."}]},{"id":"DAR-03-F","familyId":"duskrunner","mode":"football","name":"Vanishing Cut","category":"Self enhancement","activation":"Duskyre; uncommon; RB; On own rushing play, first successful ordinary juke after gaining mastery-required net rushing yards while ready.","mechanic":"DAR-03-F: Vanishing Cut; Become non-targetable for that defender NEXT tackle attempt on this play only: defender cannot initiate it but can pursue/block routes; all other defenders normal. No global invisibility or full stop.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Duskyre; uncommon; RB; On own rushing play, first successful ordinary juke after gaining mastery-required net rushing yards while ready."},{"section":"Targets / placement","rule":"Self and the one juked defender."},{"section":"Core resolution","rule":"Become non-targetable for that defender NEXT tackle attempt on this play only: defender cannot initiate it but can pursue/block routes; all other defenders normal. No global invisibility or full stop."},{"section":"Recharge / frequency","rule":"Cooldown 5 subsequent offensive plays fixed; spent at successful juke."},{"section":"Lifetime / persistence","rule":"Opportunity expires whistle; no status slot, no literal visual disappearance of football."},{"section":"Exceptions / counterplay","rule":"If defender never tries again, no refund. No bypass of existing tackle, body collisions, sideline or end-zone rules. Source disable prevents."},{"section":"Visuals","rule":"A dark afterimage peels away; actual runner/ball keep bright readable outline."},{"section":"Progression / notes","rule":"Required rush gain5 / 4 / 3 / 2 yards by mastery; no other stat changes. Needs per-opponent tackle-attempt exclusion token and preserved targeting for everyone else."}]},{"id":"DAR-03-C","familyId":"duskrunner","mode":"clash","name":"Predator Rhythm","category":"Clash ability","activation":"Duskyre; uncommon; RB; Clash archetype Striker → Striker. After two consecutive performed normal attacks damage the SAME enemy monster HP, next own normal attack on that monster is empowered.","mechanic":"DAR-03-C: Predator Rhythm; Third strike deals140 / 150 / 160 / 170% normal damage by mastery. Miss, shield-only hit, change of target or target departure resets sequence; no bonus dodge.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Duskyre; uncommon; RB; Clash archetype Striker → Striker. After two consecutive performed normal attacks damage the SAME enemy monster HP, next own normal attack on that monster is empowered."},{"section":"Targets / placement","rule":"Previously damaged monster only while still enemy active."},{"section":"Core resolution","rule":"Third strike deals140 / 150 / 160 / 170% normal damage by mastery. Miss, shield-only hit, change of target or target departure resets sequence; no bonus dodge."},{"section":"Recharge / frequency","rule":"Sequence cycles to zero after enhanced attempt; no turns timer."},{"section":"Lifetime / persistence","rule":"Partial sequence pauses in own reserve; enemy departure destroys target-specific sequence."},{"section":"Exceptions / counterplay","rule":"No free follow-up, healing or execute. Confused redirected hit does not advance valid enemy sequence."},{"section":"Visuals","rule":"Three claw slashes fill on ability marker; final slash becomes long shadow."},{"section":"Progression / notes","rule":"Third-strike damage140 / 150 / 160 / 170% by mastery. Same-target streak rules fixed. Need target-ID sequence ledger and HP-damage provenance, single normal action."}]},{"id":"DAR-04-F","familyId":"mireclaw","mode":"football","name":"Ambush Tag","category":"Targeted effect","activation":"Three own participating defensive scrimmage plays allowing at most 4 net yards fill the bar, maximum one credit per play. Incompletions and losses qualify. Touchdowns, special teams and two-point plays do not.","mechanic":"DAR-04-F: Ambush Tag; At snap launch shadow claw attempting Weakened Strength reduction15 / 20 / 25 / 30% by mastery for CURRENT play on selected RB. No damage, movement pull or tackle guarantee.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Three own participating defensive scrimmage plays allowing at most 4 net yards fill the bar, maximum one credit per play. Incompletions and losses qualify. Touchdowns, special teams and two-point plays do not."},{"section":"Targets / placement","rule":"Next participating defensive pre-choice selects opposing RB by stable lineup. If no RB, hold full charge."},{"section":"Core resolution","rule":"At snap launch shadow claw attempting Weakened Strength reduction15 / 20 / 25 / 30% by mastery for CURRENT play on selected RB. No damage, movement pull or tackle guarantee."},{"section":"Recharge / frequency","rule":"Charge threshold 3 fixed, empties on launch even blocked. Activation play cannot recharge."},{"section":"Lifetime / persistence","rule":"Partial/full bar carries halves and possessions. Application ends whistle; no seconds duration."},{"section":"Exceptions / counterplay","rule":"Only if target participates, source able. Selection visible both sides; offense can pass. No QB-target fallback."},{"section":"Visuals","rule":"Three scratch marks fill bar; snap shadow claw grips target silhouette briefly then standard fist badge."},{"section":"Progression / notes","rule":"Strength reduction 15 / 20 / 25 / 30% by mastery. Needs team-gain charge rules and per-play target snapshot / shared status attempt."}]},{"id":"DAR-04-C","familyId":"mireclaw","mode":"clash","name":"Ambush","category":"Clash ability","activation":"Murklaw; uncommon; LB; Clash archetype Striker → Striker. First ACTIVE entry per Clash including opening lineup arms one bonus on next performed normal attack.","mechanic":"DAR-04-C: Ambush; Attack at130 / 145 / 160 / 175% normal damage by mastery if HP still at least75% max; otherwise ordinary attack preserves armed state until eligible or Clash end.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Murklaw; uncommon; LB; Clash archetype Striker → Striker. First ACTIVE entry per Clash including opening lineup arms one bonus on next performed normal attack."},{"section":"Targets / placement","rule":"Current enemy active at that action, no entry damage."},{"section":"Core resolution","rule":"Attack at130 / 145 / 160 / 175% normal damage by mastery if HP still at least75% max; otherwise ordinary attack preserves armed state until eligible or Clash end."},{"section":"Recharge / frequency","rule":"One empowered attempt per Clash; once fired spent even evaded. Rotation/revival does not reset."},{"section":"Lifetime / persistence","rule":"Armed entry state pauses in reserve. No healing or shield automatically granted."},{"section":"Exceptions / counterplay","rule":"Opponent can chip source below threshold. Boost is special attack, no ordinary-only archetype stacking. Normal evasion / defense."},{"section":"Visuals","rule":"A crouched shadow marker remains on ability panel; attack emerges in one large claw."},{"section":"Progression / notes","rule":"Power 130 / 145 / 160 / 175% by mastery. Need first-entry ledger and high-HP evaluation at action commit."}]},{"id":"DAR-05-F","familyId":"nocturne","mode":"football","name":"Blackout Pocket","category":"Zone","activation":"Nocturne; rare; QB; After own completed pass gains at least 15 net yards while ready, bank next offensive field.","mechanic":"DAR-05-F: Blackout Pocket; Both teams non-Dark -25% effective Awareness. Covers front pressure reads but also own blockers, no concealed essential UI.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Nocturne; rare; QB; After own completed pass gains at least 15 net yards while ready, bank next offensive field."},{"section":"Targets / placement","rule":"Next offensive pre-choice: 12-wide by 5-long Dark rectangle from LOS into defensive side, centered upcoming QB initial lateral alignment."},{"section":"Core resolution","rule":"Both teams non-Dark -25% effective Awareness. Covers front pressure reads but also own blockers, no concealed essential UI."},{"section":"Recharge / frequency","rule":"Cooldown 6 subsequent offensive plays after creation; one pending."},{"section":"Lifetime / persistence","rule":"Pending carries half; created nonlegendary clears half. No growth from YAC or full-field coverage."},{"section":"Exceptions / counterplay","rule":"No auto-completion, guaranteed escape or field-following. Formation/audible does not reposition after reveal."},{"section":"Visuals","rule":"QB spreads wings; dark rectangular canopy settles over front of pocket while player sprites stay legible."},{"section":"Progression / notes","rule":"Lifetime 1 / 2 / 2 / 3 offensive scrimmage plays including spawn. Nocturne approved WR-to-QB move needs later permanent stat profile; new next-snap offensive producer."}]},{"id":"DAR-05-C","familyId":"nocturne","mode":"clash","name":"Eclipse Call","category":"Clash ability","activation":"From reserve, an able Nocturne automatically attempts Eclipse Call at the first eligible start-of-round opportunity. Normal entry effects resolve before eligibility. Stunned source waits and preserves the use.","mechanic":"DAR-05-C: Eclipse Call; Application chance 60 / 70 / 80 / 90% by mastery. Confused has its approved separate 25% normal-attack self-side redirect chance. No damage or extra attack.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"From reserve, an able Nocturne automatically attempts Eclipse Call at the first eligible start-of-round opportunity. Normal entry effects resolve before eligibility. Stunned source waits and preserves the use."},{"section":"Targets / placement","rule":"Target the opposing single active fighter if its shared slot is empty, or it has Confused and can accept another application under the three-application cap. Otherwise wait."},{"section":"Core resolution","rule":"Application chance 60 / 70 / 80 / 90% by mastery. Confused has its approved separate 25% normal-attack self-side redirect chance. No damage or extra attack."},{"section":"Recharge / frequency","rule":"Once per Clash. An actual application roll consumes the use even when it fails. No eligible target or disabled source preserves the use. No cost to the allied active fighter normal action."},{"section":"Lifetime / persistence","rule":"Confused lasts 2 recipient normal turns. Same-status extension follows shared duration and three-application rules. Cross-mode conversion uses the existing Confused football Awareness penalty, not a new status."},{"section":"Exceptions / counterplay","rule":"No overwrite of another status. Incoming Shielded can prevent eligibility. Reserve activation gives no free normal attack and does not reset on rotation or revival."},{"section":"Visuals","rule":"A black crescent travels from the reserve source to the active opponent; show the standard Confused badge after successful application."},{"section":"Progression / notes","rule":"Application chance 60 / 70 / 80 / 90%; fixed duration 2 recipient normal turns at every mastery. Implement post-entry, pre-initiative round hook with one active fighter per side; maintain once-use and application provenance. Implementation and balance testing remain required."}]},{"id":"DAR-06-F","familyId":"nyxshade","mode":"football","name":"Shadow Exchange","category":"Special action","activation":"Two personal pass breakups fill the bar; interceptions do not. On a later eligible forward pass release, evaluate Shadow Exchange using the intended receiver projected catch point.","mechanic":"DAR-06-F: Shadow Exchange; Simultaneously swap actual positions of Nyxshade and the chosen defender. Each retains its own assignment, speed and movement heading. Football and receiver never move through this ability. Ordinary catch/interception resolution follows.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Two personal pass breakups fill the bar; interceptions do not. On a later eligible forward pass release, evaluate Shadow Exchange using the intended receiver projected catch point."},{"section":"Targets / placement","rule":"Real allied defender within 3 yards of that catch point, closer to it than Nyxshade, and at most 8 / 10 / 12 / 14 yards from Nyxshade by mastery. Choose closest to catch point; stable lineup ordering breaks ties. Both must be able, not block/tackle-engaged, with legal in-bounds endpoints."},{"section":"Core resolution","rule":"Simultaneously swap actual positions of Nyxshade and the chosen defender. Each retains its own assignment, speed and movement heading. Football and receiver never move through this ability. Ordinary catch/interception resolution follows."},{"section":"Recharge / frequency","rule":"Spend the full bar only on a successful legal swap. No additional cooldown. Invalid opportunities preserve it. The activation play cannot earn charge."},{"section":"Lifetime / persistence","rule":"Partial and full charge carry across possessions and halftime. Swap is immediate at pass release; no lingering zone or status."},{"section":"Exceptions / counterplay","rule":"No clones, extra actors, guaranteed breakup or interception, virtual catch contest, or teleportation of the receiver/ball. Stun/Knockdown and engagement invalidate participation."},{"section":"Visuals","rule":"Both defenders dissolve into shadow and emerge at exchanged positions, with readable football and essential markers."},{"section":"Progression / notes","rule":"Maximum caster-to-teammate swap distance 8 / 10 / 12 / 14 yards. Partner catch-point radius fixed 3 yards. Two personal PBUs per activation. Implement atomic position exchange, pass-release projected catch-point selection and legal endpoint checks. Preserve current 7v7 model. Design approved; implementation and balance verification remain."}]},{"id":"DAR-06-C","familyId":"nyxshade","mode":"clash","name":"Eclipse Theft","category":"Clash ability","activation":"Nyxshade spends its own normal action, once per Clash, to steal an eligible opposing active fighter benefit, provided Nyxshade shared status slot is empty.","mechanic":"DAR-06-C: Eclipse Theft; Guaranteed atomic transfer on legal eligibility. Remove benefit from foe only when accepted by Nyxshade. Preserve strength, remaining duration, remaining shield HP and accepted application count out of three. No damage or extra attack.","designStatus":"Approved","details":[{"section":"Trigger / eligibility","rule":"Nyxshade spends its own normal action, once per Clash, to steal an eligible opposing active fighter benefit, provided Nyxshade shared status slot is empty."},{"section":"Targets / placement","rule":"Opposing single active fighter only. Eligible benefits: Shielded, Guarded, Empowered, Quickened. No eligible target or occupied own slot falls back to an ordinary attack and preserves the use."},{"section":"Core resolution","rule":"Guaranteed atomic transfer on legal eligibility. Remove benefit from foe only when accepted by Nyxshade. Preserve strength, remaining duration, remaining shield HP and accepted application count out of three. No damage or extra attack."},{"section":"Recharge / frequency","rule":"Use commits only on successful transfer. Stunned source cannot activate. Rotation and revival do not reset the once-use."},{"section":"Lifetime / persistence","rule":"Preserve the existing status episode and remaining clock with shared turn/application provenance; no extra tick or hidden duration refresh from transfer. Normal existing cross-mode status conversion applies."},{"section":"Exceptions / counterplay","rule":"Transfer the basic status only. Shardok shield rebuild and Aegistron Guarded repair are not stolen. No source ability uses, riders or flags transfer. Transfer is not shield depletion."},{"section":"Visuals","rule":"A shadow serpent carries the benefit badge from the enemy to Nyxshade; enemy badge disappears and the same basic status appears over Nyxshade."},{"section":"Progression / notes","rule":"Once per Clash at every mastery. No numerical refill, duration refresh, application-cap reset or additional damage. Implement atomic status-owner transfer with episode provenance, shield pool and application history, excluding source-only riders. Preserve one active fighter per side and one shared status slot."}]},{"id":"LIG-01-F","familyId":"glimmer","mode":"football","name":"Beacon Lane","category":"Zone","activation":"Lumini; common; WR; After own reception that gains a first down while ready, bank next offensive field.","mechanic":"Non-Light finishing a participating scrimmage play inside Light gets one extra cooldown unit after ordinary decrement on shortest-running positive repeatable signature cooldown. One benefit per monster per play. No charge-bar or once-use restoration. Same-type neutrality and bench pause apply.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Lumini; common; WR; After own reception that gains a first down while ready, bank next offensive field."},{"section":"Targets / placement","rule":"8-wide by 6-long Light rectangle at upcoming fixed 5-yard LB reference, centered on initial ball lateral position."},{"section":"Core resolution","rule":"Non-Light finishing a participating scrimmage play inside Light gets one extra cooldown unit after ordinary decrement on shortest-running positive repeatable signature cooldown. One benefit per monster per play. No charge-bar or once-use restoration. Same-type neutrality and bench pause apply."},{"section":"Recharge / frequency","rule":"Creator cooldown 6 / 5 / 4 / 3 offensive plays; starts creation and cannot receive its own field recharge."},{"section":"Lifetime / persistence","rule":"Created field lasts 1 / 1 / 2 / 2 participating offensive scrimmage plays by mastery, counting its creation play, for both forms. Created field clears at halftime. Pending creation carries through halftime under its approved carryover rule.","ruling":"N7b P3, P4","supersededRule":"Pending carries halves; created common field clears half. Spawn play counts."},{"section":"Exceptions / counterplay","rule":"Receiver can help enemy recharge. Light family immune gains no acceleration. Ordinary status timers untouched."},{"section":"Visuals","rule":"Golden low rectangle with small clock particles along perimeter."},{"section":"Progression / notes","rule":"Approved Light field exposure cadence finalized in closeout10. Lifetime by mastery as above; placement and creator cooldown as approved.","ruling":"N7b P3, P4","supersededRule":"Approved Light field exposure cadence finalized in closeout10. Keep existing creator lifetime/placement/mastery."}],"ruling":"N7b P3, P4","values":{"lifetimePlaysByMastery":[1,1,2,2]}},{"id":"LIG-01-C","familyId":"glimmer","mode":"clash","name":"Glow Mend","category":"Signature action","activation":"Lumini; common; WR; Clash archetype Support → Support. Ready own normal action replaces attack if at least two living allies are injured.","mechanic":"Glow Mend: Heal each 7 / 10% own max HP by Lumini / Photara. No surplus shield, cleanse or HP equalization.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Lumini; common; WR; Clash archetype Support → Support. Ready own normal action replaces attack if at least two living allies are injured."},{"section":"Targets / placement","rule":"Two lowest HP-percentage living allies including reserves/self, stable tie order."},{"section":"Core resolution","rule":"Heal each 7 / 10% own max HP by Lumini / Photara. No surplus shield, cleanse or HP equalization."},{"section":"Recharge / frequency","rule":"If fewer than two injured, ordinary attack preserves. Cast spent even if Healing Reduced blocks all healing."},{"section":"Lifetime / persistence","rule":"Immediate HP restoration; no recurring status or duration."},{"section":"Exceptions / counterplay","rule":"Normal maxHP cap/Healing Reduced; no revive. Cannot heal same ally twice when only one injured."},{"section":"Visuals","rule":"Two firefly lights split from source into selected allies; ordinary green numbers."},{"section":"Progression / notes","rule":"Cooldown 6 / 5 / 4 / 3 owner turns. Needs two distinct recipient selection before resolving heals; no retarget after first heal."}]},{"id":"LIG-02-F","familyId":"sunwhistle","mode":"football","name":"Dawn Signal","category":"Targeted effect","activation":"Solchirp; common; K; After successful extra point ONLY, bank support for own next kickoff. Field goals excluded.","mechanic":"Dawn Signal: Attempt Quickened +15 / +20% Speed by Solchirp / Heliark for that kickoff play only; increases max speed AND acceleration. Does not affect kick distance or returner.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Solchirp; common; K; After successful extra point ONLY, bank support for own next kickoff. Field goals excluded."},{"section":"Targets / placement","rule":"One nearest eligible non-K teammate on kickoff coverage at snap, stable lineup tie."},{"section":"Core resolution","rule":"Attempt Quickened +15 / +20% Speed by Solchirp / Heliark for that kickoff play only; increases max speed AND acceleration. Does not affect kick distance or returner."},{"section":"Recharge / frequency","rule":"No extra cooldown; max one pending, consumed on eligible kickoff cast even status blocked."},{"section":"Lifetime / persistence","rule":"Pending persists halftime if kickoff delayed. Buff clears whistle; kickoff is one play. No eligible target retains token until next own kickoff."},{"section":"Exceptions / counterplay","rule":"No guaranteed tackle/touchback; existing different status blocks; Stunned source at cast delays pending."},{"section":"Visuals","rule":"Song notes fly to coverage teammate; green boot badge if accepted."},{"section":"Progression / notes","rule":"Quickened strength +0 / +3 / +6 / +9 percentage points by mastery. Kickoffs are live plays using existing movement, blocking and tackling, so the Quickened coverage teammate's speed and acceleration take real effect; actual participants and return events are credited. Punts, field goals and extra points keep their approved scope.","ruling":"N7b P7","supersededRule":"Quickened strength +0 / +3 / +6 / +9 percentage points by mastery. Special teams may lack controllable coverage actors; needs real coverage simulation, not decorative stat bonus. Flag implementation prerequisite."}],"ruling":"N7b P7"},{"id":"LIG-02-C","familyId":"sunwhistle","mode":"clash","name":"Dawn Song","category":"Signature action","activation":"Solchirp; common; K; Clash archetype Support → Support. Ready own normal action replaces attack if active front ally is injured and has empty status slot.","mechanic":"Dawn Song: Heal5 / 6 / 7 / 8% maxHP by mastery immediately, then same amount at end of NEXT2 owner normal turns. This is ability-linked healing schedule, not new status; empty status slot gates initial cast only.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Solchirp; common; K; Clash archetype Support → Support. Ready own normal action replaces attack if active front ally is injured and has empty status slot."},{"section":"Targets / placement","rule":"Front ally, self only if actually front."},{"section":"Core resolution","rule":"Heal5 / 6 / 7 / 8% maxHP by mastery immediately, then same amount at end of NEXT2 owner normal turns. This is ability-linked healing schedule, not new status; empty status slot gates initial cast only."},{"section":"Recharge / frequency","rule":"Cooldown 6 owner turns fixed, cast turn excluded. Cannot stack own schedules on same target; eligible only if no Dawn Song schedule there."},{"section":"Lifetime / persistence","rule":"Reserve pauses future pulses; KO/actual Clash end cancels. Healing Reduced evaluated separately at each pulse."},{"section":"Exceptions / counterplay","rule":"Different later status does not erase schedule. No cross-mode healing: discard pending pulses on football transition. No cleanse/revive."},{"section":"Visuals","rule":"Small sunrise arc on target base ring, three light notes fade with pulses; no extra head badge."},{"section":"Progression / notes","rule":"Retain separately saved healing schedule outside shared status slot, with approved empty-slot requirement at cast. Heal immediately and at next2 owner-turn endpoints. Pause in reserve, clear knockout/football/actual Clash end. Keep approved5/6/7/8% healing by mastery."}]},{"id":"LIG-03-F","familyId":"lumen","mode":"football","name":"Guiding Halo","category":"Aura","activation":"Lumen; uncommon; QB; While QB able on offensive scrimmage play, first allied reception within6 yards of current QB position while ready.","mechanic":"Guiding Halo: Attempt Shielded with one football fumble save for2 subsequent participating plays. Does not improve catch or tackle resistance; normal one-status gate.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Lumen; uncommon; QB; While QB able on offensive scrimmage play, first allied reception within6 yards of current QB position while ready."},{"section":"Targets / placement","rule":"That allied receiver only, no QB self target, construct or interceptor."},{"section":"Core resolution","rule":"Attempt Shielded with one football fumble save for2 subsequent participating plays. Does not improve catch or tackle resistance; normal one-status gate."},{"section":"Recharge / frequency","rule":"Cooldown5 subsequent participating offensive plays; spent on application attempt even blocked. App play excluded."},{"section":"Lifetime / persistence","rule":"Shield carries halves/possessions and turns1:1. Clash conversion pool15% recipient maxHP; no refill equal stacking, no restored depleted pool under G09."},{"section":"Exceptions / counterplay","rule":"QB Stunned/Knocked Down prevents. Receiver must catch within radius; later leaving does not remove accepted status. Once-fumble-save consumes whole episode."},{"section":"Visuals","rule":"Thin gold halo connects QB to short-catch receiver, then standard Shielded badge appears."},{"section":"Progression / notes","rule":"Aura radius6 / 8 / 10 / 12 yards by mastery. Shield duration2 fixed. Needs post-catch aura-distance hook and shared cross-mode Shielded payload. No bonus on already-failed catch."}]},{"id":"LIG-03-C","familyId":"lumen","mode":"clash","name":"Clear Light","category":"Signature action","activation":"Lumen; uncommon; QB; Clash archetype Support → Support. Ready own normal action replaces attack when another living ally has removable harmful status.","mechanic":"Cleanse the selected removable harmful status first, then heal 8 / 10 / 12 / 14% maximum HP by mastery. Recharge is five owner normal turns. Preserve the approved target, status gate, once-use and exception rules.","supersededMechanic":"Clear Light: Remove harmful status first, then heal 10% maxHP. If status cannot be removed, no cast; no generic heal fallback.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Lumen; uncommon; QB; Clash archetype Support → Support. Ready own normal action replaces attack when another living ally has removable harmful status."},{"section":"Targets / placement","rule":"Lowest HP-percentage eligible ally including reserves, never self."},{"section":"Core resolution","rule":"Cleanse the selected removable harmful status first, then heal 8 / 10 / 12 / 14% maximum HP by mastery. Recharge is five owner normal turns. Preserve the approved target, status gate, once-use and exception rules.","ruling":"N9d","supersededRule":"Remove harmful status first, then heal 10% maxHP. If status cannot be removed, no cast; no generic heal fallback."},{"section":"Recharge / frequency","rule":"Stunned source prevents; successful cleanse spends, even if healing capped."},{"section":"Lifetime / persistence","rule":"Immediate removal/heal; statuses do not remain dormant. No revive."},{"section":"Exceptions / counterplay","rule":"Uncleansable Healing Reduced cannot be selected. Cleanse before heal removes ordinary Healing Reduced so restoration can work."},{"section":"Visuals","rule":"Clear prism flashes over existing harmful badge, badge breaks then green heal number."},{"section":"Progression / notes","rule":"Heal 8 / 10 / 12 / 14% by mastery; cooldown 5 turns fixed. Requires removable-status eligibility, atomic cleanse-before-heal and reserve target access."}],"ruling":"N9d"},{"id":"LIG-04-F","familyId":"prism","mode":"football","name":"Prism Break","category":"Special action","activation":"Personal tackles and pass breakups grant one charge per participating play, maximum one total per play. Three charges arm Prism Break for the next eligible defensive pre-choice opportunity. Activation play cannot recharge.","mechanic":"Prism Break: Remove one selected base zone entirely. For a selected hybrid overlap, remove the hybrid and contributing parent effects within that overlap footprint only; no underlying parent effect returns there. Remaining parent portions stay intact.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Personal tackles and pass breakups grant one charge per participating play, maximum one total per play. Three charges arm Prism Break for the next eligible defensive pre-choice opportunity. Activation play cannot recharge."},{"section":"Targets / placement","rule":"N9d: at the pre-choice boundary, with the source in the initial displayed defensive personnel, select the nearest existing enemy zone by exposed-footprint nearest edge, measured from the fixed point 12 yards beyond the upcoming LOS at ball lateral. Preserve creation-order ties and exact base/overlap removal. Pending fields and fields created at that same snap cannot be removed; no target keeps the bar. Save once per snap.","ruling":"N9d","supersededRule":"Choose nearest existing enemy-created environmental zone anywhere on field, distance to nearest edge, creation order breaks ties. Base, legendary-created and overlap zones eligible. No target preserves full bar."},{"section":"Core resolution","rule":"Remove one selected base zone entirely. For a selected hybrid overlap, remove the hybrid and contributing parent effects within that overlap footprint only; no underlying parent effect returns there. Remaining parent portions stay intact."},{"section":"Recharge / frequency","rule":"Spend all three charges only on legal removal; repeatable after three more qualifying plays. Maximum one full bar. No extra cooldown or once-possession limit."},{"section":"Lifetime / persistence","rule":"Partial/full charge survives possessions, halftime and overtime, clears at game end. Removal persists for the removed area; future newly created zones resolve normally."},{"section":"Exceptions / counterplay","rule":"Cannot remove physical obstacles, walls, clones, auras or statuses. Unable source preserves readiness. Do not reconstitute removed parent footprints when the overlap is recomputed."},{"section":"Visuals","rule":"Floating prism fires rainbow beam; selected field fractures into fading light before play choices."},{"section":"Progression / notes","rule":"Three charges at every mastery. No additional stat modifier or arbitrary timer. No invented mastery scaling. Implement zone provenance, polygon/rectangle subtraction, overlap selection and deterministic ties. No production code changed. Geometry and shared overlap details require implementation tests."}],"ruling":"N9d"},{"id":"LIG-04-C","familyId":"prism","mode":"clash","name":"Refraction","category":"Signature action","activation":"Prismara; uncommon; S; Clash archetype Disruptor → Disruptor. Every third performed normal attack becomes refracted.","mechanic":"Primary100% normal attack, then secondary30/40/50/60% by mastery against first living reserve only if primary connects. Independent secondary evasion. Normal shields/type/reduction, shared single Confused redirect to own side target set. No ordinary-only archetype bonus.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Prismara; uncommon; S; Clash archetype Disruptor → Disruptor. Every third performed normal attack becomes refracted."},{"section":"Targets / placement","rule":"Primary current active enemy and secondary first living enemy reserve, target IDs captured on launch. No secondary without living reserve. No replacement retarget after primary KO."},{"section":"Core resolution","rule":"Primary100% normal attack, then secondary30/40/50/60% by mastery against first living reserve only if primary connects. Independent secondary evasion. Normal shields/type/reduction, shared single Confused redirect to own side target set. No ordinary-only archetype bonus."},{"section":"Recharge / frequency","rule":"Three performed attacks; count pauses reserve, no charge on Stunned skip."},{"section":"Lifetime / persistence","rule":"One action; target set captured at launch, no replacement retarget after primary KO."},{"section":"Exceptions / counterplay","rule":"Shields can absorb each independently. Confused redirects entire target set to own side with self primary. No ordinary-only archetype boosts on special hits."},{"section":"Visuals","rule":"Prism beam splits only after first impact into a thinner side ray."},{"section":"Progression / notes","rule":"Secondary30/40/50/60%, primary100%. Owner closeout1 resolves obsolete second-active target to first living reserve. Single-active Clash model retained."}]},{"id":"LIG-05-F","familyId":"halofang","mode":"football","name":"Radiant Pursuit","category":"Self enhancement","activation":"Haloryx; rare; LB; After mastery-required personal successful tackles on rushing plays (3 / 3 / 2 / 2), arm next participating defensive snap. Assists qualify once per play.","mechanic":"Radiant Pursuit: Ignore ordinary allied-body path obstruction while chasing ball carrier; enemy blockers still collide normally. Ends BEFORE tackle contest, no pass-through enemy or automatic win.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Haloryx; rare; LB; After mastery-required personal successful tackles on rushing plays (3 / 3 / 2 / 2), arm next participating defensive snap. Assists qualify once per play."},{"section":"Targets / placement","rule":"Self until it makes first tackle attempt on current ball carrier."},{"section":"Core resolution","rule":"Ignore ordinary allied-body path obstruction while chasing ball carrier; enemy blockers still collide normally. Ends BEFORE tackle contest, no pass-through enemy or automatic win."},{"section":"Recharge / frequency","rule":"Charge empties at snap; activation play cannot recharge. No additional cooldown."},{"section":"Lifetime / persistence","rule":"Ability state expires whistle even no tackle. Partial/full charge carries halves/possessions."},{"section":"Exceptions / counterplay","rule":"No teleport or increased stats. Stunned/Knocked Down prevents snap activation and preserves bar. Cannot ghost physical walls, environmental vines or enemy bodies."},{"section":"Visuals","rule":"Radiant trail links source to runner; allied intersections shimmer without hiding source."},{"section":"Progression / notes","rule":"Required tackles 3 / 3 / 2 / 2 by mastery. Need collision filtering by team and stable pursuit mode; do not disable tackle geometry."}]},{"id":"LIG-05-C","familyId":"halofang","mode":"clash","name":"Radiant Pursuit","category":"Signature action","activation":"Haloryx; rare; LB; Clash archetype Striker → Striker. Own normal attack when enemy target HP is below 35% at action commit.","mechanic":"Radiant Pursuit: Deal115 / 125 / 135 / 145% normal damage by mastery, no auto-KO, healing or extra hit.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Haloryx; rare; LB; Clash archetype Striker → Striker. Own normal attack when enemy target HP is below 35% at action commit."},{"section":"Targets / placement","rule":"Intended active enemy; not a reserve, no target switch."},{"section":"Core resolution","rule":"Deal115 / 125 / 135 / 145% normal damage by mastery, no auto-KO, healing or extra hit."},{"section":"Recharge / frequency","rule":"Passive conditional attack; no cooldown or charge."},{"section":"Lifetime / persistence","rule":"Eligibility evaluated before hit; if target heals afterward use ordinary current event order. No persistent buff."},{"section":"Exceptions / counterplay","rule":"Normal evasion/shield/Guarded/Tank apply. Does not bypass Last Root or guaranteed survival."},{"section":"Visuals","rule":"Halo narrows into spearhead only when target visibly below threshold."},{"section":"Progression / notes","rule":"Multiplier 115 / 125 / 135 / 145% by mastery, threshold35 fixed. Conditional multiplier metadata; retain normal-attack identity for ordinary archetype perks only where global perk policy permits (G06)."}]},{"id":"LIG-06-F","familyId":"aurelion","mode":"football","name":"Daybreak","category":"Special action","activation":"Every opposing touchdown, including offense, defense and returns, adds one charge even with Aurelion off field. Two charges arm the ability. On its next eligible live successful reception, flare after catch resolution.","mechanic":"Daybreak: Guaranteed ability-specific Daybreak flash disrupts football assignments, targeting, deliberate pursuit, blocking and tackle initiation. Affected monsters wander independently with random direction changes at movement checkpoints. This is not a status effect or zone; an occupied status slot cannot block it.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Every opposing touchdown, including offense, defense and returns, adds one charge even with Aurelion off field. Two charges arm the ability. On its next eligible live successful reception, flare after catch resolution."},{"section":"Targets / placement","rule":"Every other monster on field from both teams, including Light types and allies. Aurelion alone is exempt. A touchdown scored by the catch itself preserves readiness."},{"section":"Core resolution","rule":"Guaranteed ability-specific Daybreak flash disrupts football assignments, targeting, deliberate pursuit, blocking and tackle initiation. Affected monsters wander independently with random direction changes at movement checkpoints. This is not a status effect or zone; an occupied status slot cannot block it."},{"section":"Recharge / frequency","rule":"Spend both charges when flare activates, then recharge after two more opposing touchdowns. No once-game limit. An unable source preserves readiness."},{"section":"Lifetime / persistence","rule":"Wandering persists until whistle, even after fumble or possession change during the play. Restore ordinary behavior at whistle. Charge persists across quarters, possessions, halftime and overtime; clears at actual game end."},{"section":"Exceptions / counterplay","rule":"Existing statuses remain unchanged and continue operating. Immobilized monsters remain immobilized until restrictions end. Wandering respects boundaries, bodies and obstacles; bodies can obstruct movement but no new deliberate or accidental tackle attempt occurs while blinded. No new shared status badge."},{"section":"Visuals","rule":"Sun charge icon half fills at one opposing touchdown, full at two. Golden flare on catch, then all others visibly wander while Aurelion runs. Keep ball and Aurelion readable; softened flash for reduced-flash setting."},{"section":"Progression / notes","rule":"Two opposing touchdowns per activation at every mastery. Blindness lasts the remainder of current play. No seconds timer and no unapproved mastery scaling. Implement independent saved per-play behavior override, deterministic wandering, TD charge ledger and no-tackle gate without occupying status slot. Test fumbles, collision deadlocks, immobilization recovery, replay/save and whistle cleanup. Legendary strength requires balance testing."}]},{"id":"LIG-06-C","familyId":"aurelion","mode":"clash","name":"Daybreak Lance","category":"Signature action","activation":"Aurelion; legendary; WR; Clash archetype Striker → Striker. Once per Clash on own ready normal action; replaces attack.","mechanic":"Deal 145 / 160 / 175 / 190% normal damage by mastery. Standard evasion, shield and damage reduction apply. Suppress only attack retaliation caused by this strike; passive damage auras and attached status responses remain. This replaces the normal attack and receives no ordinary-attack archetype perk.","supersededMechanic":"Daybreak Lance: 160% normal damage, standard evasion/shield/DR. Suppress only ATTACK retaliation caused by this strike; passive damage auras and attached status responses still resolve. No skipped enemy normal turn.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Aurelion; legendary; WR; Clash archetype Striker → Striker. Once per Clash on own ready normal action; replaces attack."},{"section":"Targets / placement","rule":"Current enemy active target."},{"section":"Core resolution","rule":"Deal 145 / 160 / 175 / 190% normal damage by mastery. Standard evasion, shield and damage reduction apply. Suppress only attack retaliation caused by this strike; passive damage auras and attached status responses remain. This replaces the normal attack and receives no ordinary-attack archetype perk.","ruling":"N9d","supersededRule":"160% normal damage, standard evasion/shield/DR. Suppress only ATTACK retaliation caused by this strike; passive damage auras and attached status responses still resolve. No skipped enemy normal turn."},{"section":"Recharge / frequency","rule":"Once per Clash, spent on launch even miss. Stunned preserves."},{"section":"Lifetime / persistence","rule":"No persistent modifier or cross-mode payload."},{"section":"Exceptions / counterplay","rule":"Does not silence enemy next action, bypass shield, dodge or resistance. Confused can redirect whole strike; then retaliation suppression still part of attack."},{"section":"Visuals","rule":"Sun phoenix dives as long golden lance; opposing retaliation icon briefly crossed during resolution."},{"section":"Progression / notes","rule":"Damage 145 / 160 / 175 / 190% by mastery. Attack context needs suppress-retaliation flag without suppressing all afterHit effects."}],"ruling":"N9d"},{"id":"MET-01-F","familyId":"ironcub","mode":"football","name":"Anchor Plate","category":"Self enhancement","activation":"Ferrcub; common; OL; At first own block engagement each offensive play while ready, if defender begins ordinary push attempt.","mechanic":"Anchor Plate: Ignore first 1 yard of net backward displacement that play, then ordinary strength-based pushing resumes. No extra Blocking, shed immunity, guaranteed pancake or root to permanent spot.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferrcub; common; OL; At first own block engagement each offensive play while ready, if defender begins ordinary push attempt."},{"section":"Targets / placement","rule":"Self versus that engaged defender only."},{"section":"Core resolution","rule":"Ignore first 1 yard of net backward displacement that play, then ordinary strength-based pushing resumes. No extra Blocking, shed immunity, guaranteed pancake or root to permanent spot."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 offensive plays; spent when positive displacement is actually absorbed."},{"section":"Lifetime / persistence","rule":"Single per-play budget; cannot refill on reengagement. Unspent readiness persists, temporary allowance clears whistle."},{"section":"Exceptions / counterplay","rule":"Does not prevent Landslide guaranteed legendary displacement (G05 hierarchy). Stunned/Knocked Down disables blocking normally."},{"section":"Visuals","rule":"Steel paw plate drops under feet; progress tick beside ability panel records absorbed push."},{"section":"Progression / notes","rule":"Displacement allowance 0.5 / 0.75 / 1 / 1.25 yards by mastery. Need ordinary-vs-ability displacement tags and accumulated prevented-yard budget."}]},{"id":"MET-01-C","familyId":"ironcub","mode":"clash","name":"Forge Swipe","category":"Signature action","activation":"Ferrcub; common; OL; Clash archetype Balanced → Balanced. Every third performed normal attack attempts self Empowered AFTER full attack resolves if alive.","mechanic":"After every third performed normal attack, attempt Empowered +10 / +15% outgoing damage by Ferrcub / Forgursa for 1 / 2 / 2 / 3 owner normal turns by mastery. Triggering attack gains no immediate bonus. The ordinary single-status gate and equal/stronger application rules apply; reset the count even if blocked.","supersededMechanic":"Forge Swipe: Attempt Empowered +10 / +15% outgoing damage by Ferrcub / Forgursa for 2 owner normal turns. Repeated equal application extends duration, never adds strength. No instant bonus on triggering attack.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferrcub; common; OL; Clash archetype Balanced → Balanced. Every third performed normal attack attempts self Empowered AFTER full attack resolves if alive."},{"section":"Targets / placement","rule":"Self only; normal one-status gate."},{"section":"Core resolution","rule":"After every third performed normal attack, attempt Empowered +10 / +15% outgoing damage by Ferrcub / Forgursa for 1 / 2 / 2 / 3 owner normal turns by mastery. Triggering attack gains no immediate bonus. The ordinary single-status gate and equal/stronger application rules apply; reset the count even if blocked.","ruling":"N9d","supersededRule":"Attempt Empowered +10 / +15% outgoing damage by Ferrcub / Forgursa for 2 owner normal turns. Repeated equal application extends duration, never adds strength. No instant bonus on triggering attack."},{"section":"Recharge / frequency","rule":"Three performed normal attacks per attempt; blocked status still resets count."},{"section":"Lifetime / persistence","rule":"App turn excluded. Football carry same-percent Strength for remaining plays; no permanent rating change."},{"section":"Exceptions / counterplay","rule":"Weaker/stronger/cap rules normal. No +5% unlimited stacking or shield bypass."},{"section":"Visuals","rule":"Forge sparks harden forepaws; ordinary Empowered fist badge."},{"section":"Progression / notes","rule":"Duration 1 / 2 / 2 / 3 turns by mastery. Need performed-attack ledger and post-action status application with application-turn exclusion."}],"ruling":"N9d"},{"id":"MET-02-F","familyId":"steelpaw","mode":"football","name":"Iron Lungs","category":"Aura","activation":"Steelpaw; common; LB; While linebacker able, allied defenders within 3 yards at snap qualify this play.","mechanic":"Iron Lungs: Every SECOND qualifying participating play for each protected ally reduces that play's ordinary stamina drain by1 point, minimum0. Count per protected monster, not per source, and do not stack copies. Ability drain unchanged; no stamina restoration.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Steelpaw; common; LB; While linebacker able, allied defenders within 3 yards at snap qualify this play."},{"section":"Targets / placement","rule":"Self and nearest ONE living allied defender in radius; no constructs, tie lineup order."},{"section":"Core resolution","rule":"Every SECOND qualifying participating play for each protected ally reduces that play's ordinary stamina drain by1 point, minimum0. Count per protected monster, not per source, and do not stack copies. Ability drain unchanged; no stamina restoration."},{"section":"Recharge / frequency","rule":"Passive, once calculation per participating defensive play."},{"section":"Lifetime / persistence","rule":"Protection eligibility sampled at snap. Each monster retains0/1 qualified-play progress across bench/halftime; nonqualifying plays pause it. At second eligible play consume counter even baseline drain0; actual game end clears. No effect on Exhausted."},{"section":"Exceptions / counterplay","rule":"Zero-fatigue rest-game penalty remains. Baseline1 therefore drains1 on first qualifying play,0 on second, then repeats; useful without granting total baseline immunity. G03 must be reviewed with shared provisional stamina tuning."},{"section":"Visuals","rule":"Metal breath plume at feet, saved-drain tick on stamina inspect; no head buff."},{"section":"Progression / notes","rule":"Aura radius 3 / 4 / 5 / 6 yards by mastery. Need stamina drain provenance and shared provisional-drain tuning; proposed Tank because Clash protection."}]},{"id":"MET-02-C","familyId":"steelpaw","mode":"clash","name":"Tempered Guard","category":"Signature action","activation":"Steelpaw; common; LB; Clash archetype Balanced → Tank. On own ready normal action when HP above50% and no status; replaces attack.","mechanic":"Tempered Guard: Attempt Guarded25 / 30 / 35 / 40% by mastery for next2 owner normal turns. While this OWN Guarded episode exists, enemy direct HP hit cannot exceed30% maxHP per individual hit. Cap is source payload, not another status.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Steelpaw; common; LB; Clash archetype Balanced → Tank. On own ready normal action when HP above50% and no status; replaces attack."},{"section":"Targets / placement","rule":"Self only."},{"section":"Core resolution","rule":"Attempt Guarded25 / 30 / 35 / 40% by mastery for next2 owner normal turns. While this OWN Guarded episode exists, enemy direct HP hit cannot exceed30% maxHP per individual hit. Cap is source payload, not another status."},{"section":"Recharge / frequency","rule":"Cooldown 6 owner turns, setup turn excluded; reserve pauses."},{"section":"Lifetime / persistence","rule":"Equal extension preserves payload without cap budget refill (per-hit cap has no pool); stronger OTHER-source Guarded replacement loses source cap."},{"section":"Exceptions / counterplay","rule":"Cannot set up below threshold or overwrite. DOT unaffected; multi-hit attacks each allowed30%, can KO. Football unsupported Guarded clears and cap ends."},{"section":"Visuals","rule":"Steel plates close over shoulders; ordinary Guarded breastplate badge."},{"section":"Progression / notes","rule":"Guarded reduction 25 / 30 / 35 / 40% by mastery; HP cap30 fixed. Need Guarded source payload owner and post-DR individual HP-loss clamp; not a separate passive stacking slot."}]},{"id":"MET-03-F","familyId":"gearwing","mode":"football","name":"Gear Grid","category":"Zone","activation":"Coglet; uncommon; K; After own punt of at least35 net yards that is not touchback, bank next opponent scrimmage Metal field.","mechanic":"Non-Metal first changed automatic target/assignment/engagement decision inside Metal per play adopts after one normal AI decision update. Preserve prior valid action until then, otherwise hold stance. Never delay player inputs, normal physics or an already-started route.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Coglet; uncommon; K; After own punt of at least35 net yards that is not touchback, bank next opponent scrimmage Metal field."},{"section":"Targets / placement","rule":"10-wide by 6-long at upcoming opponent LOS plus5 LB depth, centered ball lateral position."},{"section":"Core resolution","rule":"Non-Metal first changed automatic target/assignment/engagement decision inside Metal per play adopts after one normal AI decision update. Preserve prior valid action until then, otherwise hold stance. Never delay player inputs, normal physics or an already-started route."},{"section":"Recharge / frequency","rule":"No extra cooldown; one pending token and max one own field."},{"section":"Lifetime / persistence","rule":"Punt return completes BEFORE next snap geometry. Pending carries halftime; created nonlegendary field clears half."},{"section":"Exceptions / counterplay","rule":"No bounce/roll simulation assumed. Net yards measured final opponent spot; legal source kicker role retained."},{"section":"Visuals","rule":"Clockwork lines assemble a flat iron grid under LB band; slow gear-turn particles."},{"section":"Progression / notes","rule":"Life 1 / 2 / 2 / 3 defensive scrimmage plays including spawn. Needs punt final-spot/net-distance event, current return sim sufficient without bounce physics."}]},{"id":"MET-03-C","familyId":"gearwing","mode":"clash","name":"Gear Shot","category":"Signature action","activation":"Coglet; uncommon; K; Clash archetype Balanced → Balanced. Every performed normal attack.","mechanic":"Gear Shot: Clamp random base-damage variance floor to0.95 / 1.00 / 1.05 / 1.10 by mastery, never above configured upper variance. Evasion, type, shield, Guarded/Tank and critical system if any remain ordinary.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Coglet; uncommon; K; Clash archetype Balanced → Balanced. Every performed normal attack."},{"section":"Targets / placement","rule":"Current active target."},{"section":"Core resolution","rule":"Clamp random base-damage variance floor to0.95 / 1.00 / 1.05 / 1.10 by mastery, never above configured upper variance. Evasion, type, shield, Guarded/Tank and critical system if any remain ordinary."},{"section":"Recharge / frequency","rule":"Passive no cooldown; no extra attack or status."},{"section":"Lifetime / persistence","rule":"No buildup or persistent buff. Variance evaluated per own normal attack, not reactions/special type move."},{"section":"Exceptions / counterplay","rule":"Does not guarantee hit, minimum HP damage or favorable type. Confused redirect still uses clamped variance."},{"section":"Visuals","rule":"Gears align before shot; stable damage number with small gear accent, no badge."},{"section":"Progression / notes","rule":"Floor 0.95 / 1.00 / 1.05 / 1.10 by mastery (supersedes 1.00 example); never exceeds configured upper variance. Need damage-variance stage exposed and clamp before type/DR; preserve seeded RNG consumption even when clamped."}]},{"id":"MET-04-F","familyId":"ironjaw","mode":"football","name":"Ball Clamp","category":"Targeted effect","activation":"Ferronox; uncommon; DL; After own sack while ready, earn token for next tackle attempt against a ball carrier.","mechanic":"Ball Clamp: On successful normal tackle, if first fumble check did not fumble perform ONE additional ordinary forced-fumble check at mastery factor0.25 / 0.40 / 0.55 / 0.70 of normal probability. Shielded can prevent actual fumble normally. No guaranteed turnover or second tackle.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferronox; uncommon; DL; After own sack while ready, earn token for next tackle attempt against a ball carrier."},{"section":"Targets / placement","rule":"Actual tackled ball carrier, including QB sack; no returner unless explicit owner approval of special teams, default scrimmage only."},{"section":"Core resolution","rule":"On successful normal tackle, if first fumble check did not fumble perform ONE additional ordinary forced-fumble check at mastery factor0.25 / 0.40 / 0.55 / 0.70 of normal probability. Shielded can prevent actual fumble normally. No guaranteed turnover or second tackle."},{"section":"Recharge / frequency","rule":"One banked token, consumed on successful tackle eligible for extra roll; failed tackle preserves. Cannot earn and spend on same play."},{"section":"Lifetime / persistence","rule":"Token carries halftime and possessions until used; max1; only defensive scrimmage."},{"section":"Exceptions / counterplay","rule":"Tackle ending in safety/endzone/whistle follows normal fumble legality; no retroactive turnover after finalized score."},{"section":"Visuals","rule":"Iron jaws briefly snap around ball at tackle point; no body biting/damage or new status."},{"section":"Progression / notes","rule":"Extra check factor 0.25 / 0.40 / 0.55 / 0.70 of normal fumble chance by mastery. Needs fumble probability reuse without double stats/ball spawning; resolve before dead-ball finalization."}]},{"id":"MET-04-C","familyId":"ironjaw","mode":"clash","name":"Iron Bite","category":"Signature action","activation":"Ferronox; uncommon; DL; Clash archetype Striker → Striker. Ready own normal action replaces attack if enemy active has Shielded with positive pool.","mechanic":"120% normal damage, shield multiplier1.5/1.75/2/2.25, HP overflow retains ordinary budget under approved closeout13.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferronox; uncommon; DL; Clash archetype Striker → Striker. Ready own normal action replaces attack if enemy active has Shielded with positive pool."},{"section":"Targets / placement","rule":"That active Shielded enemy; one target."},{"section":"Core resolution","rule":"120% normal damage. Shield multiplier1.5/1.75/2/2.25 by mastery. Compute ordinary mitigated attack budget D and shield multiplier M. Remove min(S,D*M) shieldHP. If shield S is broken, remaining HP budget=max(0,D-S/M), otherwise zero. Do not amplify HP overflow. Example D100,M2,S100 gives100 shield damage and50 HP budget."},{"section":"Recharge / frequency","rule":"Cooldown 5 owner turns fixed, spent launch even evaded."},{"section":"Lifetime / persistence","rule":"No status strip; depleted shield ends normally. No lingering wound."},{"section":"Exceptions / counterplay","rule":"If no shield ordinary attack preserve. Phase Strike bypasses pool, this consumes it; normal type/DR apply before shield-specific multiplier."},{"section":"Visuals","rule":"Metal bite strikes shield surface, fragments match actual pool loss."},{"section":"Progression / notes","rule":"Shield multiplier 1.5 / 1.75 / 2 / 2.25 by mastery. Need separate shield and HP budgets; document exact overflow formula G08 to avoid amplified HP damage."}]},{"id":"MET-05-F","familyId":"metalhorn","mode":"football","name":"Bulwark Grid","category":"Zone","activation":"Ferrhorn; rare; TE; While ready, after own successful receiving first down OR own successful pancake on blocking play, earn one next offensive field.","mechanic":"Non-Metal first changed automatic target/assignment/engagement decision inside Metal per play adopts after one normal AI decision update. Preserve prior valid action until then, otherwise hold stance. Never delay player inputs, normal physics or an already-started route.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferrhorn; rare; TE; While ready, after own successful receiving first down OR own successful pancake on blocking play, earn one next offensive field."},{"section":"Targets / placement","rule":"8-wide by4-long Metal rectangle from upcoming LOS into offense backfield, centered initial QB lateral alignment."},{"section":"Core resolution","rule":"Non-Metal first changed automatic target/assignment/engagement decision inside Metal per play adopts after one normal AI decision update. Preserve prior valid action until then, otherwise hold stance. Never delay player inputs, normal physics or an already-started route."},{"section":"Recharge / frequency","rule":"Cooldown 6 / 5 / 4 / 3 offensive plays after creation. Max one pending."},{"section":"Lifetime / persistence","rule":"Pending carries halftime; created rare field clears half. No activation on failed catch or ordinary block hold."},{"section":"Exceptions / counterplay","rule":"Metal TE unaffected; own non-Metal QB/blockers risk delayed reactions. Does not delay player input or forced pass."},{"section":"Visuals","rule":"Four iron corner posts paint floor grid without physical obstruction."},{"section":"Progression / notes","rule":"Life 1 / 1 / 2 / 2 offensive scrimmage plays including spawn. Approved OL-to-TE reassignment requires permanent profile authoring later; reaction modifier needs snap-decision classification."}]},{"id":"MET-05-C","familyId":"metalhorn","mode":"clash","name":"Shield Wall","category":"Signature action","activation":"Ferrhorn; rare; TE; Clash archetype Support → Support. Ready own normal action replaces attack when a living RESERVE ally has empty status slot.","mechanic":"Shield Wall: Attempt Shielded12 / 15 / 18 / 21% target maxHP by mastery for3 recipient normal turns. No healing, cleanse or active target option.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Ferrhorn; rare; TE; Clash archetype Support → Support. Ready own normal action replaces attack when a living RESERVE ally has empty status slot."},{"section":"Targets / placement","rule":"Reserve ally with lowest current HP percentage, stable lineup tie."},{"section":"Core resolution","rule":"Attempt Shielded12 / 15 / 18 / 21% target maxHP by mastery for3 recipient normal turns. No healing, cleanse or active target option."},{"section":"Recharge / frequency","rule":"Cooldown5 owner turns; app turn excluded."},{"section":"Lifetime / persistence","rule":"Reserve pauses status; on football transition one fumble save for remaining plays. Return to Clash cannot refill previously depleted pool (G09)."},{"section":"Exceptions / counterplay","rule":"Existing other status blocks; at least one eligible target or ordinary attack preserve. Once cap rules apply, no refill equal strength."},{"section":"Visuals","rule":"Ferrhorn folds a steel panel into selected reserve pedestal; standard Shielded badge."},{"section":"Progression / notes","rule":"Shielded12/15/18/21% target maximum HP, three recipient turns. Preserve source pool, remaining fraction, episode application history and spent fumble-save state across mode changes. A football fumble save consumes whole episode. First football-created shield starts full fraction1, then source-defined Clash pool scales by saved fraction. Duration extension never refills. Legitimate stronger replacement follows existing stronger-status rule."}]},{"id":"MET-06-F","familyId":"aegistron","mode":"football","name":"Fortress Gate","category":"Special action","activation":"Aegistron; legendary; DL; Once per defensive possession, after 3 participating plays where opponent gains at most3 yards, next defensive snap auto-activates if able.","mechanic":"Fortress Gate: Panels stationary for current play, block BOTH teams movement, not football. Leave center lane/source position open. No push, damage, status or extra player.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Aegistron; legendary; DL; Once per defensive possession, after 3 participating plays where opponent gains at most3 yards, next defensive snap auto-activates if able."},{"section":"Targets / placement","rule":"Two physical gate panels beside initial DL position. Each panel width 1.5 / 2 / 2.5 / 3 yards by mastery; thickness 0.5 yard, clear side gap 1 yard. Safe placement only; the former illustrative fixed 2-yard width is superseded by mastery width."},{"section":"Core resolution","rule":"Panels stationary for current play, block BOTH teams movement, not football. Leave center lane/source position open. No push, damage, status or extra player."},{"section":"Recharge / frequency","rule":"One use per defensive possession; activation play cannot charge. Illegal placement preserves full bar and use."},{"section":"Lifetime / persistence","rule":"Panels disappear whistle; charge carries halftime/possessions but possession use resets only new opposing possession."},{"section":"Exceptions / counterplay","rule":"Cannot spawn inside body/endzone boundary; skip panel pair if either illegal. Opponent can run center or pass. Source continues normal DL role after cast visual."},{"section":"Visuals","rule":"Ancient machine plants two glowing steel gates with open gap; visible before snap movement."},{"section":"Progression / notes","rule":"Panel width 1.5 / 2 / 2.5 / 3 yards by mastery; thickness/gap fixed. Needs physical obstacle pipeline shared with Earth/Ice but paired safe-placement validation. DL reassignment needs permanent ratings later."}]},{"id":"MET-06-C","familyId":"aegistron","mode":"clash","name":"Fortress","category":"Signature action","activation":"Aegistron; legendary; DL; Clash archetype Tank → Tank. Once per Clash own normal action replaces attack if no status and HP below60%.","mechanic":"Attempt Guarded 50% for two owner normal turns. While that own episode is active, store HP damage it prevents, capped at 10 / 15 / 20 / 25% maximum HP by mastery. Heal the stored amount only on natural expiry. Removed/replaced episodes pay nothing; no shield pool or counterattack.","supersededMechanic":"Fortress: Attempt Guarded50% for2 owner normal turns; while own episode active, store prevented HP damage up to20% maxHP. At natural expiry heal stored amount, subject Healing Reduced. No healing if removed/replaced/KO.","designStatus":"Approved design; shared dependencies and implementation pending","details":[{"section":"Trigger / eligibility","rule":"Aegistron; legendary; DL; Clash archetype Tank → Tank. Once per Clash own normal action replaces attack if no status and HP below60%."},{"section":"Targets / placement","rule":"Self only."},{"section":"Core resolution","rule":"Attempt Guarded 50% for two owner normal turns. While that own episode is active, store HP damage it prevents, capped at 10 / 15 / 20 / 25% maximum HP by mastery. Heal the stored amount only on natural expiry. Removed/replaced episodes pay nothing; no shield pool or counterattack.","ruling":"N9d","supersededRule":"Attempt Guarded50% for2 owner normal turns; while own episode active, store prevented HP damage up to20% maxHP. At natural expiry heal stored amount, subject Healing Reduced. No healing if removed/replaced/KO."},{"section":"Recharge / frequency","rule":"Once per Clash on successful cast attempt; no reset rotation/revival."},{"section":"Lifetime / persistence","rule":"App turn excluded, reserve pauses; natural expiry only. Football unsupported clears without payout."},{"section":"Exceptions / counterplay","rule":"No Shielded pool, counterattack or fresh episode override. Existing other status blocks setup; ordinary attack preserve."},{"section":"Visuals","rule":"Fortress plates glow as prevention meter fills at base, then release small repair sparks on expiry."},{"section":"Progression / notes","rule":"Storage cap 10 / 15 / 20 / 25% maxHP by mastery; Guarded50 fixed. Need damage-prevention provenance, cap accumulator and natural-expiry reason distinct from cleanse/transition."}],"ruling":"N9d"},{"id":"PSY-01-F","familyId":"mindwing","mode":"football","name":"Mind Bend","category":"Zone","activation":"Personal tackle or assist after an opponent completed pass while ready banks a Psychic zone for the next eligible defensive pre-choice opportunity.","mechanic":"Mind Bend / Non-Psychic monsters of both teams inside receive inward movement vector at 20% of applicable maximum speed. Stop pull within 1 yard of center. Ordinary movement can overcome pull. Psychic monsters have same-type neutrality.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Personal tackle or assist after an opponent completed pass while ready banks a Psychic zone for the next eligible defensive pre-choice opportunity."},{"section":"Targets / placement","rule":"8 yards wide sideline-to-sideline and 6 yards long endzone-to-endzone. At upcoming snap place from LOS+3 to LOS+9 toward opponent goal, centered laterally on ball. Near endzone shift toward LOS only enough to fit in field of play."},{"section":"Core resolution","rule":"Non-Psychic monsters of both teams inside receive inward movement vector at 20% of applicable maximum speed. Stop pull within 1 yard of center. Ordinary movement can overcome pull. Psychic monsters have same-type neutrality."},{"section":"Recharge / frequency","rule":"Cooldown 6 / 5 / 4 / 3 subsequent participating defensive scrimmage plays by mastery, starts after creation. Cannot bank during cooldown. Unable source preserves pending readiness."},{"section":"Lifetime / persistence","rule":"Created zone life 1 / 1 / 2 / 2 defensive scrimmage plays by mastery including creation play and incompletions. Pending survives possessions and halftime. Created zone clears at halftime and remains stationary after creation."},{"section":"Exceptions / counterplay","rule":"No status application, automatic stun, player-targeted dragging or football displacement. Physical collision and field bounds apply. Placement revealed before both choices and cannot move on audible."},{"section":"Visuals","rule":"Transparent magenta rectangle, concentric rings and inward-flowing particles. Ball, routes and players stay readable."},{"section":"Progression / notes","rule":"Same dimensions and effect by form. Mastery controls life and cooldown only. Approved in chat all ten A."},{"section":"Ability story","rule":"Psyflutter senses the flow of a completed pass and folds the next defensive space inward, letting its Psychic family move freely through the bend."}]},{"id":"PSY-01-C","familyId":"mindwing","mode":"clash","name":"Mind Mend","category":"Signature action","activation":"On own normal action while active, able and ready, replace attack to donate own HP to an injured living teammate.","mechanic":"Mind Mend / Donate 10% of source maximum HP for Psyflutter or 15% for Psyraptor, plus mastery 0 / 2 / 4 / 6 percentage points. Restore one target HP per donated HP before applicable healing penalties. Limit donation to target missing HP and source current HP minus 1.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"On own normal action while active, able and ready, replace attack to donate own HP to an injured living teammate."},{"section":"Targets / placement","rule":"Lowest current HP-percentage injured living teammate including reserves, excluding self. Stable lineup ordering resolves equal percentages."},{"section":"Core resolution","rule":"Donate 10% of source maximum HP for Psyflutter or 15% for Psyraptor, plus mastery 0 / 2 / 4 / 6 percentage points. Restore one target HP per donated HP before applicable healing penalties. Limit donation to target missing HP and source current HP minus 1."},{"section":"Recharge / frequency","rule":"Four subsequent owner normal turns cooldown, paused in reserve. No eligible target or affordable positive donation preserves readiness and uses ordinary attack if able. Stunned source follows normal skip."},{"section":"Lifetime / persistence","rule":"Immediate donation and healing. Existing statuses remain. No ongoing schedule. State follows ordinary once-Clash boundaries, cooldown survives rotation."},{"section":"Exceptions / counterplay","rule":"HP cost cannot reduce source below 1 HP. Healing Reduced affects recipient normally. Donation does not cleanse, revive or generate surplus shield. Final rounding uses shared-system approved convention when reconciled."},{"section":"Visuals","rule":"Glowing orb leaves source chest. Source HP falls, then teammate HP rises. No new status badge."},{"section":"Progression / notes","rule":"Effective donation percentages by mastery: Psyflutter 10 / 12 / 14 / 16; Psyraptor 15 / 17 / 19 / 21. Archetype Support. Approved all ten A."},{"section":"Ability story","rule":"Psyflutter offers some of its own vitality so an injured teammate can return to the fight, accepting vulnerability to protect the team."}]},{"id":"PSY-02-F","familyId":"shadewisp","mode":"football","name":"Mirror Step","category":"Self enhancement","activation":"While ready and able on man coverage, assigned receiver first designated route cut before pass release can activate if in range.","mechanic":"Mirror Step / Psychically mirror receiver new route direction without ordinary turning slowdown, retaining current movement speed. Existing separation still must be covered with ordinary movement.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"While ready and able on man coverage, assigned receiver first designated route cut before pass release can activate if in range."},{"section":"Targets / placement","rule":"Assigned man receiver only. Wispira within 3 yards, Mirageist within 4 yards at cut. No zone coverage fallback."},{"section":"Core resolution","rule":"Psychically mirror receiver new route direction without ordinary turning slowdown, retaining current movement speed. Existing separation still must be covered with ordinary movement."},{"section":"Recharge / frequency","rule":"Cooldown 5 / 4 / 3 / 2 subsequent participating defensive plays by mastery after activation. No qualifying cut, out of range or unable source preserves readiness."},{"section":"Lifetime / persistence","rule":"One cut resolution only. No timed buff, status or ongoing attribute modification. Ordinary game persistence applies to running cooldown."},{"section":"Exceptions / counterplay","rule":"Normal bodies, walls, environmental movement penalties and existing immobilization apply. Only ordinary turning slowdown is bypassed. No teleport, collision bypass or guaranteed breakup."},{"section":"Visuals","rule":"Psychic ripple links receiver and cornerback briefly. Curved lavender afterimage marks the mirrored turn, with no extra actor or status badge."},{"section":"Progression / notes","rule":"Form improves range from 3 to 4 yards. Mastery changes cooldown. Approved all ten A. Family remains CB and Common through evolution."},{"section":"Ability story","rule":"Wispira listens to the receiver intent through a psychic connection, matching one sharp cut before ordinary footwork can slow it."}]},{"id":"PSY-02-C","familyId":"shadewisp","mode":"clash","name":"Mirage Veil","category":"Signature action","activation":"Two completed enemy direct normal attacks from same attacker damage source HP while active and ready. Resolve whole second attack and attached effects first. Must survive and remain able.","mechanic":"Mirage Veil / Attempt Guarded 25 / 30 / 35 / 40% reduction by mastery for 2 owner normal turns, application turn excluded. Normal shared status gate and same-status application rules apply.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Two completed enemy direct normal attacks from same attacker damage source HP while active and ready. Resolve whole second attack and attached effects first. Must survive and remain able."},{"section":"Targets / placement","rule":"Self Guarded attempt. Count whole attack once including multihit. A different attacker HP hit begins count 1 for new attacker. Miss and shield-only attack neither count nor reset."},{"section":"Core resolution","rule":"Attempt Guarded 25 / 30 / 35 / 40% reduction by mastery for 2 owner normal turns, application turn excluded. Normal shared status gate and same-status application rules apply."},{"section":"Recharge / frequency","rule":"Five subsequent owner normal turns cooldown, paused in reserve. No charging during cooldown. A qualifying attempt spends readiness even if status blocked. Unable source preserves readiness, discards trigger and queues no application."},{"section":"Lifetime / persistence","rule":"Enemy attacker departure resets same-attacker progress. Guarded duration and cooldown pause in reserve under shared rules. Guarded clears on football entry per existing unsupported-mode policy."},{"section":"Exceptions / counterplay","rule":"Protection begins only after triggering attack resolves, never prevents that attack lethal damage. No new shield pool, decoy evasion or retaliation."},{"section":"Visuals","rule":"Two faint psychic outlines gather after qualifying attacks and merge into protective veil. Standard Guarded badge displays."},{"section":"Progression / notes","rule":"Both forms share rules and mastery values. Approved Support to Tank change for whole family. Permanent ratings supply evolution durability difference."},{"section":"Ability story","rule":"Wispira learns the rhythm of repeated strikes and wraps itself in a veil tuned to survive the next assault."}]},{"id":"PSY-03-F","familyId":"cerebrix","mode":"football","name":"Foresight","category":"Targeted effect","activation":"Before either side selects plays while ready, randomly mark one initially aligned opposing LB within 3 yards of LOS. Both sides see candidate. At snap validate marked defender actually blitzes.","mechanic":"Foresight / If marked LB blitzes and Cerebrix able, roll fixed 50% chance to apply Confused. Success attempts 20% effective Awareness reduction for current play with normal shared status-slot rules. Application chance and penalty magnitude are separate.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Before either side selects plays while ready, randomly mark one initially aligned opposing LB within 3 yards of LOS. Both sides see candidate. At snap validate marked defender actually blitzes."},{"section":"Targets / placement","rule":"N9d: before both calls, choose and save one opposing LB within 3 yards of LOS in the initial visible formation. The initial look is locked once per snap. At snap validate that same monster is participating and actually blitzes; no substitute or reload/audible/redraw reroll. No future call alignment is read. Preserve the fixed 50% Confused attempt, 20% Awareness reduction and approved cooldown.","ruling":"N9d","supersededRule":"Only marked LB. No future defensive choice inspection, substitute target or new audible selection. Keep same candidate through audibles and use final assignment at snap."},{"section":"Core resolution","rule":"If marked LB blitzes and Cerebrix able, roll fixed 50% chance to apply Confused. Success attempts 20% effective Awareness reduction for current play with normal shared status-slot rules. Application chance and penalty magnitude are separate."},{"section":"Recharge / frequency","rule":"Cooldown 6 / 5 / 4 / 3 subsequent participating offensive plays by mastery. Spend on eligible cast whether 50% roll succeeds, fails or existing status blocks. No eligible blitz or unable source preserves readiness."},{"section":"Lifetime / persistence","rule":"Current-play Confused expires whistle. Candidate seeded/saved before choices. Ordinary charge/cooldown game persistence applies."},{"section":"Exceptions / counterplay","rule":"Can activate on run or pass if candidate blitzes. No automatic wrong direction, stun, forced pass or guaranteed protection. Different status blocks, same status follows shared stronger/equal policy."},{"section":"Visuals","rule":"Psychic eye above Cerebrix and lavender floor marker under warned LB. Standard Confused badge after accepted application."},{"section":"Progression / notes","rule":"Fixed 50% application roll and 20% Awareness reduction, all mastery. Mastery improves cooldown. Owner explicitly replaced original guaranteed attempt with 50% gamble."},{"section":"Ability story","rule":"Cerebrix warns one linebacker that it has seen the rush coming. The defender must decide whether the blitz is worth the risk, while the offense cannot count on the prediction working."}],"ruling":"N9d"},{"id":"PSY-03-C","familyId":"cerebrix","mode":"clash","name":"Foresight","category":"Signature action","activation":"Once per Clash, spend own normal action while active and able to prepare psychic mirror, replacing attack. Once-use spent on preparation.","mechanic":"Foresight / Prevent incoming status and redirect one application to its caster with same strength and proposed duration. Caster ordinary status eligibility applies, with no second application accuracy roll. If caster cannot receive, incoming application still prevented and mirror consumed.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Once per Clash, spend own normal action while active and able to prepare psychic mirror, replacing attack. Once-use spent on preparation."},{"section":"Targets / placement","rule":"Source only. Intercept next successful enemy ability-applied harmful-status roll before source shared slot check. Exclude reflected applications and environmental effects."},{"section":"Core resolution","rule":"Prevent incoming status and redirect one application to its caster with same strength and proposed duration. Caster ordinary status eligibility applies, with no second application accuracy roll. If caster cannot receive, incoming application still prevented and mirror consumed."},{"section":"Recharge / frequency","rule":"One preparation per Clash. Mirror lasts 2 / 2 / 3 / 3 owner normal turns by mastery, preparation turn excluded. Source inability before preparation preserves use."},{"section":"Lifetime / persistence","rule":"Rotation or knockout clears mirror; once-use stays spent through rotations/revival. Existing source status remains and does not block preparing/intercepting. Mirror clears after one interception, expiry or Clash end."},{"section":"Exceptions / counterplay","rule":"Attack damage resolves normally. Source must survive and remain able to reflect. No reflected-effect bounce or extra riders copied. No new shared status slot or badge."},{"section":"Visuals","rule":"Floating psychic eye opens on preparation. Lavender mirror catches harmful-status symbol and returns it, then shatters. Prepared indicator lives beside ability icon."},{"section":"Progression / notes","rule":"Archetype Disruptor retained. Prepared duration is only mastery scaling. All twelve A approved."},{"section":"Ability story","rule":"Cerebrix sees an incoming affliction before it takes hold and places a psychic mirror in its path, turning the opponent plan back toward its caster."}]},{"id":"PSY-04-F","familyId":"echolot","mode":"football","name":"Echo Landing","category":"Zone","activation":"Own legal kickoff caught in field of play and returned without touchdown while ready banks next opposing offensive scrimmage Psychic field. Touchback, out-of-bounds kick and return touchdown give no reward.","mechanic":"Echo Landing / Standard Psychic field: both teams non-Psychic inward pull 20% applicable maximum speed, 1-yard center deadband, same-type neutrality. Echolot can be benched when pending field appears.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Own legal kickoff caught in field of play and returned without touchdown while ready banks next opposing offensive scrimmage Psychic field. Touchback, out-of-bounds kick and return touchdown give no reward."},{"section":"Targets / placement","rule":"6 yards wide by 8 yards long, extending from upcoming LOS into offensive backfield, centered laterally on initial opposing QB. Shift only enough to fit field-of-play boundaries."},{"section":"Core resolution","rule":"Standard Psychic field: both teams non-Psychic inward pull 20% applicable maximum speed, 1-yard center deadband, same-type neutrality. Echolot can be benched when pending field appears."},{"section":"Recharge / frequency","rule":"Six subsequent team defensive scrimmage plays cooldown after creation, counting while kicker benched. Maximum one pending field."},{"section":"Lifetime / persistence","rule":"Life 1 / 2 / 2 / 3 defensive scrimmage plays by mastery including creation and incomplete passes. Kickoff consumes no life. Pending survives possessions/half, created zone clears half. Stationary after creation."},{"section":"Exceptions / counterplay","rule":"Reveal before both choices. Audibles do not reposition zone. Ordinary collision and boundaries, no altered kick physics or guaranteed return stop. Source bench does not prevent creation."},{"section":"Visuals","rule":"Psychic ripples beneath ball at return end reform into magenta backfield rectangle before next play choices. Zone does not remain at kickoff landing spot."},{"section":"Progression / notes","rule":"Mastery improves created lifetime only. All eleven A approved. Approved K reassignment retained."},{"section":"Ability story","rule":"Echolot hears the final echo of a returned kick and folds it into the opponent backfield, trading the safety of a touchback for a chance to disturb the next drive."}]},{"id":"PSY-04-C","familyId":"echolot","mode":"clash","name":"Echo Strike","category":"Signature action","activation":"Ready own normal action uses stored latest positive direct enemy HP hit. Each individual hit of a multihit attack replaces memory, leaving last qualifying hit.","mechanic":"Echo Strike / One attack with 100% normal damage plus 35 / 50 / 65 / 80% stored HP damage by mastery. Bonus capped at 15% target maximum HP before normal evasion/type/Guarded/shield defenses apply to combined budget.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Ready own normal action uses stored latest positive direct enemy HP hit. Each individual hit of a multihit attack replaces memory, leaving last qualifying hit."},{"section":"Targets / placement","rule":"Current active enemy. Store most recent qualifying individual actual HP damage, not maximum or sum. Exclude DOT, self damage and shield-absorbed damage."},{"section":"Core resolution","rule":"One attack with 100% normal damage plus 35 / 50 / 65 / 80% stored HP damage by mastery. Bonus capped at 15% target maximum HP before normal evasion/type/Guarded/shield defenses apply to combined budget."},{"section":"Recharge / frequency","rule":"Five subsequent owner normal turns cooldown, paused reserve. New qualifying hits update memory during cooldown. Consume memory on launch even if evaded. No memory or unable source preserves readiness; ordinary attack/skip as applicable."},{"section":"Lifetime / persistence","rule":"Memory survives rotation in same Clash. Clear on knockout, football entry or actual Clash end. No extra action or immediate retaliation."},{"section":"Exceptions / counterplay","rule":"Ordinary eligible damage rules apply. This is one enhanced normal attack, not separate bonus hit. Shared ordinary-only perk policy remains subject to final global reconciliation."},{"section":"Visuals","rule":"Psychic outline replays latest impact behind source, then launches vibrating sonic ring toward opponent."},{"section":"Progression / notes","rule":"Balanced retained. Stored-hit factor 35 / 50 / 65 / 80%, cap fixed 15% target maxHP. All twelve A approved."},{"section":"Ability story","rule":"Echolot remembers the last blow it heard through its own body and returns that echo in its next strike. A smaller follow-up hit can quiet the memory."}]},{"id":"PSY-05-F","familyId":"enigmane","mode":"football","name":"Mind Game","category":"Targeted effect","activation":"Four participating offensive plays in which Enigmane does not receive the ball fill a four-segment charge bar. Owner approved charge basis and play-long decoy chase. Working draft counts nonconsecutive scrimmage plays without reception, including runs and incomplete targets.","mechanic":"Guaranteed psychic afterimage continues original route direction. Assigned defender chases until anyone catches football including an interception or whistle, whichever first. Then resumes ordinary behavior from its current position. Existing immobilization still constrains movement. Spend full bar on valid activation. No separate chance roll or cooldown. Activation play cannot earn charge, following participating plays can. Maximum one full bar.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Four participating offensive scrimmage plays without receiving ball fill bar. Plays can be nonconsecutive. A reception pauses partial progress. Runs, throws to teammates and incomplete targets qualify if source participates and has no reception."},{"section":"Targets / placement","rule":"On next charged first designated route cut before pass release, assigned man defender must be within2 yards. Target that defender only. No legal opportunity preserves readiness."},{"section":"Core resolution","rule":"Guaranteed psychic afterimage continues original route direction. Assigned defender chases until anyone catches football including an interception or whistle, whichever first. Then resumes ordinary behavior from its current position. Existing immobilization still constrains movement."},{"section":"Recharge / frequency","rule":"Spend full bar on valid activation. No separate chance roll or cooldown. Activation play cannot earn charge, following participating plays can. Maximum one full bar."},{"section":"Lifetime / persistence","rule":"Charge partial/full persists possessions, halftime and overtime until actual game end. Afterimage chase ends catch/whistle, not after a second-based timer."},{"section":"Exceptions / counterplay","rule":"Other defenders still cover real source. Ability effect uses no shared status slot. Physical movement constraints remain. Image carries no football and does not create a second roster monster. Afterimage safe-path representation and other-control priority need implementation audit."},{"section":"Visuals","rule":"Visible psychic copy continues straight while real Enigmane cuts. Four-segment charge alternates with status badge using shared UI. Real ball and controlled-monster indicators remain accurate."},{"section":"Progression / notes","rule":"All recommended secondary rules resolved by owner closeout2–4. Four-play nonconsecutive charge, guaranteed2-yard man-cut activation and no extra cooldown. No unapproved mastery scaling."},{"section":"Ability story","rule":"Every time the ball goes somewhere else, Enigmane thinks it was not open enough. After four qualifying plays, its psychic mind sends a copy forward and lets the real tight end break away."}]},{"id":"PSY-05-C","familyId":"enigmane","mode":"clash","name":"Mind Game","category":"Signature action","activation":"Direct enemy normal attack missing source completely earns one trick. Every hit of multihit attack must miss. Reactions cannot earn trick.","mechanic":"Mind Game / Next performed normal attack consumes trick on launch even miss. Connected hit, including shield-absorbed hit, attempts Confused under usual slot rules. Base attack normal damage, Confused 25% self-side redirect chance.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Direct enemy normal attack missing source completely earns one trick. Every hit of multihit attack must miss. Reactions cannot earn trick. While no trick is stored, each enemy normal attack against the active Enigmane has an explicit 15% chance to strike an afterimage and miss entirely (one roll for the whole attack); explicitly undodgeable attacks bypass it without a roll.","ruling":"N7b P10","supersededRule":"Direct enemy normal attack missing source completely earns one trick. Every hit of multihit attack must miss. Reactions cannot earn trick."},{"section":"Targets / placement","rule":"Next normal attack intended active enemy. Maximum one stored trick. No extra cooldown."},{"section":"Core resolution","rule":"Next performed normal attack consumes trick on launch even miss. Connected hit, including shield-absorbed hit, attempts Confused under usual slot rules. Base attack normal damage, Confused 25% self-side redirect chance."},{"section":"Recharge / frequency","rule":"No charge accumulation beyond one. No extra normal attack. Once launched trick spent even status blocked or evaded."},{"section":"Lifetime / persistence","rule":"Confused 1 / 2 / 2 / 3 recipient normal turns by mastery, application turn excluded under shared rules. Stored trick persists reserve, clears knockout/Clash end. Existing status mode carry applies."},{"section":"Exceptions / counterplay","rule":"No extra accuracy roll for application once hit connects, only shared eligibility. Exact enhanced/ordinary archetype policy follows final shared reconciliation."},{"section":"Visuals","rule":"Purple afterimage flashes where missed attack landed to signal stored trick. Next hit sends ghostly grin past enemy, standard Confused badge on acceptance."},{"section":"Progression / notes","rule":"Disruptor retained. All seven A approved. Duration varies, fixed 25% redirect chance at every tier."},{"section":"Ability story","rule":"Enigmane notices the opponent swinging at empty space and saves that mistake. Its next attack turns the remembered opening into a second deception."}],"ruling":"N7b P10","values":{"afterimageMissPct":15}},{"id":"PSY-06-F","familyId":"astralux","mode":"football","name":"Blink","category":"Special action","activation":"Once per game, after 8 net rushing yards on current rushing play, first new tackle attempt arms and triggers teleport if source able. Handoffs and pitches qualify. No reception or kick return.","mechanic":"Blink / Teleport source and carried football through player bodies to clear landing. Solid walls/environmental obstacles block swept path. Successful relocation avoids triggering tackle; normal pursuit and subsequent tackle attempts resume at destination.","designStatus":"Approved design; implementation and interaction audit pending","details":[{"section":"Trigger / eligibility","rule":"Once per game, after 8 net rushing yards on current rushing play, first new tackle attempt arms and triggers teleport if source able. Handoffs and pitches qualify. No reception or kick return."},{"section":"Targets / placement","rule":"Destination 5 / 6 / 7 / 8 yards by mastery straight toward offensive endzone at same lateral coordinate. Clear legal landing required. Can reach goal line and score."},{"section":"Core resolution","rule":"Teleport source and carried football through player bodies to clear landing. Solid walls/environmental obstacles block swept path. Successful relocation avoids triggering tackle; normal pursuit and subsequent tackle attempts resume at destination."},{"section":"Recharge / frequency","rule":"Once game spent only successful teleport. Illegal path/landing preserves use, original tackle resolves and no further Blink attempt that play. Retain use state through halftime and overtime."},{"section":"Lifetime / persistence","rule":"Immediate relocation and authoritative rushing-yard credit once. Eight-yard threshold must be earned on current play. Source immobilized or already-resolving tackle prevents activation."},{"section":"Exceptions / counterplay","rule":"No sideways alternate landing search. Stunned and Knocked Down prevent. Other movement modifiers apply again after landing. Boundary and normal goal-line scoring rules apply."},{"section":"Visuals","rule":"Bright star collapses at origin and blooms destination. Dotted psychic trace shows football travel. Source story uses star-spirit future sight."},{"section":"Progression / notes","rule":"Owner increased original 2/3/4/5-yard distance to 5/6/7/8, allowed crossing player bodies and goal-line scoring. All twelve A approved."},{"section":"Ability story","rule":"Astralux runs toward a future it has already seen. When a defender reaches the place where it should be, Astralux has stepped into the next moment."}]},{"id":"PSY-06-C","familyId":"astralux","mode":"clash","name":"Astral Strike","category":"Signature action","activation":"Once per Clash while active and able, use own normal action to command every eligible living enemy reserve to basic-attack their own active teammate, then perform Astralux own attack.","mechanic":"Command enemy reserves to basic-attack own active at50/60/70/80%, Confused may self-hit. Ordinary defenses/passive survival apply, attack retaliations and chains suppressed. Then own100% attack.","designStatus":"Design approved and closeout recorded; implementation pending","details":[{"section":"Trigger / eligibility","rule":"Once per Clash while active and able, use own normal action to command every eligible living enemy reserve to basic-attack their own active teammate, then perform Astralux own attack."},{"section":"Targets / placement","rule":"Enemy reserve roster attacks initial enemy active. Stunned reserves cannot attack. Reserves stay reserve. Snapshot stable lineup order for deterministic sequence. No eligible reserve means ordinary Astralux attack and preserve signature."},{"section":"Core resolution","rule":"Each reserve one basic attack at 50 / 60 / 70 / 80% own normal damage by Astralux mastery. Apply normal accuracy/type/shield/damage defenses and applicable status/damage modifiers separately. After commands, Astralux performs 100% ordinary normal attack."},{"section":"Recharge / frequency","rule":"Once Clash use spent when first commanded attack launches even evaded. No extra signature cooldown or reserve signature usage. Commanded attacks cannot activate signatures, counters or extra-attack chains."},{"section":"Lifetime / persistence","rule":"Immediate ability sequence with no new shared status. If initial enemy active knocked out early, cancel remaining commands, perform ordinary replacement handling, then Astralux attacks replacement. If no living enemy remains, normal victory ends sequence."},{"section":"Exceptions / counterplay","rule":"Each commanded Confused reserve rolls its ordinary confusion chance. On misfire it attacks itself instead of own active teammate. No recursive confusion roll. Commanded attacks use ordinary shields, Guarded and passive survival effects. Attack retaliation and extra-attack chains remain suppressed. Resolve each whole attack before next commanded attacker. Stunned reserves cannot attack. Each remains in reserve, with no false active-entry effects."},{"section":"Visuals","rule":"Psychic threads connect Astralux to each enemy reserve. Violet eyes flash, reserves launch coordinated attacks, then Astralux emerges through astral doorway for final strike. No false active-entry events."},{"section":"Progression / notes","rule":"Striker retained. Commanded damage50/60/70/80%, own attack100%. Owner closeout5–6 resolves Confused self-hit and defenses. All ten original A remain applicable."},{"section":"Ability story","rule":"Astralux reaches into the minds waiting behind the frontline. For one coordinated strike they see their active teammate as the enemy, and Astralux joins the assault through an astral doorway."}]},{"id":"DRA-01-F","familyId":"drakeling","mode":"football","name":"Dragon Pounce","category":"Self enhancement","activation":"One successful ordinary juke or ordinary tackle break on current rushing attempt prepares pounce against next tackle attempt in same play. Exclude ability-guaranteed escapes from qualifying ordinary evasion.","mechanic":"Dragon Pounce / Replace that tackle-break contest with the ordinary contest plus 5 / 10 / 15 percentage points by Drakling / Drakyra / Dracolossus, plus mastery 0 / 3 / 6 / 9 points. Final success chance capped at 80%. Success breaks tackle. Failure continues normal successful-tackle resolution without a second ability reroll.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"One successful ordinary juke or ordinary tackle break on current rushing attempt prepares pounce against next tackle attempt in same play. Exclude ability-guaranteed escapes from qualifying ordinary evasion."},{"section":"Targets / placement","rule":"Source and next tackler. Handoffs and pitches qualify. Receiving and returns excluded."},{"section":"Core resolution","rule":"Replace that tackle-break contest with the ordinary contest plus 5 / 10 / 15 percentage points by Drakling / Drakyra / Dracolossus, plus mastery 0 / 3 / 6 / 9 points. Final success chance capped at 80%. Success breaks tackle. Failure continues normal successful-tackle resolution without a second ability reroll."},{"section":"Recharge / frequency","rule":"At most one pounce attempt per play, no inter-play cooldown. Pounce cannot charge itself."},{"section":"Lifetime / persistence","rule":"All per-play evasion/prepared state clears whistle. No carryover bar."},{"section":"Exceptions / counterplay","rule":"Existing movement restrictions prevent activation. No immunity window, teleport or added yards. Ordinary movement resumes after contest."},{"section":"Visuals","rule":"Crest glows after qualifying evasion. Short dragon-shaped burst accompanies next tackle contest within ordinary movement geometry."},{"section":"Progression / notes","rule":"Owner chose one evasion at all mastery, evolution bonuses 5/10/15 points and mastery bonus 0/3/6/9. Rarity Common at all forms."},{"section":"Ability story","rule":"Drakling gets more confident whenever a defender misses. It plants its claws and springs into the next challenge. Evolution turns that small burst of confidence into a dragon charge."}]},{"id":"DRA-01-C","familyId":"drakeling","mode":"clash","name":"Dragon Pounce","category":"Signature action","activation":"Ready own normal action may perform HP-cost enhanced attack if source able and can pay full cost while retaining at least 1 HP. Otherwise ordinary attack preserves readiness.","mechanic":"Dragon Pounce / Damage by form and mastery: Drakling 140/145/150/155%, Drakyra 155/160/165/170%, Dracolossus 170/175/180/185% of normal attack. Ordinary evasion/type/shields/reduction apply. Exclude ordinary-only Striker bonuses.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Ready own normal action may perform HP-cost enhanced attack if source able and can pay full cost while retaining at least 1 HP. Otherwise ordinary attack preserves readiness."},{"section":"Targets / placement","rule":"Current active enemy. Source pays 10% own maximum HP on launch."},{"section":"Core resolution","rule":"Damage by form and mastery: Drakling 140/145/150/155%, Drakyra 155/160/165/170%, Dracolossus 170/175/180/185% of normal attack. Ordinary evasion/type/shields/reduction apply. Exclude ordinary-only Striker bonuses."},{"section":"Recharge / frequency","rule":"Three subsequent owner normal turns cooldown, paused reserve. Full HP cost spent on launch even evaded or shield-absorbed. Source skipped action preserves HP/readiness."},{"section":"Lifetime / persistence","rule":"Immediate attack and payment. Cooldown state survives rotation under shared persistence rules. No extra attack."},{"section":"Exceptions / counterplay","rule":"Own Shielded and Guarded cannot reduce payment. Cost is resource debit, not enemy attack damage. Full cost required, source must retain 1 HP. Shared rounding must be reconciled before implementation."},{"section":"Visuals","rule":"Claws plant, bright outline gathers, then heavy dragon leap. HP cost appears at launch."},{"section":"Progression / notes","rule":"10% maximum-HP cost fixed all forms/mastery. Damage evolves and improves by mastery. Owner rejected original every-third-attack mechanic. Striker retained."},{"section":"Ability story","rule":"Drakling throws its whole body into the fight before learning to control its power. The effort wears it down. As it evolves, the same sacrifice produces a heavier strike."}]},{"id":"DRA-02-F","familyId":"wyrmkit","mode":"football","name":"Dragon Call","category":"Aura","activation":"Three participating offensive scrimmage plays fill bar. At next eligible offensive snap, automatically pulse. Activation play cannot recharge.","mechanic":"Dragon Call / Cleanse removable harmful shared statuses, retain beneficial and explicitly unremovable statuses, then grant protection against new harmful shared statuses for rest of current play. Protection follows snapshot recipients after leaving radius.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Three participating offensive scrimmage plays fill bar. At next eligible offensive snap, automatically pulse. Activation play cannot recharge."},{"section":"Targets / placement","rule":"Snapshot everyone within initial radius, source, allies and opponents included. Wyrmlet 3 yards, Ouroborn 5 yards."},{"section":"Core resolution","rule":"Cleanse removable harmful shared statuses, retain beneficial and explicitly unremovable statuses, then grant protection against new harmful shared statuses for rest of current play. Protection follows snapshot recipients after leaving radius."},{"section":"Recharge / frequency","rule":"Full bar spent on activation. Recharge from following participating play. Partial/full bar survives possessions, halftime and overtime, clears actual game end."},{"section":"Lifetime / persistence","rule":"Immunity ends whistle. Source can activate while Stunned and cleanse its removable harmful status. No second shared-status slot is created."},{"section":"Exceptions / counterplay","rule":"Environmental zone modifiers continue. Daybreak wandering and Sovereign Arm capture still apply because they are ability-specific effects. A retained unremovable harmful status remains even while new harmful applications are prevented."},{"section":"Visuals","rule":"Golden pulse expands from dragon. Removed badges crack and disappear. Protected recipients have subtle gold outline until whistle."},{"section":"Progression / notes","rule":"Radius 3/5 by evolution, fixed charge 3 plays. No unapproved mastery scaling. Aura with snap-time pulse. Owner replaced Coil Screen and unapproved Coil Guard."},{"section":"Ability story","rule":"Wyrmlet call steadies everyone nearby, clearing harmful effects from bodies and minds. Ouroborn stronger voice carries that protection farther across the field."}]},{"id":"DRA-02-C","familyId":"wyrmkit","mode":"clash","name":"Coil Renewal","category":"Signature action","activation":"Every third performed normal-action attack with positive direct enemy HP damage triggers ally healing. Reaction attacks do not progress. Shield-only/miss does not progress.","mechanic":"Coil Renewal / Heal target for 25% / 35% of actual HP damage dealt by Wyrmlet / Ouroborn triggering attack. Cap at 8/10/12/14% target maximum HP by mastery. Multihit counts whole attack once and sums actual HP lost. Exclude shield absorption and overkill.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Every third performed normal-action attack with positive direct enemy HP damage triggers ally healing. Reaction attacks do not progress. Shield-only/miss does not progress."},{"section":"Targets / placement","rule":"Other injured living ally with lowest HP percentage, including reserve, never self. Stable lineup ties."},{"section":"Core resolution","rule":"Heal target for 25% / 35% of actual HP damage dealt by Wyrmlet / Ouroborn triggering attack. Cap at 8/10/12/14% target maximum HP by mastery. Multihit counts whole attack once and sums actual HP lost. Exclude shield absorption and overkill."},{"section":"Recharge / frequency","rule":"One trigger every three qualifying attacks, no extra cooldown. Trigger resets count even if no injured teammate available."},{"section":"Lifetime / persistence","rule":"Count survives rotation, pauses reserve and clears actual Clash end. Immediate healing, ordinary healing penalties and HP maximum apply."},{"section":"Exceptions / counterplay","rule":"No revive or surplus shield. Trigger attack ordinary damage. Support archetype approved for both forms."},{"section":"Visuals","rule":"Three segments fill beside icon. Triggering impact sends green-gold energy into a coil around chosen ally."},{"section":"Progression / notes","rule":"Form healing transfer 25/35%, mastery cap 8/10/12/14%. Owner all twelve A. Balanced to Support."},{"section":"Ability story","rule":"Wyrmlet gathers the energy of its strikes into a glowing coil. The third qualifying strike sends that energy to a wounded teammate. Ouroborn channels more of the impact into recovery."}]},{"id":"DRA-03-F","familyId":"sablewing","mode":"football","name":"Hoard Flight","category":"Special action","activation":"Any valid fumble Sablewing recovers on a defensive scrimmage play triggers flight, regardless of who forced fumble. Not restricted to own forced fumbles.","mechanic":"Hoard Flight / End live return and place next offense at opponent 35. If recovery already at better field position, preserve better recovery spot. Preserve already-earned touchdown. Validate actual recovery ownership before applying placement.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Any valid fumble Sablewing recovers on a defensive scrimmage play triggers flight, regardless of who forced fumble. Not restricted to own forced fumbles."},{"section":"Targets / placement","rule":"Sablewing and recovered football. Use opponent goal direction to identify opponent 35-yard line."},{"section":"Core resolution","rule":"End live return and place next offense at opponent 35. If recovery already at better field position, preserve better recovery spot. Preserve already-earned touchdown. Validate actual recovery ownership before applying placement."},{"section":"Recharge / frequency","rule":"Every qualifying recovery, no extra cooldown or game-use limit. Special teams excluded."},{"section":"Lifetime / persistence","rule":"Flight ends play, then offense prepares normally at awarded spot. No temporary roster actor or status effect."},{"section":"Exceptions / counterplay","rule":"No interception trigger or lateral transfer. Exact permanent Tackling/base/ceiling and lower Coverage ceiling to be authored comparing all CBs. Re-audit actual forced-fumble attribute consumers before assigning final ratings."},{"section":"Visuals","rule":"Sablewing clutches recovered ball, launches into flight and lands at opponent 35 before offense enters. Preserve clear possession and spot indicator."},{"section":"Progression / notes","rule":"No invented mastery scaling. Special action. Owner 1B, remaining A. Wing Shadow, Wing Signal and Dragon Relay rejected/superseded."},{"section":"Ability story","rule":"Sablewing sees a loose football as treasure. Once it claims the prize, its hoarding instinct takes over and it carries that treasure deep into enemy territory."}]},{"id":"DRA-03-C","familyId":"sablewing","mode":"clash","name":"Wing Shelter","category":"Signature action","activation":"While active, after surviving complete direct enemy attack removing at least 20% own maximum HP, trigger if ready. Automatic even Stunned.","mechanic":"Wing Shelter / After damage and attached effects finish, restore 4/6/8/10% own maximum HP by mastery, subject to ordinary Healing Reduced and maximum HP.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"While active, after surviving complete direct enemy attack removing at least 20% own maximum HP, trigger if ready. Automatic even Stunned."},{"section":"Targets / placement","rule":"Self only, active fighter only. Sum actual HP damage over multihit whole attack and trigger once."},{"section":"Core resolution","rule":"After damage and attached effects finish, restore 4/6/8/10% own maximum HP by mastery, subject to ordinary Healing Reduced and maximum HP."},{"section":"Recharge / frequency","rule":"Three subsequent owner normal turns cooldown after reaction, first decrement next owner turn. Reserve pauses. Automatic recovery preserves normal action."},{"section":"Lifetime / persistence","rule":"Immediate self heal. Counter/state persists rotation under shared rules. Lethal attack cannot trigger recovery."},{"section":"Exceptions / counterplay","rule":"Exclude shield absorption, damage over time and self damage. No protection before lethal/attached effects finish. Balanced archetype owner approved."},{"section":"Visuals","rule":"Wings close around body, then green-gold restorative pulse appears and HP rises."},{"section":"Progression / notes","rule":"Threshold 20% maximum HP fixed, healing4/6/8/10%. Disruptor to Balanced."},{"section":"Ability story","rule":"Sablewing guards its remaining strength as fiercely as its treasure. After a heavy blow, it folds its wings around itself and releases a restorative pulse beneath its scales."}]},{"id":"DRA-04-F","familyId":"scaleguard","mode":"football","name":"Dragon Stomp","category":"Special action","activation":"Three participating offensive plays finishing engaged in block fill charge bar. Next offensive play engaging eligible DL triggers stomp while source able.","mechanic":"Dragon Stomp / Spectral dragon foot guarantees Pancaked attempt, subject to shared status eligibility. Pancake outcome applies existing Knocked Down status for remainder of current play under approved global timing revision.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Three participating offensive plays finishing engaged in block fill charge bar. Next offensive play engaging eligible DL triggers stomp while source able."},{"section":"Targets / placement","rule":"DL personally blocked by Scalor. Uses existing one-pancake-attempt-per-play budget."},{"section":"Core resolution","rule":"Spectral dragon foot guarantees Pancaked attempt, subject to shared status eligibility. Pancake outcome applies existing Knocked Down status for remainder of current play under approved global timing revision."},{"section":"Recharge / frequency","rule":"Full bar spent on stomp attempt even if status blocked. Activation play cannot recharge. Unable source or no eligible DL preserves. If pancake budget already spent, no additional attempt. Partial/full bar survives possessions/half/OT until actual game end."},{"section":"Lifetime / persistence","rule":"Knockdown ends whistle. No new status identity or seconds-based pancake duration. Existing contact, movement and blocking rules resume when restored next play."},{"section":"Exceptions / counterplay","rule":"Only charge from completed participating offensive plays finishing engaged. No charge from mere lineup presence. No second normal pancake attempt following stomp."},{"section":"Visuals","rule":"Giant dragon-foot shadow forms beneath target, then spectral foot slams and flattens defender with existing Knocked Down indicator."},{"section":"Progression / notes","rule":"Threshold3, once-play pancake budget. No invented mastery scaling. Owner chose 1B and remaining A. Replaces recovery and challenge drafts."},{"section":"Ability story","rule":"Scalor carries the weight of ancient dragons in its scales. After holding the line long enough, it calls down an ancestor mighty step."}]},{"id":"DRA-04-C","familyId":"scaleguard","mode":"clash","name":"Dragonhide","category":"Signature action","activation":"First active entry once per Clash attempts own Guarded 20/25/30/35% for2 owner normal turns, application turn excluded. Existing different status blocks and spends entry opportunity.","mechanic":"Dragonhide / Convert full Guarded percentage into damage bonus: attack120/125/130/135% normal. Ordinary evasion/type/shields/reduction apply, ordinary-only archetype attack bonuses excluded.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"First active entry once per Clash attempts own Guarded 20/25/30/35% for2 owner normal turns, application turn excluded. Existing different status blocks and spends entry opportunity."},{"section":"Targets / placement","rule":"Self original Dragonhide Guarded episode only. On own normal action in final remaining protected turn, consume it for enhanced attack against current active enemy."},{"section":"Core resolution","rule":"Convert full Guarded percentage into damage bonus: attack120/125/130/135% normal. Ordinary evasion/type/shields/reduction apply, ordinary-only archetype attack bonuses excluded."},{"section":"Recharge / frequency","rule":"One entry application attempt and at most one conversion per Clash. Consumed protection stays spent even if attack evaded. Rotation/revival do not grant fresh application."},{"section":"Lifetime / persistence","rule":"Reserve pauses Guarded. Removal/replacement loses conversion opportunity. Unable conversion turn follows normal skip/status decrement. If Guarded expires, no queued bonus."},{"section":"Exceptions / counterplay","rule":"Only original owned Guarded eligible, not external replacement. Conversion replaces normal attack. No extra action, shield pool or healing."},{"section":"Visuals","rule":"Hardened scales form at entry with Guarded badge. At conversion scales peel away and gather on claws, badge disappears as attack launches."},{"section":"Progression / notes","rule":"Owner changed original half conversion to full Guarded percentage and timing to final protected turn. Balanced retained. Original redundant four-turn conversion cooldown superseded by once-original-episode limit."},{"section":"Ability story","rule":"Scalor hardens its scales on entering battle. As protection nears its end, it gathers those scales around its claws and drives them into a final heavy strike."}]},{"id":"DRA-05-F","familyId":"vyrnax","mode":"football","name":"Dragon Roar","category":"Special action","activation":"Player chooses one field-goal attempt per game to activate before kick. Eligible chosen attempt up to90 yards. Canceled before launch preserves use.","mechanic":"Dragon Roar / Exact activated success chart all mastery:90yd30%,85yd40%,80yd45%,75yd50%,70yd55%,65yd or less100%. Smooth linear interpolation between listed distances. Supplies sufficient range up to90 and uses chart directly.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Player chooses one field-goal attempt per game to activate before kick. Eligible chosen attempt up to90 yards. Canceled before launch preserves use."},{"section":"Targets / placement","rule":"Own kicker and selected actual FG attempt. Extra points/punts/kickoffs follow ordinary rules."},{"section":"Core resolution","rule":"Exact activated success chart all mastery:90yd30%,85yd40%,80yd45%,75yd50%,70yd55%,65yd or less100%. Smooth linear interpolation between listed distances. Supplies sufficient range up to90 and uses chart directly."},{"section":"Recharge / frequency","rule":"Once per game spent on activated kick launch whether made/missed. Preserve spent state halftime/OT. Other kicks use ordinary calculations."},{"section":"Lifetime / persistence","rule":"One actual kick at real distance. Record actual FG distance and result. No retry, fake short distance, new field or shared status."},{"section":"Exceptions / counterplay","rule":"Chart replaces original distance-relief/floor/automatic45-yard proposal. Exact percentages fixed all mastery. Normal activation availability required. Above90 outside this signature chart."},{"section":"Visuals","rule":"Vyrnax roar summons spectral dragon coiling around football and following kick toward uprights. Clear pre-kick activation indicator."},{"section":"Progression / notes","rule":"Player-selected once-game custom curve explicitly approved, supplied power range. Curve values must be exact and stored as data. No invented mastery bonus."},{"section":"Ability story","rule":"Vyrnax gathers its breath and sends a dragon roar downfield. A spectral dragon coils around the football, carrying the force of the roar toward distant uprights."}]},{"id":"DRA-05-C","familyId":"vyrnax","mode":"clash","name":"Dragon Roar","category":"Signature action","activation":"First performed normal attack each Clash, even later active entry, becomes enhanced roar. Support actions and Stunned skips preserve first-attack opportunity.","mechanic":"Dragon Roar / Attack120/130/140/150% normal by mastery. Connected hit guarantees application attempt with normal shared gate, no separate accuracy roll. Weakened reduces outgoing damage15% for2 recipient normal turns, application turn excluded.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"First performed normal attack each Clash, even later active entry, becomes enhanced roar. Support actions and Stunned skips preserve first-attack opportunity."},{"section":"Targets / placement","rule":"Current enemy active. Connected hit including shield absorption attempts Weakened."},{"section":"Core resolution","rule":"Attack120/130/140/150% normal by mastery. Connected hit guarantees application attempt with normal shared gate, no separate accuracy roll. Weakened reduces outgoing damage15% for2 recipient normal turns, application turn excluded."},{"section":"Recharge / frequency","rule":"Once opening strike per Clash spent on launch even evaded or status blocked. Rotation/revival do not refresh."},{"section":"Lifetime / persistence","rule":"Remaining Weakened turns carry to participating football plays as15% Strength reduction under normal 1:1 carry."},{"section":"Exceptions / counterplay","rule":"Ordinary evasion/type/shields/reduction. Exclude ordinary-only Striker bonuses. 15% is status magnitude, not application probability."},{"section":"Visuals","rule":"Focused dragon-shaped sound wave strikes active target. Standard cracked-fist badge on accepted Weakened."},{"section":"Progression / notes","rule":"Attack120/130/140/150%, Weakened15% fixed2turns. Striker retained."},{"section":"Ability story","rule":"Vyrnax announces its arrival with a roar that shakes the opponent confidence. The first blast leaves its target struggling to put full strength behind the answer."}]},{"id":"DRA-06-F","familyId":"aurodrax","mode":"football","name":"Sovereign Arm","category":"Special action","activation":"Three consecutive completed passes each meet12/10/8/6 net yards by mastery, including YAC. Any participating offensive scrimmage play without qualifying completion, including run, sack, incomplete, INT or short completion, resets streak.","mechanic":"Sovereign Arm / Protected pass otherwise intercepted becomes incomplete. Dragon swallows defender. Defender misses next one scrimmage play by Aurodrax team offense, position vacant with no substitute, then returns to ordinary formation before following play. Preserve pending absence across intervening possession change.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Three consecutive completed passes each meet12/10/8/6 net yards by mastery, including YAC. Any participating offensive scrimmage play without qualifying completion, including run, sack, incomplete, INT or short completion, resets streak."},{"section":"Targets / placement","rule":"Next own released forward pass protected once per game. Would-be intercepting defender captured by spectral dragon before interception possession/stats finalize."},{"section":"Core resolution","rule":"Protected pass otherwise intercepted becomes incomplete. Dragon swallows defender. Defender misses next one scrimmage play by Aurodrax team offense, position vacant with no substitute, then returns to ordinary formation before following play. Preserve pending absence across intervening possession change."},{"section":"Recharge / frequency","rule":"One protected throw per game spent on release even no INT. Run/sack/canceled throw before release preserves charged throw but normal uncharged streak rules still apply. Partial/charged/use/capture state survives possessions, halftime and overtime until actual game end."},{"section":"Lifetime / persistence","rule":"Absence served only on next same-team offensive scrimmage play, not special teams. Defender status durations pause while absent. Return follows served play. No injury or new shared status."},{"section":"Exceptions / counterplay","rule":"Capture works regardless of defender slot and despite Dragon Call harmful-status protection. Other pass outcomes ordinary. Live defender availability ledger must be separate from roster membership. No game-end missing player."},{"section":"Visuals","rule":"Golden seal follows football. On prevented interception seal becomes dragon mouth swallowing defender, ball drops incomplete. Portrait dragon-mouth indicator while unavailable, return animation before formation."},{"section":"Progression / notes","rule":"One protected throw, not original proposed3. Streak requires consecutive qualifying completions, user1B2B. Yardage12/10/8/6 by mastery. No automatic completion."},{"section":"Ability story","rule":"Aurodrax seal treats an interception as a challenge to royal command. An ancestral dragon answers by swallowing the challenger and carrying them away for one offensive play."}]},{"id":"DRA-06-C","familyId":"aurodrax","mode":"clash","name":"Sovereign Balance","category":"Signature action","activation":"Own ready normal action selects branch from source HP at action commitment. Above50% HP attacks, at50% or below prepares Guarded if shared slot empty.","mechanic":"Sovereign Balance / HighHP attack130/140/150/160% normal. LowHP replaces attack with Guarded25/30/35/40% for2 owner normal turns, application turn excluded. LowHP occupied slot performs ordinary attack and preserves readiness.","designStatus":"Owner approved; implementation and balance audit pending","details":[{"section":"Trigger / eligibility","rule":"Own ready normal action selects branch from source HP at action commitment. Above50% HP attacks, at50% or below prepares Guarded if shared slot empty."},{"section":"Targets / placement","rule":"HighHP targets current enemy active. LowHP targets self."},{"section":"Core resolution","rule":"HighHP attack130/140/150/160% normal. LowHP replaces attack with Guarded25/30/35/40% for2 owner normal turns, application turn excluded. LowHP occupied slot performs ordinary attack and preserves readiness."},{"section":"Recharge / frequency","rule":"Five subsequent owner normal turns shared cooldown for either branch, paused reserve. Repeatable. Enhanced attack miss spends. Unable source preserves readiness."},{"section":"Lifetime / persistence","rule":"Guarded reserve pause and unsupported football clear follow existing policy. HighHP attack no lingering payload. HP changes before commitment determine branch."},{"section":"Exceptions / counterplay","rule":"Ordinary evasion/type/shields/reduction, exclude ordinary-only archetype bonuses. No cleanse/overwrite or separate branch cooldowns."},{"section":"Visuals","rule":"Crown gold for dragon silhouette attack, silver for spectral wing protection. Standard Guarded badge only."},{"section":"Progression / notes","rule":"HP threshold50%, attack130/140/150/160%, Guarded25/30/35/40%, shared5turn cooldown. Balanced retained."},{"section":"Ability story","rule":"Aurodrax rules through strength while it holds the advantage. Wounded, it folds ancestral wings around itself to withstand the assault. Its crown shifts from gold to silver with its priorities."}]}];
